    "a9.lede": "تعرض Chatfuel أسعار الاشتراكات والأرصدة الشهرية، بينما قد يعتمد استهلاك الذكاء الاصطناعي وWhatsApp على الاستخدام. تفصل هذه اللقطة المؤرخة بين أرقام الخطة المنشورة والتكاليف التي تحتاج إلى مراجعة المحفظة والفاتورة. لا نفترض هامشًا موحدًا أو تكلفة ثابتة لكل رد.",
