    "a8.t3": "رسوم Meta لـ2,000 رسالة تسويق مسلّمة لمصر",
    "a8.t3a": "128.80$ على سعر Meta المنشور 0.0644$ بالدولار",
    "a8.t3b": "حساب على سعر Meta وحده؛ لا يشمل رسوم المنصة أو المزوّد أو الضرائب",
    "a8.t3c": "غير مطبق في هذا الجدول",
    "a8.t4": "رقم دليل WhatsApp لدى ManyChat",
    "a8.t4a": "0.0740$ لرسالة تسويق لمصر في دليل 7 أكتوبر",
    "a8.t4b": "رقم منشور من ManyChat؛ لا يساوي بطاقة Meta تلقائيًا",
    "a8.t4c": "غير مطبق في هذا الجدول",
    "a8.t5": "إجمالي شاتورا",
    "a8.t5a": "غير معلن",
    "a8.t5b": "لا سعر اشتراك أو ربط رسائل مباشر للمقارنة",
    "a8.t5c": "غير مطبق في هذا الجدول",
    "a8.foot": "صفحات الموردين راجعناها في 28 أكتوبر 2026؛ بطاقة Meta بالدولار سارية من 1 أكتوبر 2026. المكافئات الشهرية تستخدم الفوترة السنوية حيثما ذُكر. قد تختلف الأسعار الإقليمية والضرائب وشروط المحفظة والاستخدام؛ ولا يقدم الجدول إجمالي فاتورة شهرية.",
    "a8.sources": "<a href=\"https://manychat.com/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">أسعار ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">أسعار Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" target=\"_blank\" rel=\"noopener noreferrer\">وثائق فوترة Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">بطاقة Meta</a>",
    "a8.b15": "تذكر بطاقة Meta لمصر 0.0644$ لكل رسالة تسويق و0.0036$ للمنفعة والتوثيق والخدمة. ويسرد دليل ManyChat رقمًا مختلفًا للتسويق في مصر. اسأل كل مزود عن السعر والرسوم المنطبقة على حسابك، وقارن الفاتورة ببطاقة Meta المنشورة؛ فالاختلاف وحده لا يثبت سببه.",
    "a8.b16": "3. ما الاستخدام الذي قد تلائمه كل منصة؟",
    "a8.b17": "المقارنة المفيدة تذكر نقاط قوة وحدود كل منتج:",
    "a8.b18": "<strong>ManyChat — منظومة راسخة.</strong> لديها محرر ناضج وموارد مجتمع وبرنامج شركاء معلن. تحقق مما إذا كانت القنوات وميزات الذكاء الاصطناعي والدعم المتاحة تناسب باقتك الحالية.",
    "a8.b19": "<strong>Chatfuel — محفظة وخيارات للوكالات.</strong> تذكر صفحاتها حالة مزود WhatsApp وجهات اتصال غير محدودة في وثائق المساعدة وخيار Agency S. راجع المحفظة والاستخدام الفعلي.",
    "a8.b20": "<strong>شاتورا — معاينة منتج.</strong> تتضمن واجهة عربية وإنجليزية ومسودات بداية قابلة للتعديل وأدوات CSV. ليست بديلًا حيًا للمراسلة ولا يوجد لها سعر اشتراك معلن.",
    "a8.b21": "4. أسئلة قبل الانتقال",
    "a8.b22": "<strong>ما البيانات التي يمكن تصديرها؟</strong> احفظ جهات الاتصال وتعريفات التدفقات والقوالب قبل تغيير المزوّد؛ وتحقق من أدوات التصدير في كل منصة.",
    "a8.b23": "<strong>ما صلاحيات القناة المطلوبة؟</strong> تحقّق من API الرسمي وملكية الحساب ومتطلبات الموافقة قبل ربط حساب إنتاجي.",
    "a8.b24": "<strong>ما الميزات التي ستفقدها أو تكسبها؟</strong> قارن مكتبة القوالب ومسارات الوكالات والتكاملات ودعم اللغات والتزامات الدعم.",
    "a8.b25": "<strong>ما سعر الرسالة الفعلي؟</strong> اطلب سعر الفئة والسوق وفاتورة نموذجية؛ فقد تختلف بطاقة Meta عن طريقة عرض فوترة المزوّد.",
    "a8.b26": "5. الخلاصة حسب الاستخدام",
    "a8.b27": "<strong>تحتاج مراسلة اجتماعية مباشرة الآن:</strong> قيّم المزوّدين ذوي القنوات المتاحة رسميًا وتأكد من حدود الخطة.",
    "a8.b28": "<strong>تحتاج قائمة كبيرة أو نموذج محفظة:</strong> قارن خطة Chatfuel المنشورة وأرصدتها واستخدام الحساب بمزيج رسائلك المتوقع.",
    "a8.b29": "<strong>تحتاج منظومة قوالب ناضجة:</strong> قد تناسبك ManyChat؛ تحقق من العرض المحلي الحالي ومستوى الميزات.",
    "a8.b30": "<strong>تفكر في شاتورا:</strong> المعاينة الحالية ليست برنامج مراسلة للإنتاج. راجع صفحة التوفر؛ لم يُعلن سعر أو توفير.",
    "a8.b31": "قبل الشراء، سجّل عدد جهات الاتصال والقنوات وفئات الرسائل المتوقعة واستخدام الذكاء الاصطناعي وبلد الفوترة. اطلب الشروط المكتوبة من كل مزوّد وقارن الفترة والميزات نفسيهما.",
    "a8.b32": "أسئلة متكررة، باختصار",
    "a8.b33": "هل Chatfuel أرخص من ManyChat؟",
    "a8.b34": "تختلف أسعار الاشتراك العامة، لكن الإجمالي يعتمد على حدود جهات الاتصال والميزات والأرصدة وخصومات المحفظة ورسوم Meta والضرائب ودورة الفوترة. مقارنة الاشتراك وحده ليست إجمالي التكلفة.",
    "a8.b35": "هل يمكنني مقارنة سعر شاتورا بهما؟",
    "a8.b36": "لا. لم تعلن شاتورا سعر اشتراك أو قناة مراسلة مباشرة؛ لذا لا توجد خطة مكافئة أو إجمالي استخدام للمقارنة.",
    "a8.b37": "هل تنتقل جهات الاتصال تلقائيًا عند تغيير المزوّد؟",
    "a8.b38": "لا تفترض ذلك. صدّر واحتفظ بنسخة من السجلات المتاحة لدى المزوّد الحالي، وتحقق من قواعد ملكية القناة ونقلها قبل فصلها.",
    "a8.b39": "أين أرى حالة شاتورا الحالية؟",
    "a8.b40": "توضح صفحة الأسعار ما هو مفعّل وما هو غير مفعّل في المعاينة الحالية. لا تنشر الصفحة خطة مدفوعة أو تَعِد بمراسلة مباشرة.",
    "a8.b41": "راجع الشروط المنشورة، لا إجماليًا مفترضًا",
    "a8.b42": "راجع الأسعار وقواعد الاستخدام الحالية لكل مورد. تعرض صفحة شاتورا حالة المعاينة؛ ولا يمكنها حساب مقارنة شاملة بعد.",
    "a8.b43": "راجع توفر شاتورا ←",
    "a8.b44": "المصادر: صفحات الأسعار والفوترة العامة لدى ManyChat وChatfuel، كما راجعناها في 28 أكتوبر 2026؛ وبطاقة Meta بالدولار السارية من 1 أكتوبر 2026. قد تتغير الأسعار وشروط المحفظة والفوترة الإقليمية. شاتورا غير تابعة لـManyChat أو Chatfuel.",
    "a8.r1": "شرح أسعار ManyChat: الخطط الحالية وحدود جهات الاتصال",
