    "mc.three": "<a href=\"blog-manychat-vs-chatfuel.html\" style=\"color:var(--cyan);text-decoration:none\">اقرأ المقارنة الثلاثية</a> مع فصل واضح بين الأسعار المؤرخة لدى المنافسين وحالة توفر شاتورا.",
