    "mc.foot": "تصف خانات شاتورا حالة المعاينة، لا عروضًا متاحة. راجعنا صفحات ManyChat الرسمية في 28 أكتوبر 2026؛ تختلف الأسعار حسب بلد الفوترة. روابط المصدر أدناه. تحقّق من التفاصيل قبل الشراء؛ لسنا تابعين لـManyChat.",
    "mc.wk": "النسخة الصريحة",
    "mc.wt": "أين يتقدم ManyChat حاليًا",
    "mc.wd": "المقارنة الأمينة تذكر أين يتقدم المنافس. شاتورا ما زالت معاينة وليست بديلًا تشغيليًا اليوم، لذلك لا يصح تحويل المزايا الحالية إلى وعد بشرائها أو مقابلتها بسعر غير منشور.",
    "mc.h1": "لدى ManyChat مكتبة قوالب ناضجة؛ وتعرض صفحة خطتها المجانية أكثر من 60 قالبًا. أما قوالب شاتورا الـ45 فهي مسودات أولية قابلة للتعديل وليست تدفقات اختُبرت في الإنتاج.",
    "mc.h1m": "استعرض 45 مسودة أولية",
    "mc.h2": "لدى ManyChat دليل لوكالات وبرنامج شركاء. لم تعلن شاتورا تسعيرًا للوكالات أو إدارة حسابات العملاء أو فوترة متعددة العملاء؛ فلا تتعامل مع المعاينة كبديل جاهز.",
    "mc.h2m": "أرسل متطلبات وكالتك",
    "mc.h3": "قد تكون خبرة الفريق بالمنصة القائمة ووثائقها ومجتمعها سببًا عمليًا للبقاء. شاتورا ما زالت معاينة، وليست بديلًا مباشرًا للخدمة الحية.",
    "mc.h3m": "اقرأ المقارنة قبل أي انتقال",
    "mc.ck": "ملخص الأسعار المنشورة",
    "mc.cl": "أسعار بالدولار كما ظهرت في صفحة ManyChat الرسمية، باستخدام المكافئ الشهري للفوترة السنوية. يختلف السعر حسب بلد الفوترة وقد يختلف السعر النهائي عند الدفع. شاتورا لم تعلن سعرًا أو باقة، لذلك لا يمكن حساب توفير.",
    "mc.ct": "باقات ManyChat المعروضة في 28 أكتوبر 2026",
