    "mc.save": "بتوفره",
    "mc.cfoot": "*مكافئات شهرية بالدولار كما ظهرت في صفحة ManyChat الرسمية عند مراجعتها في 28 أكتوبر 2026؛ يؤثر بلد الفوترة ودورتها في السعر النهائي. لا ندّعي سعرًا أو توفيرًا لشاتورا.",
    "mc.calct": "فاتورتك الشهرية، بالطريقتين",
    "mc.calcl": "موديل تقديري مبني على الدرجات المعلنة فوق، مش عرض سعر. حرّك المؤشرات على أرقامك الحقيقية.",
    "mc.calccta": "ابدأ مجانًا وتأكد بنفسك ←",
    "mc.faqt": "شاتورا وManyChat: إجابات واضحة",
    "mc.q1": "هل شاتورا أرخص من ManyChat؟",
    "mc.a1": "لا يمكن الحكم على ذلك الآن. لم تعلن شاتورا سعر اشتراك، كما أن القنوات المباشرة وردود الذكاء الاصطناعي غير مفعّلة. أي مقارنة للفواتير أو التوفير ستكون مضللة. قارن الأسعار المعلنة لدى ManyChat، واطلب عرضًا من شاتورا فقط بعد إعلان خدمة فعلية وأسعارها.",
    "mc.q2": "ما أسعار ManyChat الحالية؟",
    "mc.a2": "تعرض صفحة ManyChat الرسمية باقات بأسعار تختلف حسب البلد ودورة الدفع. الجدول أعلاه لقطة بالدولار بتاريخ 28 أكتوبر 2026، وليس ضمانًا لسعر متاح في مصر. راجع صفحة الأسعار الرسمية والسعر الظاهر عند الدفع.",
    "mc.q3": "هل يمكنني نقل تدفقات ManyChat إلى شاتورا؟",
    "mc.a3": "المعاينة الحالية لا توفر استيرادًا مباشرًا أو خدمة انتقال مختبرة. احتفظ بنسخك الأصلية، ولا تحذف تدفقاتك أو توقف حسابك القديم اعتمادًا على هذا الموقع. قد تتغير إمكانات الاستيراد بعد تنفيذها واختبارها.",
    "mc.q4": "هل تستخدم شاتورا واجهة واتساب الرسمية؟",
    "mc.a4": "لا يوجد ربط واتساب مباشر أو إرسال رسائل من شاتورا حاليًا. مسار التكامل المستقبلي المختار هو Tech Provider، لكن لم يتم التحقق من موافقة Meta أو اعتماد التطبيق. ManyChat تعرّف نفسها بأنها شريك رسمي لـMeta؛ راجع حالة كل مزود مباشرةً قبل الإطلاق.",
    "mc.q5": "هل تدعم شاتورا الرد باللهجات العربية؟",
    "mc.a5": "واجهة شاتورا متاحة بالعربية، لكن الردود الحية بالذكاء الاصطناعي غير مفعّلة ولا يوجد معيار إنتاجي منشور للأداء باللهجات. لا تختَر منصة بناءً على ادعاء لغوي فقط؛ اختبر ردودًا فعلية على بياناتك بعد إتاحة الخدمة.",
