    "lg.0": "سياسة الخصوصية",
    "lg.1": "قد تعالج معاينة شاتورا الحالية بيانات الحساب (الإيميل وإعدادات مساحة العمل)، وجهات الاتصال التي تضيفها أو تستوردها، والمعلومات التي ترسلها عبر النماذج العامة. المحادثات الحية وفوترة الاشتراك وردود الذكاء الاصطناعي غير مفعّلة في المعاينة.",
    "lg.2": "البيانات التي نجمعها: إيميل الحساب وبيانات المصادقة، وإعدادات مساحة العمل، وجهات الاتصال التي تضيفها أو تستوردها، وطلبات التواصل وطلبات الاهتمام بتحديثات المنتج. قد تشمل البيانات الإيميل والاسم والقناة والموضوع والرسالة، إلى جانب الصفحة واللغة والمحيل ووسوم UTM ومعلومات المتصفح. قد تُسجّل أيضًا مشاهدات الصفحات. عند الإرسال دون اتصال قد تُحفظ التفاصيل مؤقتًا في التخزين المحلي للمتصفح حتى تُرسل؛ تجنّب الأجهزة المشتركة ولا تُدخل معلومات حساسة.",
    "lg.3": "السبب: لمصادقة حسابك وحفظ تغييرات مساحة العمل والتعامل مع الاستفسارات وتسجيل الاهتمام بتحديثات المنتج وفهم الاستخدام الأساسي للموقع. طلب الاهتمام بالتحديثات لا يشترك بك في قائمة بريدية؛ ولا تُستخدم المعاينة لبناء ملفات إعلانية.",
    "lg.4": "معالجة الذكاء الاصطناعي: الردود الحية والمعالجة عبر مزوّدي ذكاء اصطناعي خارجيين غير مفعّلة في المعاينة. لا تضع معلومات حساسة في مسودات السيناريو التوضيحية.",
    "lg.5": "الاحتفاظ: لم تُعلن مدة احتفاظ عامة أو مهلة لحذف النسخ الاحتياطية لهذه المعاينة. يمكنك إدارة السجلات الظاهرة في مساحة العمل؛ تواصل معنا لطلبات الحساب أو الخصوصية. قد تبقى بيانات النموذج غير المرسلة في التخزين المحلي حتى إرسالها أو حذف بيانات المتصفح يدويًا.",
    "lg.6": "مقدمو الخدمات: كود الموقع مضبوط لاستخدام Supabase للمصادقة وبيانات مساحة العمل. لم نتحقق من منطقة الاستضافة الحية أو ننشر قائمة كاملة بالمعالجين من الباطن. لا يوجد مزوّد دفع أو قنوات أو ذكاء اصطناعي موصول بالمعاينة.",
    "lg.7": "طلبات الخصوصية: يمكنك طلب الوصول إلى بياناتك أو تصحيحها أو حذفها حيثما ينطبق ذلك. أرسل الطلب من صفحة التواصل؛ لا يوجد التزام منشور بمدة للرد في هذه المعاينة.",
    "lg.8": "شروط الخدمة",
    "lg.9": "يوضح هذا القسم استخدام المعاينة فقط. ليس اتفاق خدمة تجاريًا موقّعًا؛ ويجب مراجعته قبل إطلاق أي خدمة مدفوعة أو مراسلة مباشرة.",
    "lg.10": "الاستخدام المقبول: ممنوع السبام، وممنوع قوائم جهات اتصال مشتراة، وممنوع أي محتوى يخالف سياسات المنصات أو القوانين السارية. ولازم تجمع موافقة صحيحة على كل قناة بتبعت عليها.",
    "lg.11": "قواعد المنصات: لا يوجد مزوّد مراسلة اجتماعية موصول في المعاينة الحالية. أي استخدام مستقبلي لقناة يجب أن يلتزم بسياسات المزوّد ومتطلبات الموافقة السارية.",
    "lg.12": "الفوترة: لا توجد باقة اشتراك أو صفحة دفع أو فوترة متكررة من شاتورا مفعّلة في المعاينة. لا تُعرض حاليًا رسوم اشتراك أو تجاوز.",
    "lg.13": "الاسترداد: لا توجد باقة مدفوعة في المعاينة الحالية، ولا يُعرض ضمان استرداد.",
    "lg.14": "التوافر: لم يُنشر هدف لوقت التشغيل أو اتفاق مستوى خدمة أو تعويض عن انقطاع الخدمة لهذه المعاينة.",
    "lg.15": "الشروط التجارية: لم تُنشر صياغة مراجعة لحدود المسؤولية أو الضمانات لهذا العرض التجريبي.",
    "lg.16": "الوصول: يمكنك التوقف عن استخدام المعاينة في أي وقت. قد يُعلّق الوصول لمعالجة إساءة الاستخدام أو مشكلات الأمان أو الاستخدام غير القانوني؛ ولا توجد آلية إلغاء خطة مدفوعة مفعّلة.",
    "lg.17": "ملحق معالجة البيانات (غير متاح حاليًا)",
    "lg.18": "لا يوجد ملحق معالجة بيانات (DPA) موقّع أو بنود تعاقدية قياسية منشورة لهذه المعاينة. لا تستخدمها لمعالجة بيانات منظمة أو حساسة أو بيانات عملاء تتطلب ملحقًا قانونيًا.",
    "lg.19": "لم تُحدّد أدوار المتحكم والمعالج في اتفاقية موقّعة.",
    "lg.20": "لم تُنشر قائمة موثّقة بالمعالجين من الباطن أو التزام بإشعار مسبق بالتغييرات.",
    "lg.21": "لم نتحقق في هذه المراجعة المحلية من شهادات أمان مستقلة أو نتائج اختبارات اختراق أو مواصفات التشفير أثناء التخزين.",
    "lg.22": "لم تُنشر مهلة تعاقدية للإبلاغ عن خرق البيانات.",
    "lg.23": "لم نتحقق من خيارات إقامة البيانات أو منطقة تخزين المشروع الحي.",
    "lg.24": "لا يتوفر حاليًا ملحق معالجة بيانات موقّع لهذه المعاينة.",
    "lg.25": "الأمان",
    "lg.26": "المعاينة لا تطلب كلمات مرور حسابات التواصل الاجتماعي، كما أن ربط القنوات عبر OAuth غير مفعّل. لم يتحقق هذا التدقيق المحلي من إعدادات التشفير أثناء التخزين أو سجل تدقيق غير قابل للتغيير أو شهادات الأمان أو اختبارات الاختراق؛ ولا يُعرض هنا ضمان أمني أو برنامج مكافآت للثغرات.",
    "lg.au": "الاستخدام المقبول:",
