    "t.q3": "راجع المسودات وملاحظات الأسعار المؤرخة. أداة أو خدمة ترحيل ManyChat غير متاحة في هذه المعاينة.",
    "t.q2": "لا يوجد مزود مراسلة متصل ولم تعلن Chatora أسعار اشتراك. المقارنة تعرض مصادر الموردين المؤرخة، وليس أسعار Chatora.",
    "t.q1": "معرض القوالب يحتوي على 45 مسودة بداية قابلة للتعديل. اختيار قالب ينشئ مسودة؛ لا يربط قناة ولا يرسل رسالة.",
    "t.lead": "المعاينة الحالية لا تحتوي على شهادات عملاء أو تكاملات مراسلة مباشرة. يمكنك مراجعة المسودات والمحاكاة المحلية وأدوات CSV دون اعتبار الأمثلة نتائج فعلية.",
