    "cp.mig.t": "النقل غير متاح في المعاينة الحالية",
    "cp.mig.1t": "احتفظ بنسخة احتياطية",
    "cp.mig.1d": "لا توجد أداة استيراد أو خدمة نقل موجهة في شاتورا. صدّر بياناتك واحتفظ بنسخة لدى مزودك الحالي؛ ولا تفترض أن التدفقات أو الوسوم أو سجل الرسائل سينتقل.",
