    "cp.q5": "هل هناك ضمان؟",
    "cp.a1": "لا توجد قناة متصلة أو أداة استيراد في معاينة شاتورا. صدّر سجلاتك من مزودك الحالي وتأكد مما يمكن نقله قبل تغيير المورد.",
    "cp.a2": "لم تعلن شاتورا أسعار اشتراك أو رسوم تجاوز أو رسوم قنوات، ولا ترسل رسائل واتساب في المعاينة. تعرض صفحة الأسعار لقطات مؤرخة لمورّدين آخرين فقط؛ تحقّق من الأسعار الإقليمية الحالية ورسوم Meta مع كل مزود.",
    "cp.a3": "لا تستطيع شاتورا الاتصال بقناة مباشرة في المعاينة الحالية، لذا لا يتوفر اختبار متوازٍ لقناة حية. اتبع قواعد المورد الحالية قبل تغيير ملكية webhook.",
    "cp.a4": "لم تُعلن حدود المقاعد أو أسعارها. تدعم المعاينة مالك مساحة عمل واحدًا؛ ولا تتوفر ميزات تعاون الوكالات.",
    "cp.a5": "لا. لا توجد خطة مدفوعة لشاتورا في المعاينة الحالية، ولا نقدّم ضمان استرداد أو مطابقة سعر أو توفير.",

