    "a1.lede": "تعرض ManyChat خمس باقات، بينما تختلف البدائل في القنوات ووحدات الفوترة والدعم. يعرض هذا الدليل لقطات مؤرخة من صفحات الموردين ويوضح نقاط التنازل. شاتورا معاينة منتج، وليست بديلًا مباشرًا يعمل الآن؛ لم تعلن سعر اشتراك أو تربط قنوات مراسلة.",
