    "pricing.vendorNote": "Son precios publicados por los proveedores, no precios de Chatora. Consulta con cada proveedor la facturación regional, impuestos, condiciones de prueba y límites actuales.",
    "pricing.waNote": "Las tarifas por mensajes de WhatsApp se cobran aparte de la suscripción de la plataforma. La guía de ManyChat, actualizada el 7 de octubre de 2026, indica tarifas para Egipto vigentes desde el 1 de octubre: 0,0740 USD para Marketing, 0,0041 USD para Utility y 0,0036 USD para Service. Son tarifas publicadas por ManyChat, no la tarifa en USD de Meta. La tarifa propia de Meta, vigente desde el 1 de octubre, indica para Egipto 0,0644 USD para Marketing y 0,0036 USD para Utility, Authentication y Service. Meta ofrece 1.000 mensajes de servicio gratuitos al mes por número de teléfono empresarial; pueden aplicarse tramos de volumen a Utility y Authentication. Confirma el proveedor, la moneda de la cuenta y los requisitos antes de enviar.",
    "pricing.waManychat": "Guía de precios de WhatsApp de ManyChat",
    "pricing.waMeta": "Precios de WhatsApp de Meta",
    "pricing.q1": "¿Los precios de ManyChat y Chatfuel son precios de Chatora?",
    "pricing.a1": "No. Son capturas fechadas de los proveedores, consultadas el 28 de octubre de 2026. Chatora no ha publicado precios de suscripción.",
    "pricing.q2": "¿La vista previa de Chatora cobra una suscripción?",
    "pricing.a2": "La vista previa actual no tiene facturación ni pago habilitados. No es un plan de suscripción gratuito publicado.",
    "pricing.q3": "¿Chatora puede enviar mensajes de WhatsApp?",
    "pricing.a3": "La vista previa actual no tiene conectado ningún proveedor de WhatsApp ni de otros canales. Los borradores de flujos y las vistas previas de audiencia no envían mensajes.",
    "seo.pricing.title": "Precios de Chatora — planes y disponibilidad actual | Chatora",
    "seo.pricing.desc": "Chatora no ha publicado precios de suscripción ni habilitado pagos. La página compara capturas fechadas de precios de terceros; no son precios de Chatora. Las tarifas de mensajería del proveedor pueden cobrarse aparte.",

    "ap.title": "Un espacio de trabajo más claro para las conversaciones con clientes",
    "ap.s1": "No hay canales de mensajería en vivo conectados",
    "ap.s2": "Borradores iniciales editables; no probados en producción",
    "ap.s3": "No se ha publicado un precio de suscripción",
    "ap.s4": "No se han publicado precios por miembro del equipo",
    "ap.vk": "Lo que defendemos",
    "ap.vt": "Cinco principios que no negociaremos",
    "ap.v1t": "El precio no debería penalizar el crecimiento",
    "ap.v1d": "Los precios deben ser transparentes y fáciles de entender. Chatora no ha publicado precios de suscripción, límites de contactos ni condiciones por miembro del equipo; la página actual es una vista previa, no una oferta de pago.",
    "ap.v2t": "APIs oficiales, o ninguna",
    "ap.v2d": "La dirección del producto prioriza APIs documentadas y aprobadas, no compartir contraseñas ni hacer scraping. En la vista previa actual no hay ningún canal de mensajería externo conectado.",
    "ap.v3t": "Los dialectos no son un extra",
    "ap.v3d": "La vista previa ofrece interfaces en árabe e inglés. La adaptación dialectal en respuestas de IA no está habilitada; el comportamiento lingüístico debe probarse antes de prometerlo.",
    "ap.v4t": "Las personas son parte esencial del producto",
    "ap.v4d": "La visión es usar IA para tareas rutinarias y transferir la conversación a una persona cuando sea necesario. Las respuestas de IA en vivo no están habilitadas en la vista previa actual.",
    "ap.v5t": "Comparaciones honestas",
    "ap.v5d": "Las comparaciones deben mostrar las ventajas de los proveedores consolidados y explicar los límites de la vista previa de Chatora; no se puede afirmar un ahorro sin un precio publicado por Chatora.",
    "ap.hk": "Dirección del producto",
    "ap.ht": "Un espacio de trabajo más claro para las conversaciones",
    "ap.hd": "La vista previa usa Supabase para cuentas con contraseña y datos de espacio de trabajo aislados por cuenta; el inicio de sesión con Google no está configurado. Hay borradores de flujos editables, herramientas CSV para contactos y vistas previas de audiencia, pero no están habilitados los canales de mensajería, las respuestas salientes, un agente de IA en vivo ni la facturación por suscripción.",
    "ap.hd2": "La dirección del producto combina automatización estructurada con conversaciones asistidas por IA. Aquí no se afirman resultados de clientes, precios de suscripción publicados, compromisos de nivel de servicio ni fechas de lanzamiento.",
