    "pg.lead": "Esta simulación local permite arrastrar nodos, añadir pasos y previsualizar una ejecución de ejemplo. No conecta canales, no guarda nada en un espacio de trabajo, no consulta modelos de IA ni envía mensajes.",
    "pg.availability": "Solo simulación: los pasos se ejecutan en esta pestaña con texto de ejemplo y no se guardan ni se envían. Para la vista previa del espacio de trabajo, abre el panel; las conexiones de canales y la automatización siguen deshabilitadas.",
