    "up.lead": "Ideas ilustrativas de flujos para tiendas, creadores, agencias y clínicas; no son automatizaciones activas, casos de clientes ni resultados medidos.",
    "up.availability": "Disponibilidad: los casos siguientes son conceptos ilustrativos, no estudios de caso. La vista previa solo permite borradores editables, herramientas CSV para contactos y vistas previas de audiencia; no tiene canales en vivo, respuestas de IA ni resultados de rendimiento medidos.",
    "seo.about.title": "Acerca de Chatora — nuestra dirección y principios | Chatora",
    "seo.about.desc": "Conoce la dirección del producto y los principios de Chatora. La vista previa tiene borradores editables y herramientas CSV, pero no mensajería en vivo ni respuestas de IA.",
    "seo.playground.title": "Simulador de flujos en el navegador | Chatora",
    "seo.playground.desc": "Prueba una simulación local de flujos en el navegador. No conecta proveedores de mensajería, no usa datos de clientes ni envía mensajes.",

    "seo.features.title": "Funciones — marketing conversacional con IA, flujos visuales y bandeja | Chatora",
    "seo.features.desc": "Explora los conceptos de funciones de Chatora y la vista previa actual: borradores de flujos editables, plantillas, herramientas CSV y vista previa de audiencia. Las respuestas de IA y la mensajería por canales en vivo aún no están disponibles.",

    "up.ec.k": "01 · Tiendas en línea",
    "up.ec.t": "Planifica soporte fuera de horario para preguntas sobre carritos",
    "up.ec.d": "Un futuro flujo de soporte para carritos podría dirigir preguntas como «¿hay existencias?», «¿me quedará bien?» o «¿puedo pagar contra entrega?» a información aprobada de productos y políticas. Ese flujo no está conectado en la vista previa actual.",
    "up.ec.l1": "Concepto: consultar existencias y variantes mediante una futura integración de comercio (no disponible)",
    "up.ec.l2": "Concepto: recopilar una confirmación de pago contra entrega en un borrador",
