    "up.cr.t": "Organiza las conversaciones con creadores después de una publicación popular",
    "up.cr.d": "Un futuro flujo para creadores podría clasificar preguntas frecuentes, preparar un borrador de respuesta aprobado y marcar mensajes para revisión humana. La vista previa actual no se conecta a Instagram ni envía respuestas.",
    "up.cr.l1": "La prevención de duplicados y la entrega de gran volumen no están disponibles ni probadas",
