    "up.ag.k": "03 · Agencias",
    "up.ag.t": "Da una estructura clara al trabajo con varios clientes",
    "up.ag.d": "La dirección futura para agencias podría separar espacios de trabajo de clientes, permisos e informes. Esos controles, SSO, acceso a API y niveles de precios no están disponibles en la vista previa actual.",
    "up.ag.l1": "La separación de espacios de trabajo para agencias es un concepto futuro",
