    "up.ag.m3": "Sin datos de ahorro",
    "up.ag.cta": "Comparte tus necesidades como agencia →",
    "up.sv.k": "04 · Clínicas y servicios",
    "up.sv.t": "Diseña un flujo de citas antes de conectar un calendario",
    "up.sv.d": "Un futuro flujo de citas podría recopilar un horario preferido, dirigir preguntas sobre políticas y preparar un borrador de recordatorio. La vista previa no tiene integraciones de calendario, seguros ni reservas; no introduzcas datos de pacientes ni información de salud.",
    "up.sv.l1": "La disponibilidad del calendario y la sincronización de citas no están conectadas",
    "up.sv.l2": "No uses la vista previa para recopilar datos de salud o sensibles",
