    "up.sv.m2": "Sin datos de reservas",
    "up.sv.m3": "Sin datos de tiempo ahorrado",
    "up.sv.cta": "Ver plantillas de reservas →",
    "up.tk": "Misma base",
    "up.tt": "Negocios distintos, flujos ilustrativos",
    "up.td": "Son conceptos de flujos, no servicios activos. Las versiones futuras podrían usar catálogos y políticas aprobados, incluir transferencia a una persona e informar resultados; ninguna de esas capacidades de mensajería en vivo está habilitada en esta vista previa.",
    "up.chip1": "45 borradores iniciales editables",
    "up.chip2": "8 canales previstos · ninguno conectado",
