    "tp.search": "Buscar entre 45 plantillas…",
    "tp.askbuild": "Comparte una solicitud de flujo de trabajo →",
    "tp.notice": "Solo borradores iniciales: al elegir una tarjeta se crea un borrador editable con pasos genéricos de ejemplo, no una versión configurada del flujo descrito. Las plantillas no se han probado en producción ni están conectadas a proveedores de mensajería, y no se envía ningún mensaje. Revisa las integraciones, el consentimiento y las políticas del canal antes de cualquier uso real.",
    "tp.custom.k": "Flujos personalizados",
    "tp.custom.t": "¿Necesitas algo que todavía nadie haya creado?",
    "tp.custom.d": "Usa el creador local para añadir pasos manualmente y previsualizar una ejecución de ejemplo. No genera flujos a partir de instrucciones en lenguaje natural, no guarda en tu espacio de trabajo ni envía mensajes.",
    "tp.custom.cta": "Abrir la simulación local de flujos →",
    "tp.custom.ex1": "Borrador manual ilustrativo: desencadenante de comentario → texto de respuesta → espera opcional.",
    "tp.custom.ex2": "Solo vista previa local · no se genera a partir de una instrucción · no se envía nada.",
