    "tp.n1": "Control de viralidad de Reels",
    "tp.d1": "Esquema ilustrativo de flujo de comentarios con un paso para detectar duplicados; no se han probado la capacidad de envío ni el cumplimiento de las políticas.",
    "tp.n2": "Agradecimiento por mención en Story",
    "tp.d2": "Agradece públicamente al cliente y envía un código de recomendación mientras sigue entusiasmado.",
    "tp.n3": "Respuesta de precio por DM",
    "tp.d3": "Idea para un borrador: responder a «¿cuánto cuesta?» con el precio actual de la tienda, el estado del inventario y los detalles de pago; se necesita una integración activa con la tienda, que no está conectada en esta vista previa.",
    "tp.n4": "Lanzamiento exclusivo para seguidores",
    "tp.d4": "Da acceso anticipado a nuevos lanzamientos a quienes siguen la cuenta y envían la palabra clave por DM.",
    "tp.n5": "Recuperación de DM abandonado",
    "tp.d5": "Solo se ilustran los tiempos de seguimiento; las tasas de respuesta y recuperación no se miden ni se garantizan.",
    "tp.n6": "Solicitud de permiso para UGC",
    "tp.d6": "Pide permiso para reutilizar contenido del cliente, recopila los nombres de usuario y guarda el consentimiento.",
    "tp.n7": "Solicitud de colaboración con influencer",
    "tp.d7": "Califica a los creadores según seguidores, nicho y tarifa; luego agenda una llamada.",
    "tp.n8": "Confirmación de pedido por WhatsApp",
    "tp.d8": "Confirma pedidos contra reembolso 24 horas antes del despacho con una respuesta de un toque: ✅ / ❌.",
    "tp.n9": "Rescate de entrega fallida contra reembolso",
    "tp.d9": "Idea para un borrador que permite reprogramar una entrega fallida; se necesitan integraciones de pedidos y canales. No se afirma ningún ahorro de costes.",
    "tp.n10": "Navegación por el catálogo de WhatsApp",
    "tp.d10": "Envía tu catálogo, responde preguntas sobre tallas y enlaza la variante exacta.",
    "tp.n11": "Aviso de reposición de stock",
    "tp.d11": "Idea para un borrador: recopilar solicitudes de aviso y enviar una alerta cuando vuelva el stock; se necesitan integraciones activas de inventario y mensajería, que no están conectadas en esta vista previa.",
    "tp.n12": "Difusión de oferta de Ramadán",
    "tp.d12": "Difusión estacional segmentada con gestión de bajas y horarios de silencio.",
    "tp.n13": "Actualizaciones de seguimiento de entrega",
    "tp.d13": "Idea para un borrador: incluir la empresa de mensajería, la hora estimada de llegada y los detalles para reprogramar; se requieren integraciones activas de mensajería y de la empresa de reparto, que no están conectadas en esta vista previa.",
    "tp.n14": "Recordatorio de pago",
    "tp.d14": "Recopila amablemente pagos contra reembolso pendientes y permite adjuntar un comprobante de pago.",
    "tp.n15": "Atención VIP personalizada",
    "tp.d15": "Idea para un borrador: dirigir el segmento de clientes que elijas a un agente específico; consultar el historial de pedidos requiere una integración con una tienda o un CRM.",
    "tp.n16": "Ráfaga de DM viral en TikTok",
    "tp.d16": "Idea para un borrador de gestión de ráfagas de mensajes; no se garantiza capacidad de envío ni entrega.",
    "tp.n17": "Cuestionario de producto en TikTok",
    "tp.d17": "Cuestionario de tres preguntas que relaciona a cada persona con el SKU adecuado y luego enlaza al pago.",
    "tp.n18": "Respuesta a creadores de TikTok",
    "tp.d18": "Responde automáticamente a preguntas en comentarios con una respuesta breve y un enlace directo a los mensajes.",
    "tp.n19": "Sorteo con tendencia de audio",
    "tp.d19": "Organiza un sorteo, verifica los seguimientos y publica automáticamente a los ganadores.",
    "tp.n20": "Recuperación de carrito por DM",
    "tp.d20": "Idea para un borrador de seguimiento de carritos con consentimiento; se necesita una integración con la tienda y el canal.",
    "tp.n21": "Venta adicional de paquete",
    "tp.d21": "Ofrece un producto complementario adecuado durante el pago, con opción de añadirlo con un toque.",
    "tp.n22": "Asistente de guía de tallas",
    "tp.d22": "Idea para un borrador de conversación sobre preferencias de talla; no se afirma ningún resultado sobre la tasa de devoluciones.",
    "tp.n23": "Solicitud de reseña poscompra",
    "tp.d23": "Dos días después de la entrega: solicitud de reseña y sugerencia para volver a comprar.",
    "tp.n24": "Lista de espera para reposición",
    "tp.d24": "Convierte el interés por productos agotados en una lista de espera que se puede monetizar más adelante.",
    "tp.n25": "Control de descuentos",
    "tp.d25": "Rechaza solicitudes de descuento, ofrece valor en su lugar y deriva las objeciones reales a una persona.",
    "tp.n26": "Depósito de preventa",
    "tp.d26": "Recopila el enlace para pagar un depósito de preventa y etiqueta a los clientes que ya pagaron.",
    "tp.n27": "Recordatorio de recompra para clientes fieles",
    "tp.d27": "Idea para un borrador de recordatorio de recompra con reglas que tú eliges; el modelado predictivo no está disponible en esta vista previa.",
    "tp.n28": "Derivación a una persona",
    "tp.d28": "Deriva los casos de reembolso, clientes VIP o solicitudes explícitas de «quiero hablar con una persona».",
    "tp.n29": "Clasificación de solicitudes de reembolso",
    "tp.d29": "Recopila el número de pedido, el motivo y una foto como prueba; después dirige el caso al agente adecuado.",
    "tp.n30": "Atención de preguntas frecuentes",
    "tp.d30": "Idea para un borrador de respuestas a preguntas frecuentes usando tus políticas; no se promete resolución mediante IA ni un número de respuestas.",
    "tp.n31": "Desescalada de cliente molesto",
    "tp.d31": "Reconoce el problema, se disculpa, ofrece una solución y deriva el caso con todo el contexto.",
    "tp.n32": "Consulta del estado del envío",
    "tp.d32": "Idea para un borrador de respuesta sobre el estado del envío; se requiere una integración activa con la empresa de reparto.",
    "tp.n33": "Reclamación de garantía",
    "tp.d33": "Esquema de recepción de reclamaciones en borrador; la carga de archivos y los temporizadores de nivel de servicio requieren integraciones y no están implementados aquí.",
    "tp.n34": "Entrega de recurso de captación",
    "tp.d34": "Envía la guía o plantilla después de un comentario y luego etiqueta al contacto e inicia una secuencia.",
    "tp.n35": "Inscripción a seminario web",
    "tp.d35": "Registra, envía el enlace del calendario y recuerda una hora antes.",
    "tp.n36": "Cuestionario de calificación",
    "tp.d36": "Tres preguntas que puntúan la intención y derivan los contactos con mayor interés a una persona.",
    "tp.n37": "Consulta inmobiliaria",
    "tp.d37": "Idea para un borrador: recopilar presupuesto, zona y plazo antes de ofrecer una visita; reservar requiere una integración de calendario activa, que no está conectada aquí.",
    "tp.n38": "Recepción de clínica",
    "tp.d38": "Solo un esquema ilustrativo de recepción para clínicas. La clasificación de síntomas y la verificación del seguro requieren revisión cualificada e integraciones evaluadas en materia de privacidad; ninguna de las dos está implementada aquí.",
    "tp.n39": "Solicitud de auditoría de agencia",
    "tp.d39": "Califica según el gasto publicitario y agenda una llamada de auditoría de 20 minutos.",
    "tp.n40": "Suscripción a boletín desde un DM",
    "tp.d40": "Idea para un borrador: solicitar consentimiento explícito antes de recopilar un correo para el boletín; se necesita un proveedor de correo y aquí no hay ninguno conectado.",
    "tp.n41": "Reserva de cita",
    "tp.d41": "Idea para un borrador que muestra horarios disponibles; para consultar disponibilidad real, confirmar reservas o enviar recordatorios se necesita una integración de calendario activa, que no está conectada aquí.",
    "tp.n42": "Seguimiento de cita perdida",
    "tp.d42": "Idea para un borrador que ofrece una nueva cita después de perder la anterior; se requieren integraciones de calendario, disponibilidad y reprogramación. No se promete reprogramar en dos horas.",
    "tp.n43": "Gestión de lista de espera",
    "tp.d43": "Ofrece las franjas canceladas a la lista de espera por orden de llegada.",
    "tp.n44": "Venta adicional de consulta",
    "tp.d44": "Convierte una consulta gratuita en un paquete de pago mediante un único enlace.",
