    "au.google": "Continuar con Google",
    "au.legal": "Al continuar, aceptas los términos y la política de privacidad. Guardamos tu correo electrónico para gestionar la cuenta, y nada más.",
    "au.back": "← Volver al sitio",
    "dash.loading": "Abriendo tu espacio de trabajo…",
    "dash.overview": "Resumen",
