    "bp.tag.market": "MENA",
    "bp.read11": "11 min de lectura",
    "bp.f3t": "Comercio por WhatsApp en MENA: configuración y revisión de políticas",
    "bp.f3d": "Revisa los requisitos de API, las categorías de tarifas, el consentimiento de clientes y flujos prácticos, sin recurrir a referencias de conversión regionales no verificadas.",
    "a4.tag": "Precios",
    "bp.read10": "10 min de lectura",
    "a4.cardT": "Precios de ManyChat: planes actuales y límites de contactos",
    "a4.cardD": "Resumen fechado de precios de planes y límites de contactos publicados, con detalles de facturación que conviene verificar antes de comprar.",
    "a7.tag": "Guía práctica",
    "a7.read": "8 min de lectura",
    "a7.cardT": "Mensajes de WhatsApp para carritos abandonados: ejemplos y escenarios de costes",
    "a7.cardD": "Textos ilustrativos y escenarios de costes de Meta, con verificaciones de categoría y consentimiento; no son resultados de recuperación medidos.",
    "a5.tag": "Comparativa",
    "bp.read8": "8 min de lectura",
    "a5.cardT": "Herramientas de automatización de Instagram en 2026: guía para compradores",
