    "availability.notPublished": "No publicado",
    "cmp.availability": "Estado de Chatora (28 oct. 2026): solo vista previa del producto. No hay precios ni planes de pago publicados, canales conectados, mensajería saliente ni respuestas de IA en vivo. Las tablas indican la disponibilidad de cada función de Chatora; los conceptos de la hoja de ruta no son ofertas actuales. Las cifras de la competencia son capturas públicas fechadas; verifícalas antes de comprar.",
    "mc.availability": "Estado de Chatora (28 oct. 2026): solo vista previa del producto. No hay precios ni planes de pago publicados, canales conectados, mensajería saliente ni respuestas de IA en vivo. Las tablas indican la disponibilidad de cada función de Chatora; los conceptos de la hoja de ruta no son ofertas actuales. Las cifras de ManyChat son capturas públicas fechadas; verifícalas antes de comprar.",
    "cf.availability": "Estado de Chatora (28 oct. 2026): solo vista previa del producto. No hay precios ni planes de pago publicados, canales conectados, mensajería saliente ni respuestas de IA en vivo. Las tablas indican la disponibilidad de cada función de Chatora; los conceptos de la hoja de ruta no son ofertas actuales. Las cifras de Chatfuel son capturas públicas fechadas; verifícalas antes de comprar.",
    "alt.badge": "Páginas de proveedores revisadas el 28 de octubre de 2026 · sin espacios pagados",
    "alt.title": "Alternativas a ManyChat en 2026: compara según tu caso de uso",
    "alt.lead": "Cinco alternativas consolidadas, con referencias actuales de cada proveedor y sus ventajas y desventajas. Chatora aparece con transparencia como vista previa de producto, no como sustituto operativo de ManyChat: no tiene precio publicado, canales de mensajería conectados ni respuestas de IA en vivo.",
    "alt.cta1": "Ir a la tabla",
    "alt.cta2": "Ver el estado de precios publicado de Chatora",
    "alt.best": "Vista previa del producto · todavía no es una alternativa operativa",
    "alt.1d": "Actualmente Chatora ofrece una vista previa de producto con cuentas, borradores de flujos editables y herramientas CSV para contactos. No se ha publicado ningún precio de suscripción ni plan de pago, y no hay conectado ningún canal de mensajería como Instagram o WhatsApp. No puede enviar mensajes ni ofrecer respuestas de IA en vivo, por lo que todavía no sustituye a ManyChat para uso en producción.",
    "alt.previewStrengths": "Disponible en la vista previa:",
    "alt.1p": "Interfaz en árabe e inglés, espacio de trabajo autenticado, herramientas CSV y 45 borradores iniciales editables.",
    "alt.cons": "Aún no disponible:",
    "alt.1c": "Mensajería en vivo, conexiones de canales, respuestas de IA, planes de pago, servicio de migración y compromisos de soporte publicados.",
    "alt.try": "Explorar borradores iniciales editables",
    "alt.mature": "Ecosistema consolidado",
    "alt.mo": "/mes*",
    "alt.2d": "ManyChat tiene un creador visual maduro, una biblioteca comunitaria consolidada y cinco planes publicados. Su página de precios actual indica 25 contactos en Free; WhatsApp y las conversaciones con IA figuran en Pro y superiores. Los precios mostrados dependen del ciclo de facturación y del país.",
    "alt.pros": "Ventajas:",
    "alt.2p": "Creador consolidado, más de 60 plantillas indicadas en Free, centro de ayuda público y comunidad.",
    "alt.2c": "Los límites de contactos activos y las funciones disponibles varían según el plan; conviene comprobar los precios regionales y los cargos por contactos adicionales antes de comprar.",
    "alt.readcmp": "Leer la comparación completa",
    "alt.readmc": "O comparar punto por punto",
    "alt.agency": "Opciones para agencias publicadas",
    "alt.3d": "Chatfuel indica Business por un equivalente de 18 USD al mes con facturación anual (20 USD con facturación mensual), con 20 USD de saldo mensual en la cartera. Su oferta Agency S incluye tres empresas cliente y un panel para agencias. El uso de IA y WhatsApp facturado por Meta se descuenta de la cartera; el coste real depende del uso.",
    "alt.3p": "Estado de proveedor oficial de Meta/WhatsApp, canales indicados, contactos y miembros de equipo ilimitados, y un panel para agencias.",
    "alt.3c": "No se indica un nivel gratuito permanente; el acceso gratuito es una prueba de 7 días. El uso de la cartera y las tarifas de mensajes añaden costes variables.",
    "alt.readcf": "Chatora frente a Chatfuel",
    "alt.support": "Ideal para flujos de soporte",
    "alt.4d": "Tidio combina chat en vivo, gestión de tickets y automatización para atención al cliente. Su página oficial de precios indica Starter a un equivalente de 24,17 USD al mes con facturación anual para 100 conversaciones facturables. Lyro AI y Flows tienen sus propios límites, así que compara el uso total, no solo el plan base.",
    "alt.4p": "Chat en vivo, gestión de tickets, flujos de soporte y una opción documentada de agente de IA.",
    "alt.4c": "Se aplican límites de conversaciones y automatizaciones; el uso de Lyro AI/Flows puede cobrarse por separado del plan base.",
    "alt.web": "Ideal para soporte y ventas en sitios web",
    "alt.5d": "El plan Essential de ChatBot.com figura a 19 USD por usuario al mes con facturación anual. Incluye un agente de IA, chat web, bandeja de entrada y gestión de tickets; el cupo publicado de Essential es de 10 resoluciones de IA al mes. La página oficial también indica Messenger, WhatsApp y SMS (a través de Twilio), además de funciones de venta con Shopify.",
    "alt.5p": "Chat web, bandeja de soporte y tickets, agentes de IA y canales de comercio indicados.",
    "alt.5c": "Precio por usuario, pocas resoluciones de IA incluidas en Essential y ningún nivel gratuito permanente.",
    "alt.dev": "Ideal para agentes conversacionales personalizados",
    "alt.freeCustom": "Gratis · personalizado",
    "alt.6d": "Botpress ofrece una plataforma personalizable para agentes, con herramientas visuales y extensiones para desarrolladores. Su página actual de precios indica un plan Free con 100 conversaciones, 3 plazas y 3 agentes; Plus empieza en 150 USD al mes con facturación anual para 250 conversaciones, seguido de Team y Enterprise.",
    "alt.6p": "Herramientas flexibles para crear agentes, un nivel gratuito publicado y planes de pago adicionales para cargas de trabajo mayores.",
    "alt.6c": "Los límites de conversaciones y el coste de los planes importan a escala; la disponibilidad de canales difiere de la de las plataformas de automatización centradas en redes sociales.",
    "alt.tbl.t": "Planes publicados y casos de uso, lado a lado",
    "alt.tbl.s": "Referencias de planes de proveedores revisadas el 28 de octubre de 2026. Los equivalentes mensuales usan facturación anual cuando se indica; Chatora se muestra como vista previa de producto, no como alternativa de producción.",
