    "mc.foot": "Las celdas de Chatora describen la disponibilidad de la vista previa, no ofertas actuales. Los detalles de los planes, precios y soporte de ManyChat se verificaron en sus páginas oficiales el 28 oct. 2026; los precios varían según el país de facturación. Verifica antes de comprar; no estamos afiliados.",
