    "mc.wk": "La versión honesta",
    "mc.wt": "Ventajas claras de ManyChat hoy",
    "mc.wd": "Chatora sigue siendo una vista previa, no un sustituto en vivo. Estas fortalezas actuales de ManyChat son relevantes para los compradores y deben tenerse en cuenta antes de cambiar.",
    "mc.h1": "ManyChat tiene una biblioteca comunitaria de plantillas consolidada. Los 45 elementos de Chatora son borradores iniciales editables, no bots probados en producción ni un mercado de plantillas.",
    "mc.h1m": "Explorar 45 borradores iniciales",
    "mc.h2": "ManyChat cuenta con un ecosistema maduro para agencias. Chatora no ha publicado precios para agencias, facturación de clientes, subcuentas ni descuentos por volumen; las agencias no deberían considerar la vista previa actual como un sustituto.",
    "mc.h2m": "Compartir necesidades de agencia",
    "mc.h3": "Un equipo ya formado en una plataforma consolidada puede valorar razonablemente sus flujos de trabajo, documentación y ecosistema actuales. La vista previa de Chatora todavía no es un sustituto equivalente para producción.",
    "mc.h3m": "Leer antes de considerar un cambio",
    "mc.ck": "Referencia de planes publicados",
    "mc.ct": "Niveles publicados de ManyChat al 28 de octubre de 2026",
    "mc.cl": "Precios en USD mostrados en la página oficial de ManyChat al consultarla el 28 oct. 2026, según el equivalente mensual publicado con facturación anual. El precio depende del país y el importe en el proceso de pago puede variar. Chatora no ha publicado planes ni precios, por lo que no se pueden calcular ahorros.",
