    "mc.cfoot": "*Equivalentes mensuales en USD mostrados en la página oficial de precios de ManyChat (consultada el 28 oct. 2026; el país de facturación y el ciclo de pago afectan al precio final). Consulta los enlaces de las fuentes; no se afirma ningún precio ni ahorro de Chatora.",
    "mc.pricesource": "Página oficial de precios de ManyChat",
    "mc.three": "Lee la comparación de tres opciones, con las referencias fechadas de proveedores y la disponibilidad de Chatora claramente diferenciadas.",
    "mc.faqt": "Chatora frente a ManyChat: respuestas",
    "mc.q1": "¿Chatora es más barato que ManyChat?",
    "mc.a1": "Aún no se puede determinar. Chatora no tiene un precio de suscripción publicado y no están habilitados los canales en vivo ni las respuestas de IA. Cualquier comparación actual de facturas o ahorros sería engañosa.",
    "mc.q2": "¿Cuánto cobra actualmente ManyChat?",
    "mc.a2": "La página oficial de ManyChat muestra planes cuyos precios varían según el país de facturación y el ciclo de pago. La tabla anterior es una referencia fechada en USD, consultada el 28 oct. 2026, y no garantiza el precio disponible en Egipto. Verifica el precio en la página oficial y en el proceso de pago.",
    "mc.q3": "¿Puedo transferir mis flujos de ManyChat a Chatora?",
    "mc.a3": "La vista previa actual no ofrece un importador probado ni un servicio de migración. Conserva tus exportaciones originales y no canceles ni elimines flujos existentes basándote en este sitio. Las funciones de importación podrían cambiar cuando se implementen y prueben.",
    "mc.q4": "¿Chatora se conecta actualmente a WhatsApp?",
    "mc.a4": "No. Actualmente Chatora no se conecta a WhatsApp ni envía mensajes. Tech Provider es la vía de integración futura seleccionada, pero no se han verificado la aprobación de Meta ni la configuración de la aplicación. ManyChat se identifica como socio oficial de Meta; comprueba el estado actual de cada proveedor antes del lanzamiento.",
    "mc.q5": "¿Chatora responde en dialectos árabes?",
    "mc.a5": "La interfaz de Chatora está disponible en árabe, pero las respuestas de IA en vivo no están habilitadas y no se ha publicado una referencia de dialectos en producción. No elijas una plataforma basándote solo en una afirmación sobre idiomas; cuando el servicio esté activo, prueba respuestas reales con tus propios casos de uso.",
    "cf.badge": "Revisado el 28 de octubre de 2026",
