    "cf.lead": "Chatfuel publica un modelo de suscripción más cartera, con créditos mensuales y consumo medido. Chatora es una vista previa de producto sin precio publicado, canales en vivo ni respuestas de IA, por lo que todavía no hay una comparación válida de costes o rendimiento. Esta página separa la documentación actual de Chatfuel de la disponibilidad de la vista previa de Chatora.",
