    "chp.ig.l3": "Aucune capacité d’envoi ni réduction des signalements pour spam n’est revendiquée ; le comportement du fournisseur n’a pas été testé.",
    "chp.wa.title": "Là où le marché MENA achète vraiment",
    "chp.wa.lead": "Un parcours WhatsApp peut être planifié autour de messages d’assistance et de commerce avec consentement préalable. Aucun fournisseur de la plateforme WhatsApp Business ni aucun compte n’est connecté dans cet aperçu.",
