    "cmp.availability": "Statut de Chatora (28 oct. 2026) : aperçu du produit uniquement. Aucun prix ni forfait payant publié, aucun canal connecté, aucun message sortant et aucune réponse IA en direct. Les tableaux précisent la disponibilité des fonctionnalités Chatora ; les concepts de feuille de route ne sont pas des offres actuelles. Les chiffres des concurrents sont des instantanés publics datés ; vérifiez-les avant tout achat.",
    "mc.availability": "Statut de Chatora (28 oct. 2026) : aperçu du produit uniquement. Aucun prix ni forfait payant publié, aucun canal connecté, aucun message sortant et aucune réponse IA en direct. Les tableaux précisent la disponibilité des fonctionnalités Chatora ; les concepts de feuille de route ne sont pas des offres actuelles. Les chiffres de ManyChat sont des instantanés publics datés ; vérifiez-les avant tout achat.",
    "cf.availability": "Statut de Chatora (28 oct. 2026) : aperçu du produit uniquement. Aucun prix ni forfait payant publié, aucun canal connecté, aucun message sortant et aucune réponse IA en direct. Les tableaux précisent la disponibilité des fonctionnalités Chatora ; les concepts de feuille de route ne sont pas des offres actuelles. Les chiffres de Chatfuel sont des instantanés publics datés ; vérifiez-les avant tout achat.",
    "alt.badge": "Pages des fournisseurs vérifiées le 28 octobre 2026 · aucun placement sponsorisé",
    "alt.title": "Alternatives à ManyChat en 2026 : comparer selon votre usage",
    "alt.lead": "Cinq alternatives établies, avec des instantanés récents des fournisseurs et leurs compromis. Chatora est présenté en toute transparence comme un aperçu de produit, pas comme un remplacement opérationnel de ManyChat : aucun tarif publié, aucun canal de messagerie connecté et aucune réponse IA en direct.",
    "alt.cta1": "Accéder au tableau",
    "alt.cta2": "Voir le statut tarifaire publié de Chatora",
    "alt.best": "Aperçu du produit · pas encore une alternative opérationnelle",
    "alt.1d": "Chatora propose actuellement un aperçu de produit avec comptes, brouillons de flux modifiables et outils CSV pour les contacts. Aucun tarif d’abonnement ni forfait payant n’est publié, et aucun canal de messagerie tel qu’Instagram ou WhatsApp n’est connecté. Le produit ne peut ni envoyer de messages ni fournir de réponses IA en direct : il ne remplace donc pas encore ManyChat en production.",
    "alt.previewStrengths": "Disponible dans l’aperçu :",
    "alt.1p": "Interface arabe et anglaise, espace de travail authentifié, outils CSV et 45 brouillons de départ modifiables.",
