    "alt.mature": "Écosystème établi",
    "alt.mo": "/mois*",
    "alt.2d": "ManyChat dispose d’un créateur visuel mature, d’une bibliothèque communautaire établie et de cinq forfaits publiés. Sa page tarifaire actuelle indique 25 contacts avec Free ; WhatsApp et les conversations assistées par l’IA sont inclus dans Pro et les offres supérieures. Les prix affichés dépendent de la périodicité de facturation et du pays.",
    "alt.pros": "Points forts :",
    "alt.2p": "Créateur établi, plus de 60 modèles répertoriés avec Free, centre d’aide public et communauté.",
    "alt.2c": "Les limites de contacts actifs et l’accès aux fonctionnalités varient selon l’offre ; vérifiez les tarifs régionaux et les frais liés aux contacts supplémentaires avant tout achat.",
    "alt.readcmp": "Lire le comparatif complet",
