    "alt.agency": "Options agence publiées",
    "alt.3d": "Chatfuel affiche Business à 18 $ par mois en équivalent avec facturation annuelle (20 $ en facturation mensuelle), avec 20 $ de crédits mensuels dans le portefeuille. L’offre Agency S comprend trois entreprises clientes et un tableau de bord d’agence. L’usage de l’IA et de WhatsApp facturé par Meta est prélevé sur le portefeuille ; le coût réel dépend de l’utilisation.",
    "alt.3p": "Statut de fournisseur officiel Meta/WhatsApp, canaux répertoriés, contacts et coéquipiers illimités, et tableau de bord d’agence.",
    "alt.3c": "Aucune offre gratuite permanente n’est répertoriée ; l’accès gratuit correspond à un essai de 7 jours. L’utilisation du portefeuille et les frais de messagerie ajoutent des coûts variables.",
    "alt.readcf": "Chatora face à Chatfuel",
    "alt.support": "Idéal pour les parcours d’assistance",
    "alt.4d": "Tidio associe chat en direct, gestion des tickets et automatisation du support client. Sa page tarifaire officielle indique Starter à 24,17 $ par mois en équivalent avec facturation annuelle pour 100 conversations facturables. Lyro AI et Flows ont leurs propres quotas : comparez l’utilisation totale, pas seulement l’offre de base.",
    "alt.4p": "Chat en direct, gestion des tickets, parcours d’assistance et option d’agent IA documentée.",
    "alt.4c": "Des quotas de conversations et d’automatisation s’appliquent ; l’utilisation de Lyro AI/Flows peut être facturée séparément de l’offre de base.",
    "alt.web": "Idéal pour l’assistance et la vente sur le Web",
    "alt.5d": "L’offre Essential de ChatBot.com est affichée à 19 $ par utilisateur et par mois avec facturation annuelle. Elle comprend un agent IA, le chat sur site web, une boîte de réception et la gestion des tickets ; le quota Essential publié est de 10 résolutions IA par mois. La page officielle répertorie aussi Messenger, WhatsApp et les SMS (via Twilio), ainsi que des fonctionnalités de vente Shopify.",
    "alt.5p": "Chat web, boîte de réception d’assistance et tickets, agents IA et canaux commerciaux répertoriés.",
    "alt.5c": "Tarification par utilisateur, peu de résolutions IA incluses avec Essential et aucune offre gratuite permanente.",
    "alt.dev": "Idéal pour les agents conversationnels personnalisés",
    "alt.freeCustom": "Gratuit · personnalisé",
    "alt.6d": "Botpress propose une plateforme d’agents personnalisable avec outils visuels et extensions pour développeurs. Sa page tarifaire actuelle affiche une offre Free avec 100 conversations, 3 sièges et 3 agents ; Plus démarre à 150 $/mois avec facturation annuelle pour 250 conversations, puis viennent Team et Enterprise.",
    "alt.6p": "Outils flexibles de création d’agents, offre gratuite publiée et forfaits payants supplémentaires pour des charges plus importantes.",
    "alt.6c": "Les limites de conversations et le coût des offres comptent à grande échelle ; la disponibilité des canaux diffère des plateformes d’automatisation axées sur les réseaux sociaux.",
