    "mc.foot": "Les cellules Chatora décrivent la disponibilité de l’aperçu, pas des offres actuelles. Les détails des offres, tarifs et de l’assistance ManyChat ont été vérifiés sur ses pages officielles le 28 oct. 2026 ; les prix varient selon le pays de facturation. Vérifiez avant tout achat ; nous ne sommes pas affiliés.",
    "mc.sources": "Tarifs · frais WhatsApp · annuaire d’agences · statut de partenaire Meta",
    "mc.wk": "La version honnête",
    "mc.wt": "Les avantages nets de ManyChat aujourd’hui",
    "mc.wd": "Chatora reste un aperçu, pas un remplacement en direct. Ces atouts actuels de ManyChat comptent pour les acheteurs et doivent être pris en compte avant un changement.",
    "mc.h1": "ManyChat dispose d’une bibliothèque communautaire de modèles mature. Les 45 éléments de Chatora sont des brouillons de départ modifiables, pas des bots testés en production ni une marketplace de remplacement.",
    "mc.h1m": "Examiner 45 brouillons de départ",
    "mc.h2": "ManyChat possède un écosystème d’agences mature. Chatora n’a publié ni tarifs d’agence, ni facturation client, ni sous-comptes, ni remises sur volume ; les agences ne devraient pas considérer l’aperçu actuel comme un remplacement.",
    "mc.h2m": "Partager les besoins de l’agence",
    "mc.h3": "Une équipe déjà formée à une plateforme établie peut légitimement valoriser ses parcours, sa documentation et son écosystème existants. L’aperçu Chatora n’est pas aujourd’hui un remplacement équivalent pour la production.",
    "mc.h3m": "À lire avant d’envisager un changement",
    "mc.ck": "Instantané des offres publiées",
    "mc.ct": "Offres ManyChat répertoriées au 28 octobre 2026",
    "mc.cl": "Prix en USD affichés sur la page officielle de ManyChat lors de la consultation du 28 oct. 2026, selon l’équivalent mensuel affiché avec facturation annuelle. Les prix dépendent du pays ; le prix au paiement peut différer. Chatora n’a publié ni offre ni prix : les économies ne sont pas calculables.",
