    "t.lead": "Die aktuelle Vorschau enthält keine Kundenstimmen und keine aktiven Messaging-Integrationen. Du kannst bearbeitbare Entwürfe, eine lokale Simulation und CSV-Tools prüfen, ohne die Beispiele als Ergebnisse darzustellen.",
