    "chp.availability": "Verfügbarkeit: Instagram, WhatsApp, TikTok, Messenger, Telegram, SMS, E-Mail und Web-Chat sind nicht verbunden. Die folgenden Bezeichnungen und Beispiele sind Roadmap-Konzepte. Diese Vorschau empfängt oder sendet keine Kanalnachrichten.",
    "ch.ig": "Geplante Idee: Abläufe von Kommentaren zu Direktnachrichten und Stories. Instagram ist in dieser Vorschau nicht verbunden.",
    "ch.wa": "Geplante Idee: Support mit Einwilligung, Kataloge und Bestellnachrichten. WhatsApp ist in dieser Vorschau nicht verbunden.",
    "ch.tt": "Geplante Idee: Kommentar-Follow-up und Produktinformationen. TikTok ist in dieser Vorschau nicht verbunden.",
    "ch.fb": "Geplante Idee: Nachrichten für Facebook-Seiten und Anzeigen. Messenger ist in dieser Vorschau nicht verbunden.",
    "ch.tg": "Geplante Idee: Bot- und Community-Abläufe. Telegram ist in dieser Vorschau nicht verbunden.",
    "ch.sms": "Geplante Idee: SMS-Follow-up mit Einwilligung. Es ist kein SMS-Anbieter verbunden; eine Öffnungsrate wird nicht behauptet.",
    "ch.email": "Geplante Idee: E-Mail-Follow-up mit Einwilligung. In dieser Vorschau ist kein E-Mail-Anbieter verbunden.",
    "ch.web": "Geplante Idee: Website-Messaging. In dieser Vorschau ist kein Web-Chat-Widget aktiv.",
    "chp.ig.title": "Von Kommentaren zu Direktnachrichten — richtig umgesetzt",
    "chp.ig.lead": "Ein Ablauf von Kommentaren zu Direktnachrichten lässt sich mit Triggern, Antworttext und Follow-up-Zeitpunkt als Entwurf planen. Es ist keine Instagram-API verbunden; es wird nichts empfangen oder gesendet.",
    "chp.ig.l1": "Entwurfsschritte können Trigger für Kommentare, Direktnachrichten, Stories und Anzeigen beschreiben; der Empfang von Triggern ist nicht aktiviert.",
    "chp.ig.l2": "Prüfe vor einem künftigen Start Metas aktuelle Einwilligungsregeln und Messaging-Zeitfenster; deren Durchsetzung ist hier nicht implementiert.",
    "chp.ig.l3": "Es wird weder eine Versandkapazität noch eine Verringerung von Spam-Meldungen behauptet; das Verhalten des Anbieters wurde nicht getestet.",
    "chp.wa.title": "Wo der MENA-Markt tatsächlich einkauft",
    "chp.wa.lead": "Ein WhatsApp-Ablauf kann für Support- und Commerce-Nachrichten mit vorheriger Einwilligung geplant werden. In dieser Vorschau ist kein Anbieter oder Konto der WhatsApp Business Platform verbunden.",
    "chp.wa.l1": "Vor einer künftigen WhatsApp-Verbindung sind die Anbieterauswahl, Kontozugangsdaten und eine Genehmigung erforderlich.",
    "chp.wa.l2": "Die Einreichung von Vorlagen, die Überwachung von Freigaben und die Abmeldung sind in dieser Vorschau nicht implementiert.",
    "chp.wa.l3": "Es werden keine Aussagen zu Zustellung, Rücklaufquote oder Kosten gemacht.",
    "chp.tt.title": "Wenn der Algorithmus dich begünstigt, sei bereit",
    "chp.tt.lead": "Falls künftig ein unterstützter Anbieter ausgewählt und konfiguriert wird, könnte ein TikTok-Ablauf für Kundenfragen entworfen werden. In dieser Vorschau ist kein TikTok-Konto verbunden und es wird keine Nachricht gesendet.",
    "chp.tt.l1": "Es wurde kein TikTok-Messaging-Anbieter ausgewählt oder verbunden.",
    "chp.tt.l2": "Es wird weder ein Durchsatz noch eine Zustellgarantie zugesagt; Lasttests wurden nicht durchgeführt.",
    "chp.tt.l3": "In-App-Produktlinks sind in dieser Vorschau nicht verfügbar.",
    "chp.tt.s1": "Nicht verbunden",
    "chp.tt.status": "Status des TikTok-Anbieters",
    "chp.tt.s2": "Kein Benchmark",
    "chp.tt.metric": "Durchsatz / Antwortzeit",
    "chp.more.kicker": "Weitere Kanäle auf der Roadmap",
    "chp.more.title": "Messenger, Telegram, SMS, E-Mail und Web-Chat",
    "chp.more.1d": "Roadmap-Ideen umfassen Nachrichten für Seiten und Anzeigen sowie Community-Bots. In dieser Vorschau ist kein Anbieter und kein gemeinsamer Posteingang verbunden.",
    "chp.more.2d": "Roadmap-Ideen umfassen SMS- und E-Mail-Follow-ups mit Einwilligung. Keiner der beiden Anbieter ist in dieser Vorschau verbunden.",
    "ip.availability": "In der aktuellen Vorschau ist kein Drittanbieter-Connector verfügbar. Die genannten Dienste sind nur mögliche künftige Ziele; Verbindung, Synchronisierung, Webhooks und Nachrichtenzustellung sind nicht aktiviert.",
    "ip.1t": "Handel",
    "ip.1d": "Roadmap-Beispiele: Shopify, WooCommerce, BigCommerce, Salla, Zid und Magento. Produkt-, Bestands-, Bestell- und Warenkorbsynchronisierung ist noch nicht verfügbar.",
    "ip.2t": "Zahlungen",
    "ip.2d": "Roadmap-Beispiele: Stripe, Paymob, Fawry, Tap, PayTabs und PayPal. Zahlungslinks, Nachnahmebestätigung und Synchronisierung des Erstattungsstatus sind noch nicht verfügbar.",
    "ip.3t": "CRM und Support",
    "ip.3d": "Roadmap-Beispiele: HubSpot, Zoho, Pipedrive, Freshdesk und Intercom. Lead-Synchronisierung, Notizen und Support-Ticket-Verbindungen sind noch nicht verfügbar.",
    "ip.4t": "Automatisierung und Daten",
    "ip.4d": "Mögliche künftige Ziele: Zapier, Make, n8n, Google Sheets, Airtable, Notion und BigQuery. Trigger und Exporte von Gesprächsereignissen sind noch nicht verfügbar.",
    "ip.5t": "Entwickler-API",
    "ip.5d": "In der aktuellen Vorschau sind keine öffentliche REST-API, Webhooks, SDKs oder Entwickler-Sandbox aktiviert.",
