    "pricing.vendorSub": "Öffentliche USD-Preise, geprüft am 28. Oktober 2026; die angezeigten Monatsäquivalente basieren auf jährlicher Abrechnung. Lokale Preise, Steuern, Kontaktlimits und Bedingungen können je nach Land und Konto abweichen.",
