    "pricing.vendorNote": "Das sind Anbieterpreise, keine Chatora-Preise. Prüfe bei jedem Anbieter aktuelle regionale Abrechnung, Steuern, Testbedingungen und Tariflimits.",
    "pricing.waNote": "WhatsApp-Nachrichtenkosten kommen zusätzlich zum Plattform-Abo hinzu. Der am 7. Oktober 2026 aktualisierte ManyChat-Leitfaden nennt für Ägypten ab dem 1. Oktober folgende Preise: 0,0740 USD für Marketing, 0,0041 USD für Utility und 0,0036 USD für Service. Das sind ManyChat-Angaben, nicht Metas USD-Preisliste. Metas eigene, ebenfalls ab 1. Oktober gültige Preisliste nennt für Ägypten 0,0644 USD für Marketing und 0,0036 USD für Utility, Authentication und Service. Meta stellt pro Unternehmens-Telefonnummer monatlich 1.000 kostenlose Service-Nachrichten bereit; für Utility und Authentication können Mengenstaffeln gelten. Prüfe vor dem Versand den Anbieter, die Kontowährung und die geltenden Voraussetzungen.",
    "pricing.waManychat": "ManyChat-Leitfaden zu WhatsApp-Preisen",
