    "seo.pricing.title": "Chatora-Preise — Tarife und aktuelle Verfügbarkeit | Chatora",
    "seo.pricing.desc": "Chatora hat keine Abo-Preise veröffentlicht und keinen Checkout aktiviert. Die Seite vergleicht datierte Preis-Snapshots von Drittanbietern, nicht Chatora-Preise. Nachrichtenanbieter können separate Gebühren berechnen.",

    "ap.title": "Ein übersichtlicherer Arbeitsbereich für Kundengespräche",
    "ap.s1": "Keine Live-Messaging-Kanäle verbunden",
    "ap.s2": "Bearbeitbare Starter-Entwürfe; nicht für den Produktionseinsatz getestet",
