    "ap.s4": "Keine Preise für Team-Sitze veröffentlicht",
    "ap.vk": "Woran wir glauben",
    "ap.vt": "Fünf Prinzipien, bei denen wir keine Abstriche machen",
    "ap.v1t": "Preise sollten Wachstum nicht bestrafen",
    "ap.v1d": "Preise sollten transparent und verständlich sein. Chatora hat weder Abo-Preise noch Kontaktkontingente oder Bedingungen für Team-Sitze veröffentlicht; die aktuelle Seite ist eine Vorschau, kein kostenpflichtiges Angebot.",
    "ap.v2t": "Offizielle APIs, sonst nichts",
    "ap.v2d": "Die Produktrichtung setzt auf dokumentierte, freigegebene APIs statt Passwortweitergabe oder Scraping. In der aktuellen Vorschau ist kein externer Messaging-Kanal verbunden.",
    "ap.v3t": "Dialekte sind kein Extra",
    "ap.v3d": "Die Vorschau bietet arabische und englische Oberflächen. Live-KI-Antworten mit Dialektanpassung sind nicht aktiviert; Sprachverhalten muss vor einem Versprechen getestet werden.",
    "ap.v4t": "Menschen gehören zum Produkt",
    "ap.v4d": "Die Produktvision nutzt KI für Routineaufgaben und übergibt an einen Menschen, wenn es nötig ist. Live-KI-Antworten sind in der aktuellen Vorschau nicht aktiviert.",
    "ap.v5t": "Ehrliche Vergleiche",
    "ap.v5d": "Unsere Vergleiche sollen die Vorteile etablierter Anbieter zeigen und die Grenzen der Chatora-Vorschau offenlegen; ohne veröffentlichten Chatora-Preis ist keine Ersparnisbehauptung zulässig.",
    "ap.hk": "Produktrichtung",
    "ap.ht": "Ein übersichtlicherer Arbeitsbereich für Gespräche",
    "ap.hd": "Die Vorschau nutzt Supabase für passwortbasierte Konten und kontoisolierte Arbeitsbereichsdaten; Google-Anmeldung ist nicht eingerichtet. Bearbeitbare Flow-Entwürfe, CSV-Kontakttools und Zielgruppen-Vorschauen sind verfügbar, aber Messaging-Kanäle, ausgehende Antworten, ein Live-KI-Agent und Abo-Abrechnung sind nicht aktiviert.",
    "ap.hd2": "Die Produktrichtung verbindet strukturierte Automatisierung mit KI-gestützten Gesprächen. Hier werden keine Kundenergebnisse, veröffentlichten Abo-Preise, Service-Level-Zusagen oder Starttermine behauptet.",
    "ap.cta": "Produktvorschau öffnen",
