    "pg.lead": "Mit dieser lokalen Simulation kannst du Knoten verschieben, Schritte ergänzen und einen Beispielablauf ansehen. Sie verbindet keinen Kanal, speichert nichts im Arbeitsbereich, ruft kein KI-Modell auf und sendet keine Nachrichten.",
    "pg.availability": "Nur Simulation: Schritte laufen in diesem Browser-Tab mit Beispieltext und werden weder gespeichert noch gesendet. Für die Arbeitsbereich-Vorschau öffne das Dashboard; Kanäle und Automatisierung bleiben deaktiviert.",
