    "up.lead": "Illustrative Workflow-Ideen für Shops, Creator, Agenturen und Praxen — keine aktiven Automatisierungen, Kundenfälle oder gemessenen Ergebnisse.",
    "up.availability": "Verfügbarkeit: Die folgenden Beispiele sind illustrative Workflow-Konzepte, keine Kundenfälle. Die Vorschau unterstützt nur bearbeitbare Entwürfe, CSV-Kontakttools und Zielgruppen-Vorschauen; Live-Kanäle, KI-Antworten und gemessene Leistungsergebnisse sind nicht verfügbar.",
    "seo.about.title": "Über Chatora — Produktrichtung und Prinzipien | Chatora",
    "seo.about.desc": "Erfahre mehr über Chatoras Produktrichtung und Prinzipien. Die Vorschau bietet bearbeitbare Entwürfe und CSV-Tools, aber keine Live-Nachrichten oder KI-Antworten.",
