    "up.ec.k": "01 · Online-Shops",
    "up.ec.t": "Support für Warenkorbfragen außerhalb der Öffnungszeiten planen",
    "up.ec.d": "Ein künftiger Warenkorb-Supportablauf könnte Fragen wie „Ist es auf Lager?“, „Passt es?“ oder „Kann ich per Nachnahme zahlen?“ an freigegebene Produkt- und Richtlinieninformationen weiterleiten. Dieser Ablauf ist in der aktuellen Vorschau nicht verbunden.",
