    "up.cr.d": "Ein künftiger Creator-Ablauf könnte häufige Fragen sortieren, einen freigegebenen Antwortentwurf vorbereiten und Nachrichten zur Prüfung durch einen Menschen markieren. Die aktuelle Vorschau verbindet Instagram nicht und sendet keine Antworten.",
