    "bp.nl.t": "Sag uns, ob du an Produktneuigkeiten interessiert bist",
    "bp.nl.d": "Dieses Formular erfasst eine Anfrage zu Produktneuigkeiten; es trägt dich nicht in einen automatisierten Newsletter ein. Es ist weder eine Mailingliste noch eine Abmeldung mit einem Klick verbunden. Lies den Datenschutzhinweis.",
