    "availability.notPublished": "Nicht veröffentlicht",
    "cmp.availability": "Chatora-Status (28. Okt. 2026): nur Produktvorschau. Keine veröffentlichten Preise oder kostenpflichtigen Tarife, keine Live-Kanalverbindungen, keine ausgehenden Nachrichten und keine Live-KI-Antworten. Die Tabellen kennzeichnen die Verfügbarkeit der Chatora-Funktionen; Roadmap-Konzepte sind keine aktuellen Angebote. Wettbewerberzahlen sind datierte öffentliche Momentaufnahmen; bitte vor dem Kauf prüfen.",
    "mc.availability": "Chatora-Status (28. Okt. 2026): nur Produktvorschau. Keine veröffentlichten Preise oder kostenpflichtigen Tarife, keine Live-Kanalverbindungen, keine ausgehenden Nachrichten und keine Live-KI-Antworten. Die Tabellen kennzeichnen die Verfügbarkeit der Chatora-Funktionen; Roadmap-Konzepte sind keine aktuellen Angebote. ManyChat-Zahlen sind datierte öffentliche Momentaufnahmen; bitte vor dem Kauf prüfen.",
    "cf.availability": "Chatora-Status (28. Okt. 2026): nur Produktvorschau. Keine veröffentlichten Preise oder kostenpflichtigen Tarife, keine Live-Kanalverbindungen, keine ausgehenden Nachrichten und keine Live-KI-Antworten. Die Tabellen kennzeichnen die Verfügbarkeit der Chatora-Funktionen; Roadmap-Konzepte sind keine aktuellen Angebote. Chatfuel-Zahlen sind datierte öffentliche Momentaufnahmen; bitte vor dem Kauf prüfen.",
    "alt.badge": "Anbieterseiten am 28. Oktober 2026 geprüft · keine bezahlten Platzierungen",
    "alt.title": "ManyChat-Alternativen 2026: nach Anwendungsfall vergleichen",
    "alt.lead": "Fünf etablierte Alternativen mit aktuellen Anbieter-Snapshots und ihren jeweiligen Kompromissen. Chatora wird transparent als Produktvorschau aufgeführt – nicht als Live-Ersatz für ManyChat: Es gibt weder veröffentlichte Preise noch verbundene Messaging-Kanäle oder Live-KI-Antworten.",
    "alt.cta1": "Zur Vergleichstabelle",
    "alt.cta2": "Veröffentlichten Preisstatus von Chatora ansehen",
    "alt.best": "Produktvorschau · noch keine Live-Alternative",
    "alt.1d": "Chatora bietet derzeit eine kontobasierte Produktvorschau mit bearbeitbaren Flow-Entwürfen und CSV-Kontakttools. Es sind weder ein Abonnementpreis noch ein kostenpflichtiger Tarif veröffentlicht, und es ist kein Messaging-Kanal wie Instagram oder WhatsApp verbunden. Das Produkt kann keine Nachrichten senden und keine Live-KI-Antworten liefern und ist daher noch kein produktiver Ersatz für ManyChat.",
    "alt.previewStrengths": "In der Vorschau verfügbar:",
    "alt.1p": "Arabische und englische Oberfläche, authentifizierter Arbeitsbereich, CSV-Tools und 45 bearbeitbare Starter-Entwürfe.",
    "alt.cons": "Noch nicht verfügbar:",
    "alt.1c": "Live-Messaging, Kanalverbindungen, KI-Antworten, kostenpflichtige Tarife, Migrationsservice und veröffentlichte Supportzusagen.",
    "alt.try": "Bearbeitbare Starter-Entwürfe ansehen",
    "alt.mature": "Etabliertes Ökosystem",
    "alt.mo": "/Monat*",
    "alt.2d": "ManyChat bietet einen ausgereiften visuellen Builder, eine etablierte Community-Bibliothek und fünf veröffentlichte Tarife. Die aktuelle Preisseite nennt 25 Kontakte im Free-Tarif; WhatsApp und KI-gestützte Gespräche sind bei Pro und höheren Tarifen aufgeführt. Angezeigte Preise hängen von Abrechnungszyklus und Land ab.",
    "alt.pros": "Stärken:",
    "alt.2p": "Etablierter Builder, über 60 Vorlagen im Free-Tarif, öffentliches Help Center und Community.",
    "alt.2c": "Limits für aktive Kontakte und Funktionszugang variieren je nach Tarif; regionale Preise und Gebühren für zusätzliche Kontakte sollten vor dem Kauf geprüft werden.",
    "alt.readcmp": "Vollständigen Vergleich lesen",
    "alt.readmc": "Oder direkt gegenüberstellen",
    "alt.agency": "Veröffentlichte Agenturoptionen",
    "alt.3d": "Chatfuel listet Business mit einem Jahresabrechnungs-Äquivalent von 18 $ pro Monat (20 $ bei monatlicher Abrechnung) und 20 $ monatlichem Wallet-Guthaben. Agency S umfasst laut Angebot drei Kundenunternehmen und ein Agentur-Dashboard. KI- und von Meta abgerechnete WhatsApp-Nutzung wird aus dem Wallet bezahlt; die tatsächlichen Kosten hängen von der Nutzung ab.",
    "alt.3p": "Status als offizieller Meta-/WhatsApp-Anbieter, aufgeführte Kanäle, unbegrenzte Kontakte und Teammitglieder sowie ein Agentur-Dashboard.",
    "alt.3c": "Ein dauerhaft kostenloser Tarif ist nicht aufgeführt; der kostenlose Zugang ist eine 7-Tage-Testphase. Wallet-Nutzung und Nachrichtengebühren verursachen variable Kosten.",
    "alt.readcf": "Chatora vs. Chatfuel",
    "alt.support": "Am besten für Support-Abläufe",
    "alt.4d": "Tidio kombiniert Live-Chat, Ticketing und Automatisierung für den Kundensupport. Die offizielle Preisseite nennt Starter mit einem Jahresabrechnungs-Äquivalent von 24,17 $ pro Monat für 100 abrechenbare Unterhaltungen. Lyro AI und Flows haben eigene Kontingente; vergleiche daher die Gesamtnutzung und nicht nur den Basistarif.",
    "alt.4p": "Live-Chat, Ticketing, Support-Abläufe und eine dokumentierte KI-Agent-Option.",
    "alt.4c": "Es gelten Kontingente für Unterhaltungen und Automatisierung; Lyro-AI-/Flows-Nutzung kann zusätzlich zum Basistarif anfallen.",
    "alt.web": "Am besten für Website-Support und -Vertrieb",
    "alt.5d": "ChatBot.coms Essential-Tarif ist mit Jahresabrechnung für 19 $ pro Nutzer und Monat aufgeführt. Er umfasst einen KI-Agenten, Website-Chat, Posteingang und Ticketing; das veröffentlichte Essential-Kontingent beträgt 10 KI-Lösungen pro Monat. Die offizielle Seite nennt außerdem Messenger, WhatsApp und SMS (über Twilio) sowie Shopify-Verkaufsfunktionen.",
    "alt.5p": "Website-Chat, Support-Posteingang und Ticketing, KI-Agenten sowie aufgeführte Commerce-Kanäle.",
    "alt.5c": "Preis pro Nutzer, begrenzte enthaltene KI-Lösungen im Essential-Tarif und kein dauerhaft kostenloser Tarif.",
    "alt.dev": "Am besten für individuelle Konversationsagenten",
    "alt.freeCustom": "Kostenlos · individuell",
    "alt.6d": "Botpress bietet eine anpassbare Agentenplattform mit visuellen Tools und Entwickler-Erweiterungen. Die aktuelle Preisseite nennt im Free-Tarif 100 Unterhaltungen, 3 Plätze und 3 Agenten; Plus beginnt bei 150 $/Monat mit Jahresabrechnung für 250 Unterhaltungen, darüber folgen Team und Enterprise.",
    "alt.6p": "Flexible Tools zum Erstellen von Agenten, ein veröffentlichter kostenloser Tarif und weitere kostenpflichtige Pläne für größere Workloads.",
    "alt.6c": "Unterhaltungslimits und Tarifkosten sind bei größerem Umfang relevant; die Kanalverfügbarkeit unterscheidet sich von Social-first-Automatisierungsplattformen.",
