    "mc.tl": "Die für Oktober 2026 aufgeführten ManyChat-Tarife werden als datierter Snapshot gezeigt; regionale Preise, Abrechnungsintervalle und Verfügbarkeit können abweichen. Chatora hat weder Abonnementstufen noch einen Gratistarif oder Kontaktlimits veröffentlicht. Prüfe vor dem Kauf die aktuellen Bedingungen auf der offiziellen Anbieterseite.",
