    "mc.24": "E-Mail-Support an Werktagen für bezahlte Tarife",
    "mc.foot": "Chatora-Zellen beschreiben die Verfügbarkeit der Vorschau, keine aktuellen Angebote. ManyChat-Tarif-, Preis- und Supportangaben wurden am 28. Okt. 2026 anhand offizieller Seiten geprüft; Preise variieren je Abrechnungsland. Vor dem Kauf prüfen; wir sind nicht affiliiert.",
    "mc.sources": "Preise · WhatsApp-Gebühren · Agenturverzeichnis · Meta-Partnerstatus",
    "mc.wk": "Die ehrliche Einordnung",
    "mc.wt": "Wo ManyChat heute klare Vorteile hat",
    "mc.wd": "Chatora ist noch eine Vorschau und kein Live-Ersatz. Diese bestehenden Stärken von ManyChat sind für Käufer wichtig und sollten vor einem Wechsel berücksichtigt werden.",
    "mc.h1": "ManyChat hat eine ausgereifte Community-Vorlagenbibliothek. Chatoras 45 Elemente sind bearbeitbare Starter-Entwürfe, keine produktionsgetesteten Bots und kein Ersatz-Marktplatz.",
    "mc.h1m": "45 Starter-Entwürfe ansehen",
    "mc.h2": "ManyChat verfügt über ein ausgereiftes Agentur-Ökosystem. Chatora hat weder Agenturpreise noch Kundenabrechnung, Unterkonten oder Mengenrabatte veröffentlicht; Agenturen sollten die aktuelle Vorschau nicht als Ersatz betrachten.",
    "mc.h2m": "Anforderungen von Agenturen teilen",
    "mc.h3": "Ein Team, das bereits auf einer etablierten Plattform geschult ist, kann deren bestehende Abläufe, Dokumentation und Ökosystem vernünftigerweise schätzen. Chatoras Vorschau ist heute kein gleichwertiger Produktiv-Ersatz.",
    "mc.h3m": "Vor einem möglichen Wechsel lesen",
    "mc.ck": "Snapshot veröffentlichter Tarife",
    "mc.ct": "ManyChat-Tarifübersicht vom 28. Oktober 2026",
    "mc.cl": "USD-Preise von der offiziellen ManyChat-Preisseite, geprüft am 28. Okt. 2026, anhand des angezeigten monatlichen Äquivalents bei Jahresabrechnung. Preise hängen vom Land ab; der Checkout-Preis kann abweichen. Chatora hat keinen Tarif und Preis veröffentlicht, daher lassen sich keine Einsparungen berechnen.",
