    "mc.free": "Free",
    "mc.business": "Business",
    "mc.cfoot": "*Angezeigte monatliche USD-Äquivalente von der offiziellen ManyChat-Preisseite (geprüft am 28. Okt. 2026; Abrechnungsland und Zahlungszyklus beeinflussen den Endpreis). Siehe Quellenlinks; es werden weder Chatora-Preis noch Einsparungen behauptet.",
    "mc.pricesource": "Offizielle ManyChat-Preisseite",
    "mc.three": "Lies den Dreifachvergleich mit klar getrennten datierten Anbieter-Snapshots und der Verfügbarkeit von Chatora.",
    "mc.faqt": "Chatora vs. ManyChat: Antworten",
    "mc.q1": "Ist Chatora günstiger als ManyChat?",
    "mc.a1": "Das lässt sich derzeit nicht feststellen. Chatora hat keinen Abonnementpreis veröffentlicht; Live-Kanalverbindungen und KI-Antworten sind nicht aktiviert. Ein aktueller Rechnungs- oder Sparvergleich wäre irreführend.",
    "mc.q2": "Was berechnet ManyChat aktuell?",
    "mc.a2": "Die offizielle ManyChat-Seite führt Tarife auf, deren Preise je nach Abrechnungsland und Zahlungszyklus variieren. Die obige Tabelle ist ein datierter USD-Snapshot vom 28. Okt. 2026 und keine Garantie für den in Ägypten verfügbaren Preis. Prüfe die offizielle Seite und den Checkout-Preis.",
    "mc.q3": "Kann ich ManyChat-Flows zu Chatora übertragen?",
    "mc.a3": "Die aktuelle Vorschau bietet weder einen getesteten Importer noch einen Migrationsservice. Bewahre deine ursprünglichen Exporte auf und kündige oder lösche bestehende Flows nicht aufgrund dieser Website. Importfunktionen können sich nach Implementierung und Tests ändern.",
    "mc.q4": "Verbindet sich Chatora derzeit mit WhatsApp?",
    "mc.a4": "Nein. Chatora verbindet sich derzeit nicht mit WhatsApp und sendet keine Nachrichten. Tech Provider ist der ausgewählte künftige Integrationsweg, aber Meta-Freigabe und App-Konfiguration wurden nicht verifiziert. ManyChat bezeichnet sich als offiziellen Meta-Partner; prüfe vor dem Start den aktuellen Status jedes Anbieters.",
    "mc.q5": "Antwortet Chatora in arabischen Dialekten?",
    "mc.a5": "Die Chatora-Oberfläche ist auf Arabisch verfügbar, aber Live-KI-Antworten sind nicht aktiviert und es wurde kein Dialekt-Benchmark für den Produktivbetrieb veröffentlicht. Wähle eine Plattform nicht allein aufgrund einer Sprachangabe; teste echte Antworten anhand deiner Anwendungsfälle, sobald der Dienst live ist.",
    "cf.badge": "Am 28. Oktober 2026 geprüft",
    "cf.title": "Chatora vs. Chatfuel: Preise, Wallet und Verfügbarkeit 2026",
    "cf.lead": "Chatfuel veröffentlicht ein Modell aus Abonnement und Wallet mit monatlichen Guthaben und nutzungsabhängiger Abrechnung. Chatora ist eine Produktvorschau ohne veröffentlichten Preis, Live-Kanalverbindungen oder KI-Antworten; ein gültiger Kosten- oder Leistungsvergleich ist daher noch nicht möglich. Diese Seite trennt die aktuelle Chatfuel-Dokumentation von der Verfügbarkeit der Chatora-Vorschau.",
