    "cf.foot": "Chatora-Zellen beschreiben die Verfügbarkeit der Vorschau, keine Angebote. Chatfuel-Seiten und Hilfedokumente wurden am 28. Okt. 2026 geprüft; Abrechnungszyklus, Land und tatsächliche Nutzung beeinflussen die Kosten. Prüfe die Bedingungen vor dem Kauf; wir sind nicht affiliiert.",
    "cf.sources": "Preise · Tarife und Wallet · WhatsApp-Gebühren · Gebührenänderungen 2026",
    "cf.wk": "Das Wallet-Modell verstehen",
    "cf.wt": "Enthaltenes Guthaben bedeutet nicht unbegrenzte Nutzung",
    "cf.wd": "Die aktuelle Chatfuel-Dokumentation beschreibt ein Tarif-Wallet: Monatliches Guthaben kann für KI-Antworten und von Meta abgerechnete WhatsApp-Nutzung eingesetzt werden; zusätzlicher Verbrauch hängt von den Wallet-Einstellungen des Kontos ab. Chatora hat weder Live-KI noch verbundene Messaging-Kanäle, daher gibt es noch keine reale Nutzung oder Kosten zum Vergleichen.",
    "cf.wl1": "Der Business-Tarif nennt 20 $ monatliches Guthaben; der Jahrespreis wird jährlich abgerechnet.",
    "cf.wl2": "KI-Antworten und bestimmte WhatsApp-Kosten werden vom Wallet abgezogen.",
    "cf.wl3": "Meta-Tarife variieren je nach Empfängerland und Nachrichtenkategorie.",
    "cf.wl4": "Chatoras Vorschau hat keine Live-KI, Nachrichtengebühren oder veröffentlichten Abonnementpreise.",
