    "pricing.waNote": "As tarifas de mensagens do WhatsApp são cobradas à parte da assinatura da plataforma. O guia da ManyChat, atualizado em 7 de outubro de 2026, lista para o Egito tarifas válidas desde 1º de outubro: US$ 0,0740 para Marketing, US$ 0,0041 para Utility e US$ 0,0036 para Service. Esses são valores publicados pela ManyChat, não a tabela em USD da Meta. A tabela da própria Meta, também válida desde 1º de outubro, lista para o Egito US$ 0,0644 para Marketing e US$ 0,0036 para Utility, Authentication e Service. A Meta oferece 1.000 mensagens de serviço gratuitas por mês para cada número comercial; faixas por volume podem valer para Utility e Authentication. Confirme o provedor, a moeda da conta e os critérios aplicáveis antes de enviar.",
    "pricing.waManychat": "Guia de preços do WhatsApp da ManyChat",
    "pricing.waMeta": "Preços do WhatsApp da Meta",
    "pricing.q1": "Os preços listados da ManyChat e da Chatfuel são preços da Chatora?",
    "pricing.a1": "Não. São registros datados dos fornecedores, verificados em 28 de outubro de 2026. A Chatora não publicou preços de assinatura.",
    "pricing.q2": "A prévia da Chatora cobra uma assinatura?",
    "pricing.a2": "A cobrança e o checkout não estão habilitados na prévia atual. Ela não é um plano de assinatura gratuito publicado.",
    "pricing.q3": "A Chatora consegue enviar mensagens do WhatsApp?",
    "pricing.a3": "Nenhum provedor de WhatsApp ou de outros canais de mensagens está conectado na prévia atual. Rascunhos de fluxo e prévias de público não enviam mensagens.",
    "seo.pricing.title": "Preços da Chatora — planos e disponibilidade atual | Chatora",
    "seo.pricing.desc": "A Chatora não publicou preços de assinatura nem habilitou o checkout. A página compara registros datados de preços de terceiros, não preços da Chatora. Tarifas do provedor de mensagens podem ser cobradas à parte.",

    "ap.title": "Um espaço de trabalho mais claro para conversas com clientes",
    "ap.s1": "Nenhum canal de mensagens ao vivo conectado",
    "ap.s2": "Rascunhos iniciais editáveis; não testados em produção",
    "ap.s3": "Nenhum preço de assinatura publicado",
    "ap.s4": "Nenhum preço por usuário da equipe publicado",
    "ap.vk": "No que acreditamos",
    "ap.vt": "Cinco princípios dos quais não abrimos mão",
    "ap.v1t": "O preço não deve punir o crescimento",
    "ap.v1d": "Os preços devem ser transparentes e fáceis de entender. A Chatora não publicou preços de assinatura, limites de contatos nem condições por usuário da equipe; a página atual é uma prévia, não uma oferta paga.",
    "ap.v2t": "APIs oficiais, ou nada",
    "ap.v2d": "A direção do produto prioriza APIs documentadas e aprovadas, em vez de compartilhamento de senhas ou scraping. Nenhum canal externo de mensagens está conectado na prévia atual.",
    "ap.v3t": "Dialetos não são um detalhe",
    "ap.v3d": "A prévia oferece interfaces em árabe e inglês. Respostas de IA ao vivo com adaptação a dialetos não estão habilitadas; o comportamento linguístico deve ser testado antes de qualquer promessa.",
    "ap.v4t": "As pessoas fazem parte do produto",
    "ap.v4d": "A visão do produto é usar IA em tarefas rotineiras e transferir a conversa para uma pessoa quando necessário. Respostas de IA ao vivo não estão habilitadas na prévia atual.",
    "ap.v5t": "Comparações honestas",
    "ap.v5d": "Nossas comparações devem mostrar as vantagens dos fornecedores estabelecidos e explicar os limites da prévia da Chatora; não cabe alegar economia sem um preço publicado pela Chatora.",
    "ap.hk": "Direção do produto",
    "ap.ht": "Um espaço de trabalho mais claro para conversas",
    "ap.hd": "A prévia usa Supabase para contas com senha e dados de espaço de trabalho isolados por conta; o login do Google não está configurado. Rascunhos de fluxos editáveis, ferramentas CSV para contatos e prévias de público estão disponíveis, mas canais de mensagens, respostas enviadas, agente de IA ao vivo e cobrança por assinatura não estão habilitados.",
    "ap.hd2": "A direção do produto combina automação estruturada com conversas assistidas por IA. Não alegamos resultados de clientes, preço de assinatura publicado, compromisso de nível de serviço nem data de lançamento.",
