    "pg.lead": "Esta simulação local permite arrastar nós, adicionar etapas e visualizar uma execução de exemplo. Ela não conecta canais, não salva em um espaço de trabalho, não consulta modelos de IA e não envia mensagens.",
    "pg.availability": "Somente simulação: as etapas rodam nesta aba do navegador com texto de exemplo e não são salvas nem enviadas. Para a prévia do espaço de trabalho, abra o painel; conexões de canais e automação continuam desativadas.",
