    "up.availability": "Disponibilidade: os exemplos abaixo são conceitos ilustrativos, não estudos de caso. A prévia oferece apenas rascunhos editáveis, ferramentas CSV para contatos e prévias de público; canais ao vivo, respostas de IA e resultados de desempenho medidos não estão disponíveis.",
    "seo.about.title": "Sobre a Chatora — direção do produto e princípios | Chatora",
    "seo.about.desc": "Conheça a direção e os princípios do produto Chatora. A prévia oferece rascunhos editáveis e ferramentas CSV, mas não mensagens ao vivo nem respostas de IA.",
    "seo.playground.title": "Simulador de fluxos no navegador | Chatora",
    "seo.playground.desc": "Teste uma simulação local de fluxos no navegador. Nenhum provedor de mensagens é conectado, nenhum dado de cliente é usado e nenhuma mensagem é enviada.",

    "seo.features.title": "Recursos — marketing de conversas com IA, fluxos visuais e caixa de entrada | Chatora",
    "seo.features.desc": "Explore os conceitos de recursos da Chatora e a prévia atual: rascunhos editáveis, modelos, ferramentas CSV e prévia de público. Respostas de IA e mensagens em canais ao vivo ainda não estão disponíveis.",

    "up.ec.k": "01 · Lojas online",
    "up.ec.t": "Planeje suporte fora do horário para dúvidas sobre carrinho",
    "up.ec.d": "Um futuro fluxo de suporte ao carrinho poderia encaminhar perguntas como “tem em estoque?”, “serve?” ou “posso pagar na entrega?” para informações aprovadas de produtos e políticas. Esse fluxo não está conectado na prévia atual.",
    "up.ec.l1": "Conceito: consultar estoque e variantes por meio de uma futura integração de comércio (indisponível)",
    "up.ec.l2": "Conceito: registrar a confirmação de pagamento na entrega em um rascunho de fluxo",
    "up.ec.l3": "A atribuição de receita não está disponível na prévia atual",
