    "up.cr.t": "Organize conversas com criadores depois de uma publicação movimentada",
    "up.cr.d": "Um futuro fluxo para criadores poderia organizar perguntas frequentes, preparar um rascunho de resposta aprovado e sinalizar mensagens para revisão humana. A prévia atual não se conecta ao Instagram nem envia respostas.",
    "up.cr.l1": "Prevenção de duplicatas e envio em alto volume não estão disponíveis nem foram testados",
    "up.cr.l2": "Um rascunho inicial pode indicar onde um material de captação poderia ser compartilhado",
    "up.cr.l3": "A sincronização com listas de e-mail não está disponível na prévia atual",
