    "up.ag.k": "03 · Agências",
    "up.ag.t": "Dê estrutura clara ao trabalho com vários clientes",
    "up.ag.d": "Uma futura direção do produto para agências poderia separar espaços de trabalho de clientes, permissões e relatórios. Esses controles de agência, SSO, acesso à API e faixas de preço não estão disponíveis na prévia atual.",
    "up.ag.l1": "A separação de espaços de trabalho de agências é um conceito futuro do produto",
    "up.ag.l2": "Limites de usuários da equipe e de acesso de clientes não foram publicados",
    "up.ag.l3": "Relatórios com marca própria não estão disponíveis",
    "up.ag.m1": "Nenhum plano para agências publicado",
    "up.ag.m2": "Limites de usuários não publicados",
