    "up.ag.cta": "Compartilhe sua opinião sobre fluxos para agências →",
    "up.sv.k": "04 · Clínicas e serviços",
    "up.sv.t": "Planeje um fluxo de agendamento antes de conectar um calendário",
    "up.sv.d": "Um futuro fluxo de agendamento poderia coletar um horário preferido, encaminhar dúvidas sobre políticas e preparar um rascunho de lembrete. Integrações de calendário, seguro e agendamento não estão disponíveis na prévia; não insira dados de pacientes ou informações de saúde.",
    "up.sv.l1": "A disponibilidade do calendário e a sincronização de agendamentos não estão conectadas",
    "up.sv.l2": "Não use a prévia para coletar dados de saúde ou sensíveis",
    "up.sv.l3": "O envio de lembretes não está disponível nem foi testado",
    "up.sv.m1": "Sem dados de faltas",
    "up.sv.m2": "Sem dados de agendamentos",
