    "up.sv.cta": "Ver modelos de agendamento →",
    "up.tk": "Mesma base",
    "up.tt": "Negócios diferentes, fluxos ilustrativos",
    "up.td": "São conceitos de fluxo, não serviços ativos. Versões futuras poderiam usar dados aprovados de catálogo e políticas, incluir transferência para uma pessoa e apresentar resultados; nenhum desses recursos de mensagens ao vivo está habilitado nesta prévia.",
    "up.chip1": "45 rascunhos iniciais editáveis",
    "up.chip2": "8 canais planejados · nenhum conectado",
    "up.chip3": "Testar a simulação",
