    "tp.empty": "Nenhum modelo corresponde a essa busca.",
    "tp.search": "Buscar entre 45 modelos…",
    "tp.askbuild": "Compartilhe uma solicitação de fluxo de trabalho →",
    "tp.notice": "Apenas rascunhos iniciais: ao selecionar um cartão, é criado um rascunho editável com etapas genéricas de exemplo — não uma versão configurada do fluxo descrito. Os modelos não foram testados em produção nem conectados a provedores de mensagens, e nenhuma mensagem é enviada. Revise integrações, consentimento e políticas do canal antes de qualquer uso real.",
    "tp.custom.k": "Fluxos personalizados",
    "tp.custom.t": "Precisa de algo que ninguém criou ainda?",
    "tp.custom.d": "Use o criador local para adicionar etapas manualmente e visualizar uma execução de exemplo. Ele não gera fluxos a partir de instruções em linguagem natural, não salva no seu espaço de trabalho nem envia mensagens.",
    "tp.custom.cta": "Abrir a simulação local de fluxos →",
