    "bp.nl.d": "Este formulário registra uma solicitação de interesse em atualizações; ele não inscreve você em uma newsletter automatizada. Nenhuma lista de e-mails nem sistema de cancelamento com um clique está conectado. Consulte o aviso de privacidade.",
