    "availability.notPublished": "Não publicado",
    "cmp.availability": "Status da Chatora (28 out. 2026): apenas prévia do produto. Não há preços nem planos pagos publicados, canais conectados, mensagens enviadas ou respostas de IA ao vivo. As tabelas indicam a disponibilidade dos recursos da Chatora; conceitos de roadmap não são ofertas atuais. Os números dos concorrentes são registros públicos datados; verifique-os antes de comprar.",
    "mc.availability": "Status da Chatora (28 out. 2026): apenas prévia do produto. Não há preços nem planos pagos publicados, canais conectados, mensagens enviadas ou respostas de IA ao vivo. As tabelas indicam a disponibilidade dos recursos da Chatora; conceitos de roadmap não são ofertas atuais. Os números do ManyChat são registros públicos datados; verifique-os antes de comprar.",
    "cf.availability": "Status da Chatora (28 out. 2026): apenas prévia do produto. Não há preços nem planos pagos publicados, canais conectados, mensagens enviadas ou respostas de IA ao vivo. As tabelas indicam a disponibilidade dos recursos da Chatora; conceitos de roadmap não são ofertas atuais. Os números do Chatfuel são registros públicos datados; verifique-os antes de comprar.",
    "alt.badge": "Páginas dos provedores verificadas em 28 de outubro de 2026 · sem posicionamentos pagos",
    "alt.title": "Alternativas ao ManyChat em 2026: compare por caso de uso",
    "alt.lead": "Cinco alternativas estabelecidas, com retratos atuais dos provedores e seus prós e contras. A Chatora aparece com transparência como prévia de produto — não como substituta operacional do ManyChat: não tem preço publicado, canais de mensagens conectados nem respostas de IA ao vivo.",
    "alt.cta1": "Ir para a tabela",
    "alt.cta2": "Ver o status de preços publicado da Chatora",
    "alt.best": "Prévia do produto · ainda não é uma alternativa operacional",
    "alt.1d": "Atualmente, a Chatora oferece uma prévia de produto baseada em contas, com rascunhos de fluxos editáveis e ferramentas CSV para contatos. Nenhum preço de assinatura ou plano pago foi publicado, e nenhum canal de mensagens como Instagram ou WhatsApp está conectado. O produto não pode enviar mensagens nem oferecer respostas de IA ao vivo, portanto ainda não substitui o ManyChat em produção.",
    "alt.previewStrengths": "Disponível na prévia:",
    "alt.1p": "Interface em árabe e inglês, espaço de trabalho autenticado, ferramentas CSV e 45 rascunhos iniciais editáveis.",
    "alt.cons": "Ainda indisponível:",
    "alt.1c": "Mensagens ao vivo, conexões com canais, respostas de IA, planos pagos, serviço de migração e compromissos publicados de suporte.",
    "alt.try": "Explorar rascunhos iniciais editáveis",
    "alt.mature": "Ecossistema estabelecido",
    "alt.mo": "/mês*",
    "alt.2d": "O ManyChat tem um criador visual maduro, uma biblioteca comunitária estabelecida e cinco planos publicados. A página atual de preços lista 25 contatos no Free; WhatsApp e conversas com IA aparecem no Pro e nos planos superiores. Os preços exibidos dependem do ciclo de cobrança e do país.",
    "alt.pros": "Pontos fortes:",
    "alt.2p": "Criador estabelecido, mais de 60 modelos listados no Free, central de ajuda pública e comunidade.",
    "alt.2c": "Os limites de contatos ativos e o acesso a recursos variam conforme o plano; verifique preços regionais e cobranças por contatos adicionais antes de comprar.",
    "alt.readcmp": "Ler o comparativo completo",
    "alt.readmc": "Ou comparar item por item",
    "alt.agency": "Opções para agências publicadas",
    "alt.3d": "O Chatfuel lista o Business por um equivalente de US$ 18 por mês na cobrança anual (US$ 20 na mensal), com US$ 20 em créditos mensais na carteira. A oferta Agency S inclui três empresas clientes e um painel de agência. O uso de IA e do WhatsApp cobrado pela Meta é descontado da carteira; os custos reais dependem do uso.",
    "alt.3p": "Status de provedor oficial da Meta/WhatsApp, canais listados, contatos e integrantes de equipe ilimitados e painel de agência.",
    "alt.3c": "Nenhum nível gratuito permanente é listado; o acesso gratuito é um teste de 7 dias. O uso da carteira e as tarifas de mensagens acrescentam custos variáveis.",
    "alt.readcf": "Chatora vs. Chatfuel",
    "alt.support": "Ideal para fluxos de suporte",
    "alt.4d": "O Tidio combina chat ao vivo, sistema de tickets e automação para suporte ao cliente. A página oficial de preços lista o Starter por um equivalente de US$ 24,17 por mês na cobrança anual para 100 conversas faturáveis. Lyro AI e Flows têm cotas próprias; compare o uso total, não apenas o plano básico.",
    "alt.4p": "Chat ao vivo, tickets, fluxos de suporte e uma opção documentada de agente de IA.",
    "alt.4c": "Há limites de conversas e automações; o uso do Lyro AI/Flows pode ser separado do plano básico.",
    "alt.web": "Ideal para suporte e vendas em sites",
    "alt.5d": "O plano Essential do ChatBot.com é listado por US$ 19 por usuário ao mês com cobrança anual. Inclui um agente de IA, chat no site, caixa de entrada e tickets; a franquia publicada do Essential é de 10 resoluções de IA por mês. A página oficial também lista Messenger, WhatsApp e SMS (via Twilio), além de recursos de venda pelo Shopify.",
    "alt.5p": "Chat no site, caixa de entrada de suporte e tickets, agentes de IA e canais de comércio listados.",
    "alt.5c": "Preço por usuário, poucas resoluções de IA incluídas no Essential e nenhum nível gratuito permanente.",
    "alt.dev": "Ideal para agentes conversacionais personalizados",
    "alt.freeCustom": "Grátis · personalizado",
    "alt.6d": "O Botpress oferece uma plataforma personalizável de agentes, com ferramentas visuais e extensões para desenvolvedores. A página atual de preços lista um plano Free com 100 conversas, 3 assentos e 3 agentes; o Plus começa em US$ 150/mês na cobrança anual para 250 conversas, seguido pelos planos Team e Enterprise.",
    "alt.6p": "Ferramentas flexíveis para criar agentes, um nível gratuito publicado e planos pagos adicionais para cargas maiores.",
    "alt.6c": "Limites de conversas e custos dos planos importam em escala; a disponibilidade de canais difere das plataformas de automação focadas em redes sociais.",
    "alt.tbl.t": "Planos publicados e casos de uso, lado a lado",
    "alt.tbl.s": "Planos dos provedores verificados em 28 de outubro de 2026. Os equivalentes mensais usam cobrança anual quando indicado; a Chatora aparece como prévia de produto, não como alternativa de produção.",
