    "mc.24": "Suporte por e-mail em dias úteis nos planos pagos",
    "mc.foot": "As células da Chatora descrevem a disponibilidade da prévia, não ofertas atuais. Detalhes de planos, preços e suporte do ManyChat foram verificados nas páginas oficiais em 28 out. 2026; os preços variam conforme o país de cobrança. Verifique antes de comprar; não somos afiliados.",
    "mc.sources": "Preços · tarifas do WhatsApp · diretório de agências · status de parceiro da Meta",
    "mc.wk": "A versão honesta",
    "mc.wt": "Onde o ManyChat tem vantagem clara hoje",
    "mc.wd": "A Chatora ainda é uma prévia, não uma substituição ao vivo. Esses pontos fortes atuais do ManyChat importam para compradores e devem ser considerados antes de trocar.",
    "mc.h1": "O ManyChat tem uma biblioteca comunitária madura de modelos. Os 45 itens da Chatora são rascunhos iniciais editáveis, não bots testados em produção nem um marketplace substituto.",
    "mc.h1m": "Explorar 45 rascunhos iniciais",
    "mc.h2": "O ManyChat tem um ecossistema maduro para agências. A Chatora não publicou preços de agência, cobrança de clientes, subcontas nem descontos por volume; agências não devem tratar a prévia atual como substituta.",
    "mc.h2m": "Compartilhar necessidades da agência",
    "mc.h3": "Uma equipe já treinada em uma plataforma estabelecida pode valorizar legitimamente seus fluxos existentes, documentação e ecossistema. A prévia da Chatora ainda não é um substituto equivalente para produção.",
    "mc.h3m": "Leia antes de considerar a troca",
    "mc.ck": "Retrato dos planos publicados",
    "mc.ct": "Planos listados pelo ManyChat em 28 de outubro de 2026",
    "mc.cl": "Preços em USD exibidos na página oficial do ManyChat quando consultada em 28 out. 2026, usando o equivalente mensal exibido na cobrança anual. O preço depende do país; o valor no checkout pode ser diferente. A Chatora não publicou plano nem preço, portanto não é possível calcular economias.",
    "mc.plan": "Plano",
    "mc.contactsIncluded": "Contatos ativos incluídos",
    "mc.priceSnapshot": "Preço listado pelo ManyChat*",
    "mc.free": "Free",
    "mc.business": "Business",
    "mc.cfoot": "*Equivalentes mensais em USD exibidos na página oficial de preços do ManyChat (consultada em 28 out. 2026; país de cobrança e ciclo de pagamento afetam o preço final). Consulte os links das fontes; não afirmamos preço nem economia da Chatora.",
    "mc.pricesource": "Página oficial de preços do ManyChat",
    "mc.three": "Leia a comparação entre três opções, com os retratos datados dos provedores e a disponibilidade da Chatora claramente separados.",
    "mc.faqt": "Chatora vs. ManyChat: respostas",
    "mc.q1": "A Chatora é mais barata que o ManyChat?",
    "mc.a1": "Ainda não é possível determinar. A Chatora não publicou preço de assinatura, e conexões ao vivo com canais e respostas de IA não estão habilitadas. Qualquer comparação atual de faturas ou economia seria enganosa.",
    "mc.q2": "Quanto o ManyChat cobra atualmente?",
    "mc.a2": "A página oficial do ManyChat lista planos cujos preços variam conforme o país de cobrança e o ciclo de pagamento. A tabela acima é um retrato datado em USD, verificado em 28 out. 2026, e não garante o preço disponível no Egito. Confira a página oficial e o preço no checkout.",
    "mc.q3": "Posso transferir meus fluxos do ManyChat para a Chatora?",
    "mc.a3": "A prévia atual não oferece um importador testado nem um serviço de migração. Guarde suas exportações originais e não cancele nem exclua fluxos existentes com base neste site. Os recursos de importação podem mudar depois de implementados e testados.",
    "mc.q4": "A Chatora se conecta ao WhatsApp atualmente?",
    "mc.a4": "Não. Atualmente, a Chatora não se conecta ao WhatsApp nem envia mensagens. Tech Provider é o caminho futuro de integração selecionado, mas a aprovação da Meta e a configuração do aplicativo não foram verificadas. O ManyChat se identifica como parceiro oficial da Meta; confira o status atual de cada provedor antes do lançamento.",
    "mc.q5": "A Chatora responde em dialetos árabes?",
    "mc.a5": "A interface da Chatora está disponível em árabe, mas respostas de IA ao vivo não estão habilitadas e não há referência publicada de desempenho de dialetos em produção. Não escolha uma plataforma apenas com base em uma alegação de idioma; teste respostas reais com seus próprios casos de uso quando o serviço estiver ao vivo.",
    "cf.badge": "Revisado em 28 de outubro de 2026",
    "cf.title": "Chatora vs. Chatfuel: preços, carteira e disponibilidade em 2026",
    "cf.lead": "O Chatfuel publica um modelo de assinatura mais carteira, com créditos mensais e cobrança por uso. A Chatora é uma prévia de produto sem preço publicado, conexões ao vivo com canais ou respostas de IA, portanto ainda não existe uma comparação válida de custos ou desempenho. Esta página separa a documentação atual do Chatfuel da disponibilidade da prévia da Chatora.",
