  "cp.pick.t": "Explorez l’aperçu de Chatora si…",
  "cp.pick.d": "Vous souhaitez examiner des brouillons de flux modifiables, des outils CSV pour les contacts et des aperçus d’audience. Chatora ne peut pas encore remplacer un outil d’automatisation actif : aucun canal, message sortant, réponse IA ou forfait payant n’est disponible.",
  "cp.pick2.t": "Restez sur ManyChat si…",
  "cp.pick2.d": "Vous dépendez de l’éditeur éprouvé de ManyChat, de ses modèles communautaires, de ses intégrations actives ou de son programme d’agences. Gardez votre processus actuel : Chatora ne propose ni connexion à un canal actif ni service de migration dans cet aperçu.",
  "cp.calct": "Aucune estimation valable des économies n’est disponible",
  "cp.calcl": "Chatora n’a publié ni offre payante, ni quota de contacts, ni tarif de dépassement. Un calculateur de coûts ou d’économies laisserait croire à des prix qui n’existent pas.",
  "cp.calcUnavailable": "Consultez la page des tarifs pour les références concurrentes datées, puis confirmez votre région, période de facturation, taxes et usage auprès du fournisseur.",
  "cp.mig.k": "Migration",
  "cp.mig.t": "La migration n’est pas disponible dans l’aperçu actuel",
  "cp.mig.1t": "Conservez une sauvegarde",
  "cp.mig.1d": "Chatora ne propose ni outil d’importation ni service de migration guidée. Exportez vos données et gardez une sauvegarde chez votre fournisseur actuel ; ne présumez pas que les flux, étiquettes ou historiques de messages seront transférés.",
  "cp.mig.2t": "Testez en parallèle",
  "cp.mig.2d": "Avant tout futur changement, vérifiez la propriété des canaux, les consentements, l’exhaustivité des exports et les étapes de migration propres au fournisseur. Chatora ne peut pas encore fonctionner avec un canal actif.",
  "cp.mig.3t": "Basculer",
  "cp.mig.3d": "Ne résiliez pas votre offre actuelle sur la base de cet aperçu. Chatora ne propose aucune connexion à un canal actif, aucune assistance à la migration ni garantie d’économies.",
  "cp.faq.t": "Questions fréquentes sur la migration",
  "cp.q1": "Vais-je perdre mes contacts si je change de plateforme ?",
  "cp.a1": "Chatora ne dispose ni de connexion à un canal ni d’outil d’importation dans cet aperçu. Exportez vos données depuis votre fournisseur actuel et vérifiez ce qui peut être transféré avant d’en changer.",
  "cp.q2": "Chatora est-elle vraiment moins chère, ou seulement sur le papier ?",
  "cp.a2": "Non. Chatora n’a publié aucun tarif d’abonnement, de dépassement ou de canal et ne peut pas envoyer de messages WhatsApp dans cet aperçu. La page des tarifs ne contient que des références tierces datées ; vérifiez les prix régionaux actuels et les frais Meta auprès de chaque fournisseur.",
  "cp.q3": "Puis-je utiliser Chatora et ManyChat en même temps ?",
  "cp.a3": "Chatora ne peut pas se connecter à un canal actif dans l’aperçu actuel ; un test parallèle avec un canal réel n’est donc pas possible. Respectez les règles actuelles du fournisseur avant de changer la propriété du webhook.",
  "cp.q4": "Et si j’ai une grande équipe ?",
  "cp.a4": "Les limites d’utilisateurs et les tarifs n’ont pas été publiés. L’aperçu prend en charge un propriétaire d’espace de travail individuel ; les fonctions de collaboration pour les agences ne sont pas disponibles.",
  "cp.q5": "Proposez-vous une garantie ?",
  "cp.a5": "Non. Chatora ne propose aucune offre payante dans l’aperçu actuel et n’offre aucune garantie de remboursement, d’alignement de prix ou d’économies."
