  "cp.tl": "Disponibilidade da Chatora e planos públicos do ManyChat verificados em 28 de outubro de 2026. Os detalhes dos recursos têm links para a documentação do fornecedor; cobrança e disponibilidade de canais podem variar conforme a conta ou região.",
  "cmp.them": "ManyChat",
