/* Article a4 translations: ManyChat pricing. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a4.h1": "Precios de ManyChat explicados (2026): planes actuales, límites de contactos y facturación",
  "a4.lede": "La página pública de precios de ManyChat muestra cinco niveles de plan. Esta referencia en USD, fechada, presenta los límites de contactos publicados y los equivalentes mensuales con facturación anual; los precios regionales, los impuestos, el acceso a canales y las condiciones de facturación pueden variar, así que confirma la oferta vigente antes de comprar.",
  "a4.date": "Actualizado el 28 de octubre de 2026 · 10 min de lectura",
  "a4.b53": "<b>Referencia consultada el 28 de octubre de 2026:</b> Free figura a 0 USD para 25 contactos. Los equivalentes mensuales con facturación anual son: Essential, 14 USD para 250; Pro, 29 USD para 2.500; Business, 69 USD para 7.500; y Advanced, 139 USD para 25.000. Son precios publicados por el proveedor, no precios de Chatora ni una garantía del importe final de cada cliente.",
  "a4.b1": "Contenido",
  "a4.b2": "<a href=\"#tiers\">Los cinco niveles de la referencia actual</a>",
  "a4.b3": "<a href=\"#billing\">Cómo interpretar los precios mensuales y anuales</a>",
  "a4.b4": "<a href=\"#examples\">Qué plan cubre cada límite de contactos</a>",
  "a4.b5": "<a href=\"#hidden\">Costes y condiciones que debes comprobar</a>",
  "a4.b6": "<a href=\"#cheaper\">Preguntas antes de cambiar de proveedor</a>",
  "a4.b7": "<a href=\"#faq\">Preguntas frecuentes</a>",
  "a4.b8": "1. Los cinco niveles de la referencia actual",
  "a4.b9": "La página de precios muestra los siguientes límites de contactos y precios en USD. Los importes mensuales son equivalentes cuando se selecciona la facturación anual; no son precios de pago mes a mes.",
  "a4.b10": "<strong>Free — 0 USD:</strong> 25 contactos.",
  "a4.b11": "<strong>Essential — equivalente a 14 USD/mes con facturación anual:</strong> 250 contactos.",
  "a4.b12": "<strong>Pro — equivalente a 29 USD/mes con facturación anual:</strong> 2.500 contactos.",
  "a4.b13": "<strong>Business — equivalente a 69 USD/mes con facturación anual:</strong> 7.500 contactos.",
  "a4.b14": "<strong>Advanced — equivalente a 139 USD/mes con facturación anual:</strong> 25.000 contactos.",
  "a4.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Página de precios de ManyChat</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guía de precios de WhatsApp</a>",
  "a4.b15": "2. Cómo interpretar los precios mensuales y anuales",
  "a4.b16": "Los importes anteriores se presentan como equivalentes mensuales con facturación anual. Antes de compararlos con una oferta de pago mensual, revisa en la pantalla de pago el intervalo real, el cargo total por adelantado, la moneda y los impuestos locales aplicables.",
  "a4.b17": "Elige la facturación anual solo si el plazo y el límite de contactos se ajustan al uso previsto. Si tu audiencia crece rápidamente, compara el siguiente nivel y las condiciones escritas del proveedor sobre excesos o cambios de plan; no supongas que existe un cargo concreto por contacto adicional.",
  "a4.b18": "3. Qué plan cubre cada límite de contactos",
  "a4.b19": "Estos ejemplos indican el nivel publicado cuyo límite cubre el número de contactos señalado. No son estimaciones del coste total: debes comprobar por separado el acceso a funciones, la facturación regional y las reglas sobre excesos.",
  "a4.b20": "25 contactos",
  "a4.b21": "La referencia pública muestra Free a 0 USD con 25 contactos. Si necesitas algo más que el límite de contactos, revisa sus límites actuales de canales y funciones.",
  "a4.b22": "1.000 contactos",
  "a4.b23": "Según los niveles publicados aquí, 1.000 contactos quedan dentro del límite de 2.500 del plan Pro, cuyo equivalente mensual es de 29 USD con facturación anual. Confirma las funciones incluidas y el precio regional en la página oficial.",
  "a4.b24": "5.000 contactos",
  "a4.b25": "Business es el nivel publicado que cubre 5.000 contactos: permite 7.500, con un equivalente mensual de 69 USD si se factura anualmente. Esta es solo una referencia del precio de suscripción.",
  "a4.b26": "15.000 contactos",
  "a4.b27": "Advanced es el nivel publicado que cubre 15.000 contactos: permite 25.000, con un equivalente mensual de 139 USD si se factura anualmente. Para volúmenes mayores, solicita las condiciones vigentes en vez de extrapolar.",
  "a4.b28": "Los límites ayudan a identificar un nivel inicial, pero por sí solos no determinan el importe final. También importan el ciclo de facturación, el país, los impuestos, las funciones y el uso de mensajes.",
  "a4.b29": "4. Costes y condiciones que debes comprobar",
  "a4.b30": "<strong>Tarifas de mensajes de WhatsApp.</strong> Son independientes de la suscripción a la plataforma y dependen de la categoría del mensaje, el mercado del destinatario y la facturación del proveedor. La guía de ManyChat y la tarifa de Meta no son intercambiables; compara cada fuente con tu factura.",
  "a4.b31": "<strong>Usuarios y acceso a canales.</strong> La disponibilidad de usuarios y canales puede variar según el nivel. Consulta la tabla actual para confirmar cuántos usuarios y canales necesita tu equipo.",
  "a4.b32": "<strong>Disponibilidad de funciones.</strong> Las herramientas de IA y los canales de mensajería pueden estar limitados a ciertos niveles. Antes de subir de plan, confirma qué se incluye actualmente en tu país.",
  "a4.b33": "<strong>Uso y excesos.</strong> No supongas que sigue vigente una tarifa histórica por contacto. Pregunta a ManyChat cómo trata los contactos que superan el límite y cuándo entra en vigor un cambio de nivel.",
  "a4.b34": "<strong>Moneda e impuestos.</strong> Los ejemplos en USD pueden no coincidir con el importe mostrado para tu país de facturación; los impuestos, los tipos de cambio y las ofertas locales pueden modificar el cargo final.",
  "a4.b35": "5. Preguntas antes de cambiar de proveedor",
  "a4.b36": "<strong>Confirma qué significa «contacto».</strong> Lee la definición de facturación vigente y comprueba qué contactos cuentan para el límite elegido.",
  "a4.b37": "<strong>Compara el siguiente nivel.</strong> Pregunta si subir de plan o aplicar las condiciones actuales del proveedor por exceso resulta más económico para la audiencia prevista.",
  "a4.b38": "<strong>Compara periodos de facturación equivalentes.</strong> Separa los equivalentes mensuales con facturación anual de los precios mes a mes y anota cualquier compromiso de pago por adelantado.",
  "a4.b39": "<strong>Comprueba la disponibilidad real de la alternativa.</strong> Chatora no ha publicado precios de suscripción ni habilitado la mensajería por canales en directo, por lo que ahora no es posible hacer una comparación válida de costes o funciones.",
  "a4.b40": "¿Qué publica Chatora actualmente?",
  "a4.b41": "Chatora es una vista previa del producto, no una oferta de suscripción publicada. Consulta su disponibilidad actual y compara las condiciones de los proveedores con tus propios datos de uso.",
  "a4.cta": "Consultar disponibilidad actual →",
  "a4.b42": "6. Preguntas frecuentes",
  "a4.b43": "¿ManyChat es gratuito?",
  "a4.b44": "La página pública consultada el 28 de octubre de 2026 muestra un plan Free a 0 USD para 25 contactos. Consulta la página vigente para conocer las condiciones regionales y las funciones incluidas.",
  "a4.b45": "¿Qué planes incluyen IA o WhatsApp?",
  "a4.b46": "Las páginas actuales de precios y ayuda de ManyChat describen el acceso a funciones según el plan. Antes de elegir un nivel, confirma en tu cuenta qué incluye exactamente en IA y WhatsApp, cuáles son los límites de uso y qué disponibilidad regional hay.",
  "a4.b47": "¿Qué se considera un contacto activo?",
  "a4.b48": "Consulta la definición de facturación vigente de ManyChat; no supongas que todos los proveedores o planes cuentan los contactos de la misma manera.",
  "a4.b49": "¿La facturación anual cambia el límite de contactos?",
  "a4.b50": "La referencia pública muestra el mismo límite de contactos para cada plan, independientemente del equivalente de facturación indicado. Confirma las condiciones en el pago antes de comprar.",
  "a4.b51": "¿Qué ocurre si supero el límite?",
  "a4.b52": "El tratamiento exacto de los excesos o las mejoras de plan puede depender del plan y de las condiciones de facturación vigentes. Consulta las condiciones escritas más recientes de ManyChat; esta referencia no estima un cargo por exceso.",
  "a4.b54": "Fuentes: página pública de precios de ManyChat y páginas de su centro de ayuda, consultadas el 28 de octubre de 2026. Los equivalentes mensuales son ejemplos con facturación anual; los precios y las condiciones varían según la región y pueden cambiar. Chatora no ha publicado un precio de suscripción.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a4.h1": "Tarifs ManyChat expliqués (2026) : offres actuelles, quotas de contacts et facturation",
  "a4.lede": "La page publique des tarifs de ManyChat présente cinq niveaux d’offres. Cet instantané daté en USD indique les quotas de contacts publiés et les équivalents mensuels en cas de facturation annuelle ; les tarifs régionaux, les taxes, l’accès aux canaux et les conditions de facturation peuvent varier. Vérifiez donc l’offre actuelle avant tout achat.",
  "a4.date": "Mis à jour le 28 octobre 2026 · 10 min de lecture",
  "a4.b53": "<b>Instantané vérifié le 28 octobre 2026 :</b> Free est affiché à 0 $ pour 25 contacts. Les équivalents mensuels avec facturation annuelle sont : Essential, 14 $ pour 250 ; Pro, 29 $ pour 2 500 ; Business, 69 $ pour 7 500 ; et Advanced, 139 $ pour 25 000. Ce sont les tarifs publiés par le fournisseur, pas des tarifs Chatora ni une garantie du montant final payé par un client.",
  "a4.b1": "Sommaire",
  "a4.b2": "<a href=\"#tiers\">Les cinq niveaux de l’instantané actuel</a>",
  "a4.b3": "<a href=\"#billing\">Comprendre les prix mensuels et annuels</a>",
  "a4.b4": "<a href=\"#examples\">Choisir selon le quota de contacts</a>",
  "a4.b5": "<a href=\"#hidden\">Frais et conditions à vérifier</a>",
  "a4.b6": "<a href=\"#cheaper\">Questions à se poser avant de changer</a>",
  "a4.b7": "<a href=\"#faq\">FAQ</a>",
  "a4.b8": "1. Les cinq niveaux de l’instantané actuel",
  "a4.b9": "La page tarifaire indique les quotas de contacts et les prix en USD suivants. Les montants mensuels ci-dessous sont des équivalents lorsque la facturation annuelle est sélectionnée ; ce ne sont pas des tarifs mensuels sans engagement.",
  "a4.b10": "<strong>Free — 0 $ :</strong> 25 contacts.",
  "a4.b11": "<strong>Essential — équivalent de 14 $/mois avec facturation annuelle :</strong> 250 contacts.",
  "a4.b12": "<strong>Pro — équivalent de 29 $/mois avec facturation annuelle :</strong> 2 500 contacts.",
  "a4.b13": "<strong>Business — équivalent de 69 $/mois avec facturation annuelle :</strong> 7 500 contacts.",
  "a4.b14": "<strong>Advanced — équivalent de 139 $/mois avec facturation annuelle :</strong> 25 000 contacts.",
  "a4.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Page tarifaire de ManyChat</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guide tarifaire WhatsApp</a>",
  "a4.b15": "2. Comprendre les prix mensuels et annuels",
  "a4.b16": "Les montants ci-dessus sont présentés comme des équivalents mensuels avec facturation annuelle. Avant de les comparer à un devis mensuel, vérifiez sur la page de paiement la périodicité réelle, le montant total à régler d’avance, la devise et les taxes locales éventuelles.",
  "a4.b17": "Choisissez la facturation annuelle uniquement si la durée et le quota de contacts correspondent à votre usage prévisionnel. Si votre audience grandit vite, comparez l’offre supérieure et les conditions écrites de dépassement ou de changement d’offre du fournisseur ; ne présumez pas d’un tarif précis par contact supplémentaire.",
  "a4.b18": "3. Choisir selon le quota de contacts",
  "a4.b19": "Ces exemples indiquent l’offre publiée dont le quota couvre le nombre de contacts mentionné. Ce ne sont pas des estimations tout compris : vérifiez séparément l’accès aux fonctionnalités, la facturation régionale et les règles de dépassement.",
  "a4.b20": "25 contacts",
  "a4.b21": "L’instantané public affiche Free à 0 $ pour 25 contacts. Si vous avez besoin d’autre chose que du quota de contacts, vérifiez les limites actuelles de canaux et de fonctionnalités.",
  "a4.b22": "1 000 contacts",
  "a4.b23": "Selon les offres publiées ici, 1 000 contacts relèvent du quota Pro de 2 500 contacts, affiché à un équivalent de 29 $ par mois avec facturation annuelle. Confirmez les fonctionnalités incluses et le tarif régional sur la page officielle.",
  "a4.b24": "5 000 contacts",
  "a4.b25": "Business est l’offre publiée qui couvre 5 000 contacts : son quota est de 7 500, à un équivalent de 69 $ par mois avec facturation annuelle. Il s’agit uniquement de l’instantané de l’abonnement.",
  "a4.b26": "15 000 contacts",
  "a4.b27": "Advanced est l’offre publiée qui couvre 15 000 contacts : son quota est de 25 000, à un équivalent de 139 $ par mois avec facturation annuelle. Pour des volumes supérieurs, demandez les conditions actuelles au lieu d’extrapoler.",
  "a4.b28": "Les quotas aident à choisir une première offre, mais ne déterminent pas à eux seuls le montant final. Le cycle de facturation, le pays, les taxes, les fonctionnalités et le volume de messages comptent aussi.",
  "a4.b29": "4. Frais et conditions à vérifier",
  "a4.b30": "<strong>Frais de messages WhatsApp.</strong> Ils s’ajoutent à l’abonnement de la plateforme et dépendent de la catégorie du message, du marché du destinataire et de la facturation du fournisseur. Le guide de ManyChat et la grille de Meta ne sont pas interchangeables ; comparez chaque source à votre facture.",
  "a4.b31": "<strong>Sièges et accès aux canaux.</strong> Le nombre d’utilisateurs et les canaux disponibles peuvent varier selon l’offre. Consultez le tableau actuel pour vérifier les besoins de votre équipe.",
  "a4.b32": "<strong>Disponibilité des fonctionnalités.</strong> Les outils d’IA et les canaux de messagerie peuvent être réservés à certains niveaux. Vérifiez les inclusions actuelles dans votre pays avant de changer d’offre.",
  "a4.b33": "<strong>Utilisation et dépassements.</strong> Ne supposez pas qu’un ancien tarif par contact est toujours valable. Demandez à ManyChat comment sont traités les contacts au-delà du quota et quand un changement d’offre prend effet.",
  "a4.b34": "<strong>Devise et taxes.</strong> Les exemples en USD peuvent différer du montant affiché dans votre pays de facturation ; les taxes, les taux de change et les offres locales peuvent modifier le montant final.",
  "a4.b35": "5. Questions à se poser avant de changer",
  "a4.b36": "<strong>Vérifiez la définition de « contact ».</strong> Consultez la définition de facturation actuelle et vérifiez quels contacts sont comptabilisés dans le quota choisi.",
  "a4.b37": "<strong>Comparez l’offre supérieure.</strong> Demandez si le changement d’offre ou les conditions actuelles de dépassement du fournisseur coûtent moins cher pour l’audience prévue.",
  "a4.b38": "<strong>Comparez des périodes de facturation équivalentes.</strong> Distinguez les équivalents mensuels avec facturation annuelle des tarifs mensuels sans engagement et notez tout paiement anticipé.",
  "a4.b39": "<strong>Vérifiez la disponibilité réelle de l’alternative.</strong> Chatora n’a publié aucun tarif d’abonnement et n’a pas activé la messagerie sur des canaux en direct ; il est donc impossible pour le moment de comparer valablement les coûts ou les fonctionnalités.",
  "a4.b40": "Que publie Chatora aujourd’hui ?",
  "a4.b41": "Chatora est un aperçu de produit, pas une offre d’abonnement publiée. Consultez son état de disponibilité et comparez les conditions des fournisseurs à partir de votre propre usage.",
  "a4.cta": "Consulter la disponibilité actuelle →",
  "a4.b42": "6. FAQ",
  "a4.b43": "ManyChat est-il gratuit ?",
  "a4.b44": "La page publique consultée le 28 octobre 2026 affiche l’offre Free à 0 $ pour 25 contacts. Consultez la page actuelle pour connaître les conditions régionales et les fonctionnalités incluses.",
  "a4.b45": "Quelles offres comprennent l’IA ou WhatsApp ?",
  "a4.b46": "Les pages actuelles des tarifs et d’aide de ManyChat décrivent l’accès aux fonctionnalités selon l’offre. Avant de choisir un niveau, vérifiez dans votre compte les inclusions exactes pour l’IA et WhatsApp, les limites d’utilisation et la disponibilité régionale.",
  "a4.b47": "Qu’est-ce qu’un contact actif ?",
  "a4.b48": "Consultez la définition de facturation actuelle de ManyChat ; ne supposez pas que les fournisseurs ou les offres comptabilisent les contacts de la même manière.",
  "a4.b49": "La facturation annuelle modifie-t-elle le quota de contacts ?",
  "a4.b50": "L’instantané public indique le même quota de contacts pour chaque offre, quel que soit l’équivalent de facturation affiché. Confirmez les conditions au moment du paiement avant tout achat.",
  "a4.b51": "Que se passe-t-il si je dépasse mon quota ?",
  "a4.b52": "Le traitement des dépassements ou des changements d’offre dépend des conditions actuelles du forfait et de facturation. Consultez les dernières conditions écrites de ManyChat ; cet instantané ne chiffre pas les dépassements.",
  "a4.b54": "Sources : page tarifaire publique de ManyChat et pages de son centre d’aide, consultées le 28 octobre 2026. Les équivalents mensuels sont des exemples avec facturation annuelle ; les prix et conditions des offres varient selon la région et peuvent évoluer. Chatora n’a publié aucun tarif d’abonnement.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a4.h1": "ManyChat-Preise erklärt (2026): aktuelle Tarife, Kontaktlimits und Abrechnung",
  "a4.lede": "Die öffentliche Preisseite von ManyChat führt fünf Tarifstufen auf. Diese datierte USD-Übersicht zeigt die veröffentlichten Kontaktlimits und Monatsäquivalente bei Jahresabrechnung; regionale Preise, Steuern, Kanalzugang und Abrechnungsbedingungen können abweichen. Prüfe daher vor dem Kauf das aktuelle Angebot.",
  "a4.date": "Aktualisiert am 28. Oktober 2026 · 10 Min. Lesezeit",
  "a4.b53": "<b>Stand der Prüfung: 28. Oktober 2026:</b> Free ist mit 0 USD für 25 Kontakte aufgeführt. Die Monatsäquivalente bei Jahresabrechnung lauten: Essential 14 USD für 250, Pro 29 USD für 2.500, Business 69 USD für 7.500 und Advanced 139 USD für 25.000. Dies sind vom Anbieter veröffentlichte Tarifpreise, keine Chatora-Preise und keine Garantie für die endgültige Rechnung eines Kunden.",
  "a4.b1": "Inhalt",
  "a4.b2": "<a href=\"#tiers\">Die fünf Stufen der aktuellen Übersicht</a>",
  "a4.b3": "<a href=\"#billing\">Monats- und Jahrespreise richtig lesen</a>",
  "a4.b4": "<a href=\"#examples\">Tarif passend zum Kontaktlimit</a>",
  "a4.b5": "<a href=\"#hidden\">Zu prüfende Kosten und Bedingungen</a>",
  "a4.b6": "<a href=\"#cheaper\">Fragen vor einem Wechsel</a>",
  "a4.b7": "<a href=\"#faq\">Häufige Fragen</a>",
  "a4.b8": "1. Die fünf Stufen der aktuellen Übersicht",
  "a4.b9": "Die Preisseite nennt die folgenden Kontaktlimits und USD-Preise. Die Monatsbeträge unten sind Monatsäquivalente bei ausgewählter Jahresabrechnung; es sind keine Monat-zu-Monat-Preise.",
  "a4.b10": "<strong>Free — 0 USD:</strong> 25 Kontakte.",
  "a4.b11": "<strong>Essential — Monatsäquivalent 14 USD bei Jahresabrechnung:</strong> 250 Kontakte.",
  "a4.b12": "<strong>Pro — Monatsäquivalent 29 USD bei Jahresabrechnung:</strong> 2.500 Kontakte.",
  "a4.b13": "<strong>Business — Monatsäquivalent 69 USD bei Jahresabrechnung:</strong> 7.500 Kontakte.",
  "a4.b14": "<strong>Advanced — Monatsäquivalent 139 USD bei Jahresabrechnung:</strong> 25.000 Kontakte.",
  "a4.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">ManyChat-Preisseite</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Leitfaden zu WhatsApp-Preisen</a>",
  "a4.b15": "2. Monats- und Jahrespreise richtig lesen",
  "a4.b16": "Die oben genannten Beträge sind Monatsäquivalente bei Jahresabrechnung. Prüfe im Checkout das tatsächliche Abrechnungsintervall, den gesamten Vorauszahlungsbetrag, die Währung und mögliche lokale Steuern, bevor du sie mit einem monatlich kündbaren Angebot vergleichst.",
  "a4.b17": "Wähle die Jahresabrechnung nur, wenn Laufzeit und Kontaktlimit zu deinem erwarteten Bedarf passen. Wenn deine Zielgruppe schnell wächst, vergleiche die nächste Tarifstufe und die schriftlichen Bedingungen zu Überschreitungen oder Tarifwechseln, statt einen bestimmten Preis je zusätzlichem Kontakt anzunehmen.",
  "a4.b18": "3. Tarif passend zum Kontaktlimit",
  "a4.b19": "Diese Beispiele zeigen den veröffentlichten Tarif, dessen Limit die angegebene Kontaktzahl abdeckt. Sie sind keine Gesamtkostenschätzungen: Funktionszugang, regionale Abrechnung und Regeln für Überschreitungen müssen separat geprüft werden.",
  "a4.b20": "25 Kontakte",
  "a4.b21": "Die öffentliche Übersicht nennt Free mit 0 USD für 25 Kontakte. Wenn du mehr als das Kontaktlimit benötigst, prüfe die aktuellen Kanal- und Funktionsgrenzen.",
  "a4.b22": "1.000 Kontakte",
  "a4.b23": "Nach den hier gezeigten Tarifen liegen 1.000 Kontakte innerhalb des Pro-Limits von 2.500, das bei Jahresabrechnung mit einem Monatsäquivalent von 29 USD aufgeführt ist. Bestätige Funktionsumfang und regionalen Preis auf der offiziellen Seite.",
  "a4.b24": "5.000 Kontakte",
  "a4.b25": "Business ist der veröffentlichte Tarif für 5.000 Kontakte: Das Limit beträgt 7.500, bei einem Monatsäquivalent von 69 USD mit Jahresabrechnung. Dies ist nur eine Momentaufnahme des Abonnementpreises.",
  "a4.b26": "15.000 Kontakte",
  "a4.b27": "Advanced ist der veröffentlichte Tarif für 15.000 Kontakte: Das Limit beträgt 25.000, bei einem Monatsäquivalent von 139 USD mit Jahresabrechnung. Frage bei höheren Volumen die aktuellen Konditionen an, statt sie hochzurechnen.",
  "a4.b28": "Die Limits helfen bei der Wahl einer Einstiegskategorie, bestimmen aber nicht allein die Endrechnung. Abrechnungszyklus, Land, Steuern, Funktionen und Nachrichtenvolumen spielen ebenfalls eine Rolle.",
  "a4.b29": "4. Zu prüfende Kosten und Bedingungen",
  "a4.b30": "<strong>WhatsApp-Nachrichtengebühren.</strong> Sie fallen zusätzlich zum Plattformabonnement an und hängen von Nachrichtenkategorie, Empfängermarkt und Anbieterabrechnung ab. Der ManyChat-Leitfaden und Metas Preisliste sind nicht austauschbar; vergleiche beide Quellen mit deiner Rechnung.",
  "a4.b31": "<strong>Nutzerplätze und Kanalzugang.</strong> Nutzer- und Kanalverfügbarkeit kann je Tarifstufe abweichen. Prüfe in der aktuellen Tarifübersicht, wie viele Nutzer und Kanäle dein Team benötigt.",
  "a4.b32": "<strong>Funktionsverfügbarkeit.</strong> KI-Werkzeuge und Messaging-Kanäle können bestimmten Tarifstufen vorbehalten sein. Prüfe vor einem Upgrade die aktuellen Leistungen in deinem Land.",
  "a4.b33": "<strong>Nutzung und Überschreitungen.</strong> Gehe nicht davon aus, dass ein früherer Preis je Kontakt noch gilt. Frage ManyChat, wie Kontakte oberhalb des Limits behandelt werden und wann ein Tarifwechsel wirksam wird.",
  "a4.b34": "<strong>Währung und Steuern.</strong> USD-Beispiele müssen nicht dem Betrag entsprechen, der für dein Abrechnungsland angezeigt wird; Steuern, Wechselkurse und lokale Angebote können den Endbetrag verändern.",
  "a4.b35": "5. Fragen vor einem Wechsel",
  "a4.b36": "<strong>Prüfe, was als „Kontakt“ gilt.</strong> Lies die aktuelle Abrechnungsdefinition und kläre, welche Kontakte auf dein gewähltes Limit angerechnet werden.",
  "a4.b37": "<strong>Vergleiche die nächste Tarifstufe.</strong> Frage, ob ein Upgrade oder die aktuellen Überschreitungsbedingungen des Anbieters für deine erwartete Zielgruppe günstiger sind.",
  "a4.b38": "<strong>Vergleiche gleiche Abrechnungszeiträume.</strong> Trenne Monatsäquivalente bei Jahresabrechnung von Monat-zu-Monat-Preisen und notiere mögliche Vorauszahlungen.",
  "a4.b39": "<strong>Prüfe die tatsächliche Verfügbarkeit der Alternative.</strong> Chatora hat keine Abonnementpreise veröffentlicht und keinen Live-Kanalnachrichtenversand aktiviert. Ein gültiger Kosten- oder Funktionsvergleich ist daher derzeit nicht möglich.",
  "a4.b40": "Was veröffentlicht Chatora derzeit?",
  "a4.b41": "Chatora ist eine Produktvorschau und kein veröffentlichtes Abonnementangebot. Prüfe den aktuellen Verfügbarkeitsstatus und vergleiche Anbieterbedingungen anhand deiner eigenen Nutzung.",
  "a4.cta": "Aktuelle Verfügbarkeit prüfen →",
  "a4.b42": "6. Häufige Fragen",
  "a4.b43": "Ist ManyChat kostenlos?",
  "a4.b44": "Die am 28. Oktober 2026 geprüfte öffentliche Seite nennt einen Free-Tarif mit 0 USD für 25 Kontakte. Prüfe die aktuelle Seite auf regionale Bedingungen und enthaltene Funktionen.",
  "a4.b45": "Welche Tarife enthalten KI oder WhatsApp?",
  "a4.b46": "Die aktuellen Preis- und Hilfeseiten von ManyChat beschreiben den Funktionszugang je Tarif. Prüfe vor der Wahl in deinem Konto die genauen KI- und WhatsApp-Leistungen, Nutzungslimits und regionale Verfügbarkeit.",
  "a4.b47": "Was gilt als aktiver Kontakt?",
  "a4.b48": "Nutze ManyChats aktuelle Abrechnungsdefinition und gehe nicht davon aus, dass Anbieter oder Tarife Kontakte gleich zählen.",
  "a4.b49": "Ändert die Jahresabrechnung das Kontaktlimit?",
  "a4.b50": "Die öffentliche Übersicht weist für jeden Tarif unabhängig vom angezeigten Abrechnungsäquivalent dasselbe Kontaktlimit aus. Prüfe vor dem Kauf die Checkout-Bedingungen.",
  "a4.b51": "Was passiert, wenn ich mein Limit überschreite?",
  "a4.b52": "Die genaue Behandlung von Überschreitungen oder Upgrades hängt möglicherweise vom aktuellen Tarif und den Abrechnungsbedingungen ab. Prüfe die neuesten schriftlichen Bedingungen von ManyChat; diese Übersicht schätzt keine Überschreitungsgebühr.",
  "a4.b54": "Quellen: öffentliche ManyChat-Preisseite und Help-Center-Seiten, geprüft am 28. Oktober 2026. Die Monatsäquivalente sind Beispiele bei Jahresabrechnung; Preise und Tarifbedingungen unterscheiden sich regional und können sich ändern. Chatora hat keinen Abonnementpreis veröffentlicht.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a4.h1": "Preços do ManyChat explicados (2026): planos atuais, limites de contatos e cobrança",
  "a4.lede": "A página pública de preços do ManyChat lista cinco níveis de plano. Este retrato datado em USD mostra os limites de contatos publicados e os equivalentes mensais na cobrança anual; preços regionais, impostos, acesso a canais e condições de cobrança podem variar. Confira a oferta atual antes de comprar.",
  "a4.date": "Atualizado em 28 de outubro de 2026 · 10 min de leitura",
  "a4.b53": "<b>Retrato consultado em 28 de outubro de 2026:</b> o Free aparece por US$ 0 para 25 contatos. Os equivalentes mensais na cobrança anual são: Essential, US$ 14 para 250; Pro, US$ 29 para 2.500; Business, US$ 69 para 7.500; e Advanced, US$ 139 para 25.000. São preços de planos publicados pelo fornecedor, não preços da Chatora nem garantia do valor final da fatura de cada cliente.",
  "a4.b1": "Conteúdo",
  "a4.b2": "<a href=\"#tiers\">Os cinco níveis do retrato atual</a>",
  "a4.b3": "<a href=\"#billing\">Como interpretar preços mensais e anuais</a>",
  "a4.b4": "<a href=\"#examples\">Plano adequado ao limite de contatos</a>",
  "a4.b5": "<a href=\"#hidden\">Custos e condições a conferir</a>",
  "a4.b6": "<a href=\"#cheaper\">Perguntas antes de trocar</a>",
  "a4.b7": "<a href=\"#faq\">Perguntas frequentes</a>",
  "a4.b8": "1. Os cinco níveis do retrato atual",
  "a4.b9": "A página de preços lista os seguintes limites de contatos e valores em USD. Os valores mensais abaixo são equivalentes quando se escolhe a cobrança anual; não são preços para pagamento mês a mês.",
  "a4.b10": "<strong>Free — US$ 0:</strong> 25 contatos.",
  "a4.b11": "<strong>Essential — equivalente a US$ 14/mês na cobrança anual:</strong> 250 contatos.",
  "a4.b12": "<strong>Pro — equivalente a US$ 29/mês na cobrança anual:</strong> 2.500 contatos.",
  "a4.b13": "<strong>Business — equivalente a US$ 69/mês na cobrança anual:</strong> 7.500 contatos.",
  "a4.b14": "<strong>Advanced — equivalente a US$ 139/mês na cobrança anual:</strong> 25.000 contatos.",
  "a4.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Página de preços do ManyChat</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guia de preços do WhatsApp</a>",
  "a4.b15": "2. Como interpretar preços mensais e anuais",
  "a4.b16": "Os valores acima são apresentados como equivalentes mensais na cobrança anual. Antes de compará-los com uma cotação mês a mês, confira na tela de pagamento o intervalo real de cobrança, o total antecipado, a moeda e os impostos locais aplicáveis.",
  "a4.b17": "Escolha a cobrança anual somente se o prazo e o limite de contatos forem adequados ao uso esperado. Se seu público estiver crescendo rapidamente, compare o próximo nível e as condições escritas do fornecedor para excedentes ou mudança de plano; não presuma um valor específico por contato adicional.",
  "a4.b18": "3. Plano adequado ao limite de contatos",
  "a4.b19": "Estes exemplos indicam o plano publicado cujo limite cobre a quantidade de contatos informada. Não são estimativas do custo total: verifique separadamente o acesso a recursos, a cobrança regional e as regras de excedentes.",
  "a4.b20": "25 contatos",
  "a4.b21": "O retrato público lista o Free por US$ 0 para 25 contatos. Se precisar de algo além do limite de contatos, confira os limites atuais de canais e recursos.",
  "a4.b22": "1.000 contatos",
  "a4.b23": "Nos planos publicados aqui, 1.000 contatos ficam dentro do limite de 2.500 do Pro, listado pelo equivalente mensal de US$ 29 na cobrança anual. Confirme os recursos incluídos e o preço regional na página oficial.",
  "a4.b24": "5.000 contatos",
  "a4.b25": "O Business é o plano publicado que cobre 5.000 contatos: permite 7.500, com equivalente mensal de US$ 69 na cobrança anual. Este é apenas o retrato da assinatura.",
  "a4.b26": "15.000 contatos",
  "a4.b27": "O Advanced é o plano publicado que cobre 15.000 contatos: permite 25.000, com equivalente mensal de US$ 139 na cobrança anual. Para volumes maiores, peça as condições atuais em vez de extrapolar.",
  "a4.b28": "Os limites ajudam a identificar um plano inicial, mas não determinam sozinhos o valor final. Ciclo de cobrança, país, impostos, recursos e volume de mensagens também importam.",
  "a4.b29": "4. Custos e condições a conferir",
  "a4.b30": "<strong>Tarifas de mensagens do WhatsApp.</strong> Elas são separadas da assinatura da plataforma e dependem da categoria da mensagem, do mercado do destinatário e da cobrança do fornecedor. O guia do ManyChat e a tabela da Meta não são intercambiáveis; compare cada fonte com sua fatura.",
  "a4.b31": "<strong>Usuários e acesso a canais.</strong> A disponibilidade de usuários e canais pode variar por nível. Confira a tabela atual para ver quantos usuários e canais sua equipe precisa.",
  "a4.b32": "<strong>Disponibilidade de recursos.</strong> Ferramentas de IA e canais de mensagens podem estar restritos a determinados níveis. Antes de fazer upgrade, confirme o que está incluído atualmente no seu país.",
  "a4.b33": "<strong>Uso e excedentes.</strong> Não presuma que uma tarifa antiga por contato continua valendo. Pergunte ao ManyChat como são tratados os contatos acima do limite e quando uma mudança de plano entra em vigor.",
  "a4.b34": "<strong>Moeda e impostos.</strong> Os exemplos em USD podem não corresponder ao valor exibido para o país de cobrança; impostos, câmbio e ofertas locais podem alterar a cobrança final.",
  "a4.b35": "5. Perguntas antes de trocar",
  "a4.b36": "<strong>Confirme o que significa “contato”.</strong> Leia a definição de cobrança atual e confira quais contatos contam para o limite escolhido.",
  "a4.b37": "<strong>Compare o próximo nível.</strong> Pergunte se o upgrade ou as condições atuais de excedente do fornecedor são mais econômicos para o público esperado.",
  "a4.b38": "<strong>Compare períodos de cobrança equivalentes.</strong> Separe equivalentes mensais na cobrança anual de preços mês a mês e anote qualquer compromisso de pagamento antecipado.",
  "a4.b39": "<strong>Confira a disponibilidade real da alternativa.</strong> A Chatora não publicou preços de assinatura nem habilitou mensagens ao vivo por canais; portanto, uma comparação válida de custos ou recursos ainda não é possível.",
  "a4.b40": "O que a Chatora publica hoje?",
  "a4.b41": "A Chatora é uma prévia do produto, não uma oferta de assinatura publicada. Consulte a disponibilidade atual e compare as condições dos fornecedores com seus próprios dados de uso.",
  "a4.cta": "Consultar disponibilidade atual →",
  "a4.b42": "6. Perguntas frequentes",
  "a4.b43": "O ManyChat é gratuito?",
  "a4.b44": "A página pública consultada em 28 de outubro de 2026 lista um plano Free por US$ 0 para 25 contatos. Consulte a página atual para verificar condições regionais e recursos incluídos.",
  "a4.b45": "Quais planos incluem IA ou WhatsApp?",
  "a4.b46": "As páginas atuais de preços e ajuda do ManyChat descrevem o acesso a recursos por plano. Antes de escolher um nível, confirme na sua própria conta as inclusões exatas de IA e WhatsApp, os limites de uso e a disponibilidade regional.",
  "a4.b47": "O que conta como contato ativo?",
  "a4.b48": "Use a definição de cobrança atual do ManyChat; não presuma que diferentes fornecedores ou planos contam contatos da mesma forma.",
  "a4.b49": "A cobrança anual muda o limite de contatos?",
  "a4.b50": "O retrato público lista o mesmo limite de contatos para cada plano, independentemente do equivalente de cobrança exibido. Confirme as condições no checkout antes de comprar.",
  "a4.b51": "O que acontece se eu ultrapassar meu limite?",
  "a4.b52": "O tratamento exato de excedentes ou upgrades pode depender do plano e das condições de cobrança atuais. Confira os termos escritos mais recentes do ManyChat; este retrato não estima cobranças por excedente.",
  "a4.b54": "Fontes: página pública de preços do ManyChat e páginas da central de ajuda, consultadas em 28 de outubro de 2026. Os equivalentes mensais são exemplos na cobrança anual; preços e condições dos planos variam por região e podem mudar. A Chatora não publicou preço de assinatura.",
});


/* Article a5 translations: Instagram automation tools. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a5.h1": "Herramientas de automatización de Instagram en 2026: qué comprobar antes de elegir",
  "a5.lede": "Usa esta lista de comprobación para evaluar el acceso a la API oficial, los flujos compatibles de comentarios y mensajes directos, los límites de solicitudes, la transferencia a una persona y las condiciones vigentes del plan. Chatora es una vista previa del producto sin mensajería activa de Instagram; no se afirma haber realizado pruebas de carga ni mediciones de tiempo de respuesta.",
  "a5.date": "Actualizado el 28 de octubre de 2026 · 8 min de lectura",
  "a5.b33": "<b>Si solo lees una línea:</b> verifica el acceso a la API oficial, los activadores compatibles de comentario a mensaje directo, la gestión de los límites de solicitudes y la transferencia a una persona. Pide pruebas con condiciones de ensayo especificadas; Chatora no tiene mensajería activa de Instagram ni métricas de carga en ráfagas.",
  "a5.b1": "1. Qué puede incluir la automatización de Instagram en 2026",
  "a5.b2": "Tres tareas distintas suelen agruparse bajo esta etiqueta, y pocas herramientas destacan en las tres:",
  "a5.b3": "<strong>Automatización de comentarios</strong>: responder públicamente a comentarios en publicaciones y Reels y, cuando alguien pregunta «¿precio?», «¿enlace?» o «¿a cuánto?», continuar la conversación por mensaje directo.",
  "a5.b4": "<strong>Automatización de mensajes directos</strong>: flujos por palabras clave, respuestas rápidas, fichas de producto, enlaces de pago, cualificación y seguimientos en la bandeja de entrada.",
  "a5.b5": "<strong>Gestión de Stories y menciones</strong>: agradecimientos, códigos de recomendación y solicitudes de permiso para usar contenido generado por usuarios.",
  "a5.b6": "Comprueba qué funciones de Instagram admite cada proveedor mediante acceso autorizado por Meta y qué permisos necesita. Evita las herramientas que te pidan la contraseña de Instagram o dependan de extracción de datos no documentada; verifica las políticas actuales de la plataforma antes de conectar una cuenta.",
  "a5.b7": "2. Qué indican las páginas públicas de planes",
  "a5.b8": "Son referencias públicas fechadas, no facturas comparables directamente. Los límites de contactos, conversaciones y canales usan unidades de facturación distintas; comprueba la oferta vigente para tu país y las funciones incluidas.",
  "a5.b9": "<strong>Chatora — vista previa del producto.</strong> No hay precio de suscripción publicado ni conexión activa con Instagram. La vista previa ofrece borradores iniciales editables y herramientas CSV; no dispone de entrega de mensajes ni de métricas de rendimiento.",
  "a5.b10": "<strong>ManyChat — niveles por contactos.</strong> La página en USD consultada el 28 de octubre muestra Essential a un equivalente de 14 USD/mes para 250 contactos y Pro a 29 USD para 2.500 con facturación anual. Los precios regionales y la disponibilidad de canales e IA varían; confirma la página del plan actual.",
  "a5.b11": "<strong>Chatfuel — suscripción más cartera.</strong> Business figura a 20 USD mes a mes o a un equivalente de 18 USD/mes con facturación anual, e incluye 20 USD en créditos mensuales. Comprueba qué cubre la cartera y el uso real de la cuenta; no supongas un recargo universal por mensaje ni un coste total determinado.",
  "a5.b12": "<strong>Herramientas centradas en comentarios.</strong> Compara los activadores admitidos, el acceso a la API oficial, la gestión de bajas y las opciones de exportación. Una función para comentarios no incluye automáticamente una bandeja de entrada completa ni un flujo de comercio; verifica el alcance y el precio actuales de cada proveedor.",
  "a5.b13": "<strong>Tidio — flujos de soporte.</strong> Su página de precios muestra Starter a 24,17 USD/mes equivalentes con facturación anual para 100 conversaciones facturables; los límites de IA y Flows se contabilizan por separado. Compara la unidad de facturación con el volumen previsto.",
  "a5.b14": "3. Cómo evaluar las pruebas de rendimiento",
  "a5.b15": "Una demostración cuidada no demuestra fiabilidad durante picos de tráfico. Pregunta qué límites y condiciones de prueba respaldan cada afirmación de rendimiento y, después, realiza una prueba pequeña y controlada dentro de las reglas del proveedor.",
  "a5.b16": "<strong>Eventos duplicados.</strong> Pregunta cómo detectan webhooks o comentarios repetidos y si el proveedor documenta la idempotencia y el comportamiento de los reintentos.",
  "a5.b17": "<strong>Demoras en la cola.</strong> Pregunta cómo se gestionan los picos, los reintentos y las acumulaciones, y cómo se notifican los envíos retrasados o fallidos.",
  "a5.b18": "<strong>Límites de la API.</strong> Confirma que la integración usa acceso autorizado por Meta y entiende los límites de solicitudes, permisos y requisitos de políticas aplicables.",
  "a5.b19": "La vista previa actual de Chatora no tiene un canal de Instagram conectado ni automatización en producción. Su simulador local de borradores no prueba la entrega de Meta, el rendimiento, las colas ni el tiempo de respuesta.",
  "a5.b20": "4. Lista de comprobación para compradores",
  "a5.b21": "Confirma el acceso oficial a la API, los permisos necesarios y el plan del proveedor para afrontar cambios de políticas.",
  "a5.b22": "Pregunta cómo se gestionan los activadores de comentarios, los eventos duplicados, los reintentos y las bajas; prueba solo en un espacio de trabajo autorizado.",
  "a5.b23": "Solicita una latencia integral medida bajo una carga especificada y elige un objetivo de servicio que se ajuste a tus necesidades.",
  "a5.b24": "Para las funciones de IA, comprueba si las respuestas usan tu catálogo aprobado y gestionan los precios desconocidos de forma segura; verifica que la función esté activa en el plan.",
  "a5.b25": "Comprueba las reglas de transferencia a una persona y si el agente que recibe la conversación obtiene el contexto.",
  "a5.b26": "Si vendes en MENA, prueba casos de uso en árabe y dialectos con ejemplos reales y autorizados.",
  "a5.b27": "Compara el coste total para el volumen previsto, incluidos los límites de contactos o conversaciones, usuarios, complementos, uso e impuestos.",
  "a5.b28": "Antes de conectar una cuenta de producción, comprueba el acceso a los datos, el alcance de las exportaciones y los plazos de conservación.",
  "a5.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de Chatfuel</a> · <a href=\"https://www.tidio.com/pricing/\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de Tidio</a> · <a href=\"https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/messaging-api/\" rel=\"noopener noreferrer\" target=\"_blank\">API de mensajería de Instagram de Meta</a>",
  "a5.b29": "Comprueba la disponibilidad actual del producto",
  "a5.b30": "La vista previa actual de Chatora incluye borradores iniciales editables, herramientas CSV para contactos y pruebas locales de flujos. No tiene un canal de Instagram activo, mensajería saliente, respuestas de IA ni un plan de suscripción gratuito o de pago habilitado.",
  "a5.cta": "Consultar disponibilidad →",
  "a5.b31": "5. Veredicto",
  "a5.b32": "Si necesitas automatización de Instagram en producción ahora, compara proveedores con integraciones oficiales actualmente admitidas, límites de plan claros, exportaciones utilizables y soporte documentado. ManyChat puede convenir a equipos que valoran su editor consolidado y su comunidad; Chatfuel y otras herramientas tienen distintos modelos de facturación. Chatora sigue siendo una vista previa, así que no hay una comparación válida de rendimiento en directo ni de ahorro.",
  "a5.b34": "Páginas de precios de los proveedores y documentación de la API de Instagram de Meta consultadas el 28 de octubre de 2026. Aquí no se usan pruebas de carga independientes, datos de producción de Chatora ni clasificaciones de rendimiento. Chatora es un proveedor; verifica directamente las condiciones actuales.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a5.h1": "Outils d’automatisation Instagram en 2026 : points à vérifier avant de choisir",
  "a5.lede": "Utilisez cette liste d’achat pour évaluer l’accès officiel à l’API, les parcours pris en charge pour les commentaires et les messages privés, les limites de requêtes, le transfert à une personne et les conditions actuelles des offres. Chatora est un aperçu de produit sans messagerie Instagram en direct ; aucun test de charge ni repère de temps de réponse n’est revendiqué.",
  "a5.date": "Mis à jour le 28 octobre 2026 · 8 min de lecture",
  "a5.b33": "<b>À retenir en une phrase :</b> vérifiez l’accès officiel à l’API, les déclencheurs commentaire-vers-message privé pris en charge, la gestion des limites de requêtes et le transfert à une personne. Demandez des preuves pour un test dont les conditions sont précisées ; Chatora n’a ni messagerie Instagram en direct ni référence de charge en rafale.",
  "a5.b1": "1. Ce que peut inclure l’automatisation Instagram en 2026",
  "a5.b2": "Trois tâches distinctes sont souvent regroupées sous cette appellation, et les outils sont rarement performants sur les trois :",
  "a5.b3": "<strong>Automatisation des commentaires</strong> — répondre publiquement aux commentaires sur les publications et les Reels, puis poursuivre en message privé lorsqu’une personne demande « le prix ? », « le lien ? » ou « à combien ? ».",
  "a5.b4": "<strong>Automatisation des messages privés</strong> — parcours par mots-clés, réponses rapides, fiches produit, liens de paiement, qualification et relances dans la boîte de réception.",
  "a5.b5": "<strong>Gestion des Stories et des mentions</strong> — remerciements, codes de parrainage et demandes de consentement pour les contenus générés par les utilisateurs.",
  "a5.b6": "Vérifiez les fonctionnalités Instagram prises en charge par chaque fournisseur via un accès autorisé par Meta et les autorisations requises. Évitez les outils qui demandent votre mot de passe Instagram ou s’appuient sur une collecte non documentée ; vérifiez les règles actuelles de la plateforme avant de connecter un compte.",
  "a5.b7": "2. Ce qu’indiquent les pages publiques des offres",
  "a5.b8": "Il s’agit d’instantanés publics datés, pas de factures directement comparables. Les limites de contacts, de conversations et de canaux utilisent des unités de facturation différentes ; vérifiez l’offre actuelle pour votre pays et les fonctionnalités incluses.",
  "a5.b9": "<strong>Chatora — aperçu de produit.</strong> Aucun tarif d’abonnement publié ni connexion Instagram en direct. L’aperçu propose des brouillons de départ modifiables et des outils CSV ; aucun envoi de messages ni indicateur de performance n’est disponible.",
  "a5.b10": "<strong>ManyChat — paliers par contacts.</strong> La page USD consultée le 28 octobre affiche Essential à un équivalent de 14 $/mois pour 250 contacts et Pro à 29 $ pour 2 500 avec facturation annuelle. Les tarifs régionaux et la disponibilité des canaux et de l’IA varient ; consultez la page actuelle de l’offre.",
  "a5.b11": "<strong>Chatfuel — abonnement et portefeuille.</strong> Business est affiché à 20 $ par mois sans engagement ou à un équivalent de 18 $/mois avec facturation annuelle, avec 20 $ de crédits mensuels. Vérifiez ce que couvre le portefeuille et l’usage réel du compte ; ne présumez ni d’une majoration universelle par message ni d’une facture totale donnée.",
  "a5.b12": "<strong>Outils axés sur les commentaires.</strong> Comparez les déclencheurs pris en charge, l’accès officiel à l’API, la gestion des désabonnements et les options d’export. Une fonctionnalité de commentaire ne comprend pas automatiquement une boîte de réception complète ni un parcours commercial ; vérifiez le périmètre et le tarif actuels de chaque fournisseur.",
  "a5.b13": "<strong>Tidio — parcours d’assistance.</strong> Sa page tarifaire affiche Starter à un équivalent de 24,17 $/mois avec facturation annuelle pour 100 conversations facturables ; les limites de l’IA et de Flows sont distinctes. Comparez l’unité de facturation à votre volume prévisionnel.",
  "a5.b14": "3. Évaluer les preuves de performance",
  "a5.b15": "Une démonstration soignée ne prouve pas la fiabilité en période de forte activité. Demandez les limites et les conditions de test qui étayent toute affirmation de performance, puis réalisez un petit test contrôlé dans le respect des règles du fournisseur.",
  "a5.b16": "<strong>Événements en double.</strong> Demandez comment sont détectés les webhooks ou commentaires répétés et si le fournisseur documente l’idempotence et les tentatives de nouvelle exécution.",
  "a5.b17": "<strong>Retards dans la file d’attente.</strong> Demandez comment le système gère les pics, les nouvelles tentatives et les retards accumulés, et comment il signale les envois tardifs ou échoués.",
  "a5.b18": "<strong>Limites de l’API.</strong> Confirmez que l’intégration utilise un accès autorisé par Meta et renseignez-vous sur les limites de requêtes, les autorisations et les exigences de conformité applicables.",
  "a5.b19": "L’aperçu actuel de Chatora n’a ni canal Instagram connecté ni automatisation en production. Son simulateur local de brouillons ne teste pas la livraison Meta, le débit, la mise en file d’attente ni le temps de réponse.",
  "a5.b20": "4. Liste de vérification pour l’acheteur",
  "a5.b21": "Confirmez l’accès officiel à l’API, les autorisations requises et le plan du fournisseur en cas d’évolution des règles.",
  "a5.b22": "Demandez comment sont gérés les déclencheurs de commentaires, les événements en double, les nouvelles tentatives et les désabonnements ; testez uniquement dans un espace autorisé.",
  "a5.b23": "Demandez une latence de bout en bout mesurée sous une charge définie et choisissez un objectif de service adapté à vos besoins.",
  "a5.b24": "Pour les fonctions d’IA, vérifiez si les réponses s’appuient sur votre catalogue approuvé et gèrent correctement les prix inconnus ; confirmez que la fonction est active dans l’offre.",
  "a5.b25": "Vérifiez les règles de transfert à une personne et si l’agent qui reçoit la conversation dispose du contexte.",
  "a5.b26": "Si vous vendez dans la région MENA, testez des cas d’usage en arabe et en dialecte avec des exemples réels et autorisés.",
  "a5.b27": "Comparez le coût total pour votre volume prévisionnel, y compris les limites de contacts ou de conversations, les sièges, les options, l’utilisation et les taxes.",
  "a5.b28": "Vérifiez l’accès aux données, le périmètre des exports et la durée de conservation avant de connecter un compte de production.",
  "a5.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs Chatfuel</a> · <a href=\"https://www.tidio.com/pricing/\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs Tidio</a> · <a href=\"https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/messaging-api/\" rel=\"noopener noreferrer\" target=\"_blank\">API de messagerie Instagram de Meta</a>",
  "a5.b29": "Vérifiez la disponibilité actuelle du produit",
  "a5.b30": "L’aperçu actuel de Chatora comprend des brouillons de départ modifiables, des outils CSV pour les contacts et des tests locaux de parcours. Aucun canal Instagram en direct, envoi de messages, réponse IA ni abonnement gratuit ou payant n’est activé.",
  "a5.cta": "Consulter la disponibilité →",
  "a5.b31": "5. Conclusion",
  "a5.b32": "Si vous avez besoin dès maintenant d’une automatisation Instagram en production, comparez les fournisseurs selon les intégrations officielles actuellement prises en charge, des limites d’offre claires, des exports utilisables et une assistance documentée. ManyChat peut convenir aux équipes qui apprécient son éditeur éprouvé et sa communauté ; Chatfuel et d’autres outils ont des modèles de facturation différents. Chatora reste un aperçu : aucune comparaison de performance en direct ou d’économies n’est possible.",
  "a5.b34": "Pages tarifaires des fournisseurs et documentation de l’API Instagram de Meta consultées le 28 octobre 2026. Aucun test de charge indépendant, donnée de production Chatora ou classement de performance n’est utilisé ici. Chatora est un fournisseur ; vérifiez directement les conditions actuelles.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a5.h1": "Instagram-Automatisierungstools 2026: Was du vor der Auswahl prüfen solltest",
  "a5.lede": "Nutze diese Checkliste, um offiziellen API-Zugang, unterstützte Kommentar- und DM-Abläufe, Ratenlimits, Übergabe an Menschen und aktuelle Tarifbedingungen zu bewerten. Chatora ist eine Produktvorschau ohne Live-Instagram-Nachrichten; es werden weder Lasttests noch Antwortzeit-Benchmarks behauptet.",
  "a5.date": "Aktualisiert am 28. Oktober 2026 · 8 Min. Lesezeit",
  "a5.b33": "<b>Wenn du nur eine Zeile liest:</b> Prüfe den offiziellen API-Zugang, unterstützte Kommentar-zu-DM-Auslöser, den Umgang mit Ratenlimits und die Übergabe an Menschen. Verlange Nachweise unter klar benannten Testbedingungen; Chatora hat weder Live-Instagram-Nachrichten noch einen Benchmark für Lastspitzen.",
  "a5.b1": "1. Was Instagram-Automatisierung 2026 umfassen kann",
  "a5.b2": "Drei unterschiedliche Aufgaben werden unter diesem Begriff oft zusammengefasst, und nur wenige Tools sind in allen drei Bereichen stark:",
  "a5.b3": "<strong>Kommentarautomatisierung</strong> — öffentlich auf Kommentare zu Beiträgen und Reels antworten und das Gespräch in DMs verlagern, wenn jemand nach „Preis?“, „Link?“ oder „wie viel?“ fragt.",
  "a5.b4": "<strong>DM-Automatisierung</strong> — Keyword-Abläufe, Schnellantworten, Produktkarten, Checkout-Links, Qualifizierung und Nachfragen im Posteingang.",
  "a5.b5": "<strong>Story- und Erwähnungsverwaltung</strong> — Dankesnachrichten, Empfehlungscodes und Einwilligungsanfragen für nutzergenerierte Inhalte.",
  "a5.b6": "Prüfe, welche Instagram-Funktionen jeder Anbieter über von Meta autorisierten Zugang unterstützt und welche Berechtigungen nötig sind. Meide Tools, die dein Instagram-Passwort verlangen oder auf undokumentiertes Scraping setzen; prüfe vor der Kontoverbindung die aktuellen Plattformregeln.",
  "a5.b7": "2. Was die öffentlichen Tarifseiten aussagen",
  "a5.b8": "Dies sind datierte öffentliche Tarifübersichten, keine direkt vergleichbaren Rechnungen. Kontakt-, Gesprächs- und Kanallimits verwenden unterschiedliche Abrechnungseinheiten; prüfe das aktuelle Angebot für dein Land und die enthaltenen Funktionen.",
  "a5.b9": "<strong>Chatora — Produktvorschau.</strong> Kein veröffentlichter Abonnementpreis und keine Live-Instagram-Verbindung. Die Vorschau bietet bearbeitbare Startentwürfe und CSV-Werkzeuge; Nachrichtenversand oder Leistungsbenchmarks gibt es nicht.",
  "a5.b10": "<strong>ManyChat — Kontaktstufen.</strong> Die am 28. Oktober geprüfte USD-Seite nennt Essential mit einem Monatsäquivalent von 14 USD für 250 Kontakte und Pro mit 29 USD für 2.500 bei Jahresabrechnung. Regionale Preise sowie Kanal- und KI-Verfügbarkeit variieren; prüfe die aktuelle Tarifseite.",
  "a5.b11": "<strong>Chatfuel — Abonnement plus Wallet.</strong> Business ist mit 20 USD bei monatlicher Zahlung oder einem Monatsäquivalent von 18 USD bei Jahresabrechnung aufgeführt und enthält 20 USD monatliches Guthaben. Prüfe, wofür das Wallet gilt und wie das Konto tatsächlich genutzt wird; gehe weder von einem allgemeinen Nachrichtenaufschlag noch von einer bestimmten Gesamtrechnung aus.",
  "a5.b12": "<strong>Kommentarorientierte Tools.</strong> Vergleiche unterstützte Auslöser, offiziellen API-Zugang, Abmeldemöglichkeiten und Exportoptionen. Eine Kommentarfunktion umfasst nicht automatisch einen vollständigen Posteingang oder Commerce-Ablauf; prüfe Umfang und aktuellen Preis jedes Anbieters.",
  "a5.b13": "<strong>Tidio — Support-Abläufe.</strong> Die Preisseite nennt Starter mit einem Monatsäquivalent von 24,17 USD bei Jahresabrechnung für 100 abrechenbare Gespräche; KI und Flows haben separate Limits. Vergleiche die Abrechnungseinheit mit deinem erwarteten Volumen.",
  "a5.b14": "3. Leistungsnachweise bewerten",
  "a5.b15": "Eine überzeugende Demo belegt keine Zuverlässigkeit bei Spitzenlast. Frage nach Limits und Testbedingungen für Leistungsversprechen und führe anschließend einen kleinen kontrollierten Test im Rahmen der Anbietervorgaben durch.",
  "a5.b16": "<strong>Doppelte Ereignisse.</strong> Frage, wie wiederholte Webhooks oder Kommentare erkannt werden und ob der Anbieter Idempotenz und Wiederholungsverhalten dokumentiert.",
  "a5.b17": "<strong>Verzögerungen in der Warteschlange.</strong> Frage, wie das System Lastspitzen, Wiederholungen und Rückstände verarbeitet und verzögerte oder fehlgeschlagene Sendungen meldet.",
  "a5.b18": "<strong>API-Limits.</strong> Bestätige den von Meta autorisierten Integrationszugang und informiere dich über relevante Ratenlimits, Berechtigungen und Richtlinienanforderungen.",
  "a5.b19": "Chatoras aktuelle Vorschau hat keinen verbundenen Instagram-Kanal und keine Produktivautomatisierung. Der lokale Entwurfssimulator testet weder Meta-Zustellung noch Durchsatz, Warteschlangen oder Antwortzeit.",
  "a5.b20": "4. Checkliste für Käufer",
  "a5.b21": "Bestätige offiziellen API-Zugang, erforderliche Berechtigungen und den Plan des Anbieters für mögliche Richtlinienänderungen.",
  "a5.b22": "Frage nach dem Umgang mit Kommentarauslösern, doppelten Ereignissen, Wiederholungen und Abmeldungen; teste nur in einem dafür freigegebenen Workspace.",
  "a5.b23": "Fordere eine gemessene Ende-zu-Ende-Latenz unter einer angegebenen Last an und wähle ein Serviceziel, das zu deinem Bedarf passt.",
  "a5.b24": "Prüfe bei KI-Funktionen, ob Antworten deinen freigegebenen Katalog verwenden und unbekannte Preise sicher behandeln; bestätige, dass die Funktion im Tarif live ist.",
  "a5.b25": "Prüfe die Regeln für die Übergabe an Menschen und ob die übernehmende Person den bisherigen Kontext erhält.",
  "a5.b26": "Wenn du in der MENA-Region verkaufst, teste Anwendungsfälle auf Arabisch und in Dialekten mit echten, freigegebenen Beispielen.",
  "a5.b27": "Vergleiche die Gesamtkosten für dein erwartetes Volumen, einschließlich Kontakt- oder Gesprächslimits, Nutzerplätzen, Zusatzoptionen, Nutzung und Steuern.",
  "a5.b28": "Prüfe Datenzugriff, Exportumfang und Aufbewahrungsfristen, bevor du ein Produktionskonto verbindest.",
  "a5.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">ManyChat-Preise</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Chatfuel-Preise</a> · <a href=\"https://www.tidio.com/pricing/\" rel=\"noopener noreferrer\" target=\"_blank\">Tidio-Preise</a> · <a href=\"https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/messaging-api/\" rel=\"noopener noreferrer\" target=\"_blank\">Meta Instagram Messaging API</a>",
  "a5.b29": "Aktuelle Produktverfügbarkeit prüfen",
  "a5.b30": "Chatoras aktuelle Vorschau umfasst editierbare Startentwürfe, CSV-Werkzeuge für Kontakte und lokale Flow-Tests. Kein Live-Instagram-Kanal, ausgehender Nachrichtenversand, keine KI-Antworten und kein kostenloser oder kostenpflichtiger Tarif sind aktiviert.",
  "a5.cta": "Verfügbarkeit prüfen →",
  "a5.b31": "5. Fazit",
  "a5.b32": "Wenn du jetzt Instagram-Automatisierung im Produktivbetrieb brauchst, vergleiche Anbieter mit aktuell unterstützten offiziellen Integrationen, klaren Tariflimits, nutzbaren Exporten und dokumentiertem Support. ManyChat kann zu Teams passen, die den etablierten Builder und die Community schätzen; Chatfuel und andere Tools haben andere Abrechnungsmodelle. Chatora ist weiterhin eine Vorschau, daher gibt es keinen gültigen Live-Leistungs- oder Sparvergleich.",
  "a5.b34": "Preisseiten der Anbieter und Metas Instagram-API-Dokumentation, geprüft am 28. Oktober 2026. Es werden weder unabhängige Lasttests noch Chatora-Produktivdaten oder Leistungsrankings verwendet. Chatora ist ein Anbieter; prüfe aktuelle Konditionen direkt.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a5.h1": "Ferramentas de automação do Instagram em 2026: o que verificar antes de escolher",
  "a5.lede": "Use esta lista para avaliar o acesso oficial à API, os fluxos compatíveis de comentários e DMs, os limites de requisições, a transferência para atendimento humano e as condições atuais dos planos. A Chatora é uma prévia do produto sem mensagens ativas no Instagram; não há alegação de teste de carga nem de referência de tempo de resposta.",
  "a5.date": "Atualizado em 28 de outubro de 2026 · 8 min de leitura",
  "a5.b33": "<b>Se você ler apenas uma linha:</b> verifique o acesso oficial à API, os gatilhos compatíveis de comentário para DM, o tratamento dos limites de requisição e a transferência para atendimento humano. Peça evidências sob condições de teste declaradas; a Chatora não tem mensagens ativas no Instagram nem referência de carga em rajada.",
  "a5.b1": "1. O que a automação do Instagram pode incluir em 2026",
  "a5.b2": "Três tarefas diferentes costumam ser reunidas sob esse rótulo, e poucas ferramentas são fortes nas três:",
  "a5.b3": "<strong>Automação de comentários</strong> — responder publicamente a comentários em publicações e Reels e levar a conversa para as DMs quando alguém pergunta \"preço?\", \"link?\" ou \"quanto custa?\".",
  "a5.b4": "<strong>Automação de DMs</strong> — fluxos por palavra-chave, respostas rápidas, cartões de produto, links de checkout, qualificação e acompanhamentos na caixa de entrada.",
  "a5.b5": "<strong>Gestão de Stories e menções</strong> — agradecimentos, códigos de indicação e pedidos de consentimento para conteúdo gerado pelo usuário.",
  "a5.b6": "Confira quais recursos do Instagram cada fornecedor oferece por meio de acesso autorizado pela Meta e quais permissões exige. Evite ferramentas que peçam sua senha do Instagram ou dependam de coleta de dados não documentada; verifique as políticas atuais da plataforma antes de conectar uma conta.",
  "a5.b7": "2. O que as páginas públicas dos planos informam",
  "a5.b8": "São retratos públicos datados, não faturas diretamente comparáveis. Limites de contatos, conversas e canais usam unidades de cobrança diferentes; confira a oferta atual para seu país e os recursos incluídos.",
  "a5.b9": "<strong>Chatora — prévia do produto.</strong> Não há preço de assinatura publicado nem conexão ativa com o Instagram. A prévia oferece rascunhos iniciais editáveis e ferramentas CSV; não há entrega de mensagens nem indicadores de desempenho.",
  "a5.b10": "<strong>ManyChat — níveis por contatos.</strong> A página em USD consultada em 28 de outubro lista o Essential pelo equivalente mensal de US$ 14 para 250 contatos e o Pro por US$ 29 para 2.500 na cobrança anual. Preços regionais e disponibilidade de canais e IA variam; confirme a página atual do plano.",
  "a5.b11": "<strong>Chatfuel — assinatura mais carteira.</strong> O Business aparece por US$ 20 no pagamento mensal ou pelo equivalente a US$ 18/mês na cobrança anual, com US$ 20 em créditos mensais. Confira o que a carteira cobre e o uso real da conta; não presuma uma margem universal por mensagem nem uma fatura total específica.",
  "a5.b12": "<strong>Ferramentas focadas em comentários.</strong> Compare gatilhos compatíveis, acesso oficial à API, tratamento de descadastros e opções de exportação. Um recurso de comentários não inclui automaticamente uma caixa de entrada completa ou um fluxo de comércio; verifique o escopo e o preço atual de cada fornecedor.",
  "a5.b13": "<strong>Tidio — fluxos de suporte.</strong> A página de preços lista o Starter pelo equivalente a US$ 24,17/mês na cobrança anual para 100 conversas faturáveis; IA e Flows têm limites separados. Compare a unidade de cobrança ao volume esperado.",
  "a5.b14": "3. Como avaliar evidências de desempenho",
  "a5.b15": "Uma demonstração bem produzida não comprova confiabilidade em períodos de pico. Pergunte quais limites e condições de teste sustentam cada alegação de desempenho e, em seguida, faça um teste pequeno e controlado dentro das regras do fornecedor.",
  "a5.b16": "<strong>Eventos duplicados.</strong> Pergunte como webhooks ou comentários repetidos são detectados e se o fornecedor documenta idempotência e comportamento de novas tentativas.",
  "a5.b17": "<strong>Atrasos na fila.</strong> Pergunte como o sistema lida com picos, novas tentativas e acúmulo de tarefas, e como informa envios atrasados ou com falha.",
  "a5.b18": "<strong>Limites da API.</strong> Confirme se a integração usa acesso autorizado pela Meta e entenda os limites de requisições, permissões e requisitos de política aplicáveis.",
  "a5.b19": "A prévia atual da Chatora não tem canal do Instagram conectado nem automação em produção. O simulador local de rascunhos não testa a entrega da Meta, a capacidade, o enfileiramento nem o tempo de resposta.",
  "a5.b20": "4. Lista de verificação para compradores",
  "a5.b21": "Confirme o acesso oficial à API, as permissões necessárias e o plano do fornecedor para mudanças de política.",
  "a5.b22": "Pergunte como são tratados gatilhos de comentários, eventos duplicados, novas tentativas e descadastros; teste somente em um espaço autorizado.",
  "a5.b23": "Peça uma latência ponta a ponta medida sob uma carga especificada e escolha uma meta de serviço adequada às suas necessidades.",
  "a5.b24": "Para recursos de IA, teste se as respostas usam seu catálogo aprovado e tratam preços desconhecidos com segurança; confirme se o recurso está ativo no plano.",
  "a5.b25": "Confira as regras de transferência para atendimento humano e se o agente que recebe a conversa tem acesso ao contexto.",
  "a5.b26": "Se você vende no MENA, teste casos de uso em árabe e dialetos com exemplos reais e autorizados.",
  "a5.b27": "Compare o custo total no volume esperado, incluindo limites de contatos ou conversas, usuários, adicionais, uso e impostos.",
  "a5.b28": "Confira o acesso aos dados, o escopo da exportação e o prazo de retenção antes de conectar uma conta de produção.",
  "a5.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do Chatfuel</a> · <a href=\"https://www.tidio.com/pricing/\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do Tidio</a> · <a href=\"https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/messaging-api/\" rel=\"noopener noreferrer\" target=\"_blank\">API de mensagens do Instagram da Meta</a>",
  "a5.b29": "Confira a disponibilidade atual do produto",
  "a5.b30": "A prévia atual da Chatora inclui rascunhos iniciais editáveis, ferramentas CSV para contatos e testes locais de fluxos. Não há canal ativo do Instagram, envio de mensagens, respostas de IA nem plano de assinatura gratuito ou pago habilitado.",
  "a5.cta": "Consultar disponibilidade →",
  "a5.b31": "5. Conclusão",
  "a5.b32": "Se você precisa de automação do Instagram em produção agora, compare fornecedores com integrações oficiais atualmente compatíveis, limites claros de plano, exportações úteis e suporte documentado. O ManyChat pode atender equipes que valorizam seu editor consolidado e sua comunidade; Chatfuel e outras ferramentas têm modelos de cobrança diferentes. A Chatora ainda é uma prévia, portanto não há comparação válida de desempenho ao vivo nem de economia.",
  "a5.b34": "Páginas de preços dos fornecedores e documentação da API do Instagram da Meta consultadas em 28 de outubro de 2026. Não são usados testes de carga independentes, dados de produção da Chatora nem ranking de desempenho. A Chatora é um fornecedor; confira diretamente as condições atuais.",
});


/* Article a6 translations: WhatsApp API pricing in Egypt. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a6.h1": "Precios de la API de WhatsApp en Egipto (2026): tarifas de Meta y ejemplos de costes",
  "a6.lede": "Meta fija el precio de los mensajes de WhatsApp según la categoría y el mercado del destinatario. Esta guía utiliza la tarifa de Egipto vigente desde el 1 de octubre de 2026 para mostrar cálculos de ejemplo, incluida la franquicia mensual de mensajes de servicio. No son facturas reales de clientes; los cargos del proveedor, los impuestos y la configuración de la cuenta pueden añadir costes.",
  "a6.author": "Equipo de investigación de Chatora",
  "a6.date": "Actualizado el 28 de octubre de 2026 · 10 min de lectura",
  "a6.callout": "<b>Referencia de la tarifa de Meta:</b> para mensajes entregados a un número egipcio (+20), la tarifa en USD de octubre de 2026 indica <strong>0,0644 USD</strong> por mensaje de marketing y <strong>0,0036 USD</strong> por mensaje de utilidad, autenticación o servicio. También incluye 1.000 mensajes de servicio gratuitos al mes por número de empresa. Son tarifas de Meta, no una factura completa del proveedor.",
  "a6.b1": "Contenido",
  "a6.b2": "<a href=\"#change\">Qué cambió el 1 de octubre de 2026</a>",
  "a6.b3": "<a href=\"#categories\">Las cuatro categorías explicadas con claridad</a>",
  "a6.b4": "<a href=\"#bills\">Tres cálculos ilustrativos</a>",
  "a6.b5": "<a href=\"#tiers\">Otras reglas de la tarifa y comprobaciones de elegibilidad</a>",
  "a6.b6": "<a href=\"#markups\">Cómo comparar la facturación de los proveedores</a>",
  "a6.b7": "<a href=\"#cut\">Siete formas de reducir la factura</a>",
  "a6.b8": "1. Qué cambió el 1 de octubre de 2026",
  "a6.b9": "Si lees un artículo sobre precios de WhatsApp escrito antes de finales de 2024, describe un sistema que ya no existe: una tarifa fija por «conversación» de 24 horas. Meta lo ha sustituido dos veces.",
  "a6.b10": "<strong>Julio de 2025 — por mensaje, no por conversación.</strong> Cada plantilla entregada se cobra por separado. Enviar una plantilla de marketing y luego tres actualizaciones el mismo día supone ahora cuatro cargos, no uno.",
  "a6.b11": "<strong>1 de octubre de 2026 — las respuestas de servicio vuelven a tener coste.</strong> Antes, las respuestas enviadas durante la ventana de atención de 24 horas eran gratuitas y sin límite. Ahora cada número de teléfono de empresa tiene <strong>1.000 mensajes de servicio gratuitos al mes</strong>; el mensaje 1.001 se cobra según la tarifa de utilidad del mercado. La franquicia se renueva cada mes y no se acumula.",
  "a6.b12": "<strong>Comprueba las reglas y categorías de las plantillas.</strong> No supongas que una plantilla es gratuita porque la ventana de atención al cliente esté abierta; confirma su categoría aprobada y el tratamiento vigente en la tarifa.",
  "a6.b13": "Para una tienda pequeña importan tanto la categoría del mensaje como el volumen entregado. Las guías antiguas pueden describir reglas anteriores: comprueba la fecha de cualquier cálculo, compáralo con la documentación vigente de Meta.",
  "a6.b14": "2. Las cuatro categorías explicadas con claridad",
  "a6.b15": "Meta asigna cada mensaje que envías a una única categoría, que determina el precio para el país del destinatario. No se negocia ni se puede «elegir» una categoría más barata: se clasifica la plantilla que envías.",
  "a6.b16": "<strong>Marketing</strong>: promociones y ofertas. La tarifa de Egipto de octubre de 2026 indica 0,0644 USD por mensaje entregado; comprueba el volumen y las reglas actuales de la cuenta.",
  "a6.b17": "<strong>Utilidad</strong>: actualizaciones que cumplen los requisitos sobre una transacción del cliente, como el pedido o el envío. La tarifa de Egipto indica 0,0036 USD.",
  "a6.b18": "<strong>Autenticación</strong>: contraseñas de un solo uso y códigos de inicio de sesión que cumplen los requisitos. La tarifa de Egipto indica 0,0036 USD; en mercados elegibles puede aplicarse una tarifa internacional de autenticación. Comprueba la tarifa vigente del mercado del destinatario.",
  "a6.b19": "<strong>Servicio</strong>: respuestas de atención al cliente según las reglas vigentes de Meta. La tarifa incluye 1.000 mensajes de servicio gratuitos al mes por número de empresa y, después, 0,0036 USD en Egipto.",
  "a6.b20": "La tarifa vigente de Meta define qué mensajes se cobran y cómo se contabiliza la entrega. Consulta la documentación más reciente y compara los mensajes entregados con la factura del proveedor; no supongas que todos los mensajes enviados se cobran.",
  "a6.b21": "3. Tres cálculos ilustrativos",
  "a6.b22": "Estos ejemplos usan la tarifa de Egipto vigente desde el 1 de octubre de 2026 y suponen que todos los mensajes indicados se entregan y se clasifican correctamente. Excluyen cargos del proveedor, impuestos, descuentos y otros costes empresariales; son ejemplos aritméticos, no facturas de clientes.",
  "a6.b23": "<b>Ejemplo 1 — mensajes de servicio.</b> Supongamos que un número de teléfono de empresa recibe 12.000 respuestas de servicio entregadas en un mes. Tras los 1.000 mensajes gratuitos, 11.000 × 0,0036 USD = <strong>39,60 USD</strong> en tarifas de Meta. Los volúmenes reales y otros cargos pueden variar.",
  "a6.b24": "<b>Ejemplo 2 — mensajes de marketing.</b> Si se entregan 10.000 mensajes de marketing a destinatarios elegibles con números egipcios, 10.000 × 0,0644 USD = <strong>644 USD</strong> según la tarifa publicada de Meta. Es un cálculo de tarifas de Meta, no un cargo de la plataforma ni una factura completa.",
  "a6.b25": "<b>Ejemplo 3 — seguimiento de un carrito.</b> Si 800 carritos reciben dos mensajes de utilidad entregados cada uno y la categoría y el contenido aprobados cumplen los requisitos, 1.600 × 0,0036 USD = <strong>5,76 USD</strong> en tarifas de Meta. Con un pedido de 30 USD y un margen bruto del 30%, una recuperación hipotética del 4% supone 288 USD de beneficio bruto antes de otros costes: 50 veces este ejemplo de tarifas de mensajes, pero no una estimación completa del retorno.",
  "a6.b26": "Estos ejemplos no establecen una proporción típica de ingresos ni una combinación típica de categorías. Usa tus propios recuentos de mensajes entregados, categorías aprobadas, margen y factura del proveedor para estimar costes y resultados.",
  "a6.b27": "4. Otras reglas de la tarifa y comprobaciones de elegibilidad",
  "a6.b28": "Los precios de Meta pueden incluir reglas específicas por mercado, condiciones de elegibilidad y excepciones para ciertos puntos de entrada. La duración de las ventanas y los cargos han cambiado, y la documentación de los proveedores puede describirlos de otra manera. Antes de incluir una excepción o ventana gratuita en el presupuesto, consulta la página de precios vigente de Meta y las condiciones concretas de la cuenta.",
  "a6.b29": "Si usas anuncios que abren WhatsApp, confirma qué mensajes cumplen los requisitos para una ventana sin cargo vigente, cuánto dura y si incluye plantillas de seguimiento. No supongas que todos los mensajes de la conversación son gratuitos; incluye en el cálculo los cargos del proveedor y el gasto publicitario.",
  "a6.b30": "5. Cómo comparar la facturación de los proveedores",
  "a6.b31": "Las tarifas de Meta son públicas, pero una factura del proveedor puede usar otras formas de presentación y condiciones de cobro. Por ejemplo, la guía de ManyChat del 7 de octubre de 2026 indica 0,0740 USD por mensaje de marketing en Egipto; la tarifa de Meta vigente desde el 1 de octubre indica 0,0644 USD. Esa diferencia por sí sola no explica su causa ni demuestra un recargo concreto. Pide al proveedor la tarifa aplicable, las comisiones incluidas y una factura de ejemplo.",
  "a6.b32": "Preguntas que conviene hacer a cualquier proveedor antes de conectar WhatsApp:",
  "a6.b33": "¿Qué tarifas de mensajes y cargos del proveedor se aplican a mi mercado y cuenta, y dónde están documentados?",
  "a6.b34": "¿Los cargos son por mensaje, según el uso o una cuota mensual fija? ¿Pueden variar según el volumen?",
  "a6.b35": "¿Puedo ver el coste por mensaje en el panel antes de enviarlo o solo en la factura?",
  "a6.b36": "Si me voy, ¿conservaré el número de teléfono y el historial de plantillas?",
  "a6.b37": "6. Siete formas de reducir la factura",
  "a6.b38": "<strong>Deja que el cliente inicie el chat.</strong> Los mensajes entrantes son gratuitos. Un flujo de comentario a mensaje directo o de clic para chatear hace que el primer mensaje corra por cuenta del cliente.",
  "a6.b39": "<strong>Reserva los 1.000 mensajes de servicio gratuitos para atención al cliente.</strong> No los gastes en guiones de venta adicional: eso sería un coste de marketing disfrazado de soporte.",
  "a6.b40": "<strong>Segmenta por recencia, no por tamaño.</strong> Enviar 10.000 mensajes a personas que compraron el mes pasado puede ser mejor que enviar 30.000 a todas las que alguna vez estuvieron en la lista.",
  "a6.b41": "<strong>Envía recibos como utilidad, no como marketing.</strong> «Tu pedido se ha enviado» es un mensaje de utilidad a 0,0036 USD; un mensaje de «¡te echamos de menos!» es marketing a 0,0644 USD y los usuarios pueden denunciarlo.",
  "a6.b42": "<strong>Usa los canales que tu empresa ya admite.</strong> El correo electrónico u otro canal puede servir para ciertas actualizaciones, pero comprueba sus reglas de consentimiento, servicio y precios; no supongas que una integración de herramienta está activa.",
  "a6.b43": "<strong>Vigila la calidad y las entregas.</strong> Sigue las alertas vigentes de la cuenta de Meta, revisa quejas y resultados de entrega, y pausa o ajusta la actividad cuando lo exijan las políticas.",
  "a6.b44": "<strong>Pide la conciliación.</strong> La facturación de Meta muestra el número de mensajes entregados por categoría. Compárala cada mes con el recuento de la plataforma; una diferencia suele indicar que las plantillas se clasificaron de otra manera de lo previsto.",
  "a6.b45": "Chatora es actualmente una vista previa del producto sin precio de suscripción publicado, canal de WhatsApp conectado ni estimación del coste de mensajes en directo. Todavía no hay una tarifa de Chatora que comparar con Meta u otro proveedor.",
  "a6.b46": "Preguntas frecuentes, en breve",
  "a6.b47": "¿La API de WhatsApp Business es gratuita?",
  "a6.b48": "La tarifa publicada de Cloud API de Meta cobra por mensaje según las categorías y mercados indicados, pero los proveedores externos pueden cobrar suscripciones o tarifas de uso. Comprueba la tarifa vigente y las condiciones del proveedor para tu cuenta.",
  "a6.b49": "¿Las respuestas de servicio dejaron de ser gratuitas?",
  "a6.b50": "Sí. El cambio entró en vigor el 1 de octubre de 2026, después de que fueran gratuitas desde noviembre de 2024. Cada número de teléfono de empresa dispone ahora de 1.000 mensajes de servicio gratuitos al mes; el resto se cobra a la tarifa de utilidad de ese país.",
  "a6.b51": "¿Es obligatorio contratar un BSP?",
  "a6.b52": "No siempre se necesita un proveedor comercial externo para configurar Cloud API, pero la incorporación directa sigue sujeta a los requisitos actuales de cuenta, permisos y tecnología de Meta. Consulta la documentación oficial y elige la vía que mejor se adapte a tu equipo.",
  "a6.b53": "¿Estas tarifas caducan?",
  "a6.b54": "Pueden cambiar. Las cifras anteriores se contrastaron con la tarifa publicada por Meta el 28 de octubre de 2026; las tarifas y la elegibilidad pueden variar, así que vuelve a consultar la fuente oficial antes de elaborar un presupuesto.",
  "a6.b55": "Consulta el estado actual de disponibilidad",
  "a6.b56": "La vista previa de Chatora no tiene canal de WhatsApp conectado, precio de suscripción publicado ni estimación activa del coste de mensajes. Para elaborar un presupuesto vigente, usa la tarifa oficial de Meta y las condiciones de facturación de tu proveedor.",
  "a6.cta": "Consultar disponibilidad de Chatora →",
  "a6.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de WhatsApp de Meta</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guía de precios de WhatsApp de ManyChat</a>",
  "a6.b57": "Fuentes: documentación de precios de WhatsApp Business Platform de Meta, actualizada el 30 de septiembre de 2026; tarifa de Meta para Egipto vigente desde el 1 de octubre de 2026; y guía pública de precios de WhatsApp de ManyChat, consultada el 7 de octubre de 2026. Son cifras publicadas por proveedores, no facturas de clientes de Chatora; verifica las reglas vigentes antes de presupuestar.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a6.h1": "Tarifs de l’API WhatsApp en Égypte (2026) : tarifs Meta et exemples de coûts",
  "a6.lede": "Meta facture les messages WhatsApp selon leur catégorie et le marché du destinataire. Ce guide utilise la grille égyptienne de Meta en vigueur depuis le 1er octobre 2026 pour présenter des calculs illustratifs, y compris le quota mensuel gratuit de messages de service. Il ne s’agit pas de factures réelles ; les frais du fournisseur, les taxes et les paramètres du compte peuvent ajouter des coûts.",
  "a6.author": "Équipe de recherche de Chatora",
  "a6.date": "Mis à jour le 28 octobre 2026 · 10 min de lecture",
  "a6.callout": "<b>Instantané de la grille Meta :</b> pour les messages remis à un numéro égyptien (+20), la grille USD d’octobre 2026 indique <strong>0,0644 $</strong> par message marketing et <strong>0,0036 $</strong> par message utilitaire, d’authentification ou de service. Elle prévoit aussi 1 000 messages de service gratuits par mois et par numéro professionnel. Ce sont les tarifs de Meta, pas une facture complète du fournisseur.",
  "a6.b1": "Sommaire",
  "a6.b2": "<a href=\"#change\">Ce qui a changé le 1er octobre 2026</a>",
  "a6.b3": "<a href=\"#categories\">Les quatre catégories, expliquées simplement</a>",
  "a6.b4": "<a href=\"#bills\">Trois calculs illustratifs</a>",
  "a6.b5": "<a href=\"#tiers\">Autres règles de la grille et vérifications d’éligibilité</a>",
  "a6.b6": "<a href=\"#markups\">Comparer la facturation des fournisseurs</a>",
  "a6.b7": "<a href=\"#cut\">Sept façons de réduire la facture</a>",
  "a6.b8": "1. Ce qui a changé le 1er octobre 2026",
  "a6.b9": "Un article sur les tarifs WhatsApp écrit avant la fin de 2024 décrit un système qui n’existe plus : un tarif fixe par « conversation » de 24 heures. Meta l’a remplacé deux fois depuis.",
  "a6.b10": "<strong>Juillet 2025 — facturation par message, pas par conversation.</strong> Chaque modèle livré est facturé séparément. Envoyer un modèle marketing puis trois mises à jour le même jour entraîne désormais quatre frais, et non un seul.",
  "a6.b11": "<strong>1er octobre 2026 — les réponses de service sont de nouveau facturées.</strong> Les réponses envoyées pendant la fenêtre de service client de 24 heures étaient auparavant gratuites et sans plafond. Désormais, chaque numéro de téléphone professionnel bénéficie de <strong>1 000 messages de service gratuits par mois</strong> ; le 1 001e est facturé au tarif utilitaire du marché. Le quota est réinitialisé chaque mois et n’est pas reporté.",
  "a6.b12": "<strong>Vérifiez les règles et les catégories des modèles.</strong> Ne supposez pas qu’un modèle est gratuit parce que la fenêtre de service client est ouverte ; confirmez sa catégorie approuvée et son traitement tarifaire actuel.",
  "a6.b13": "Pour une petite boutique, la catégorie et le volume de messages livrés comptent tous les deux. Les anciens guides peuvent décrire des règles précédentes : vérifiez la date de toute estimation et comparez-la à la documentation actuelle de Meta.",
  "a6.b14": "2. Les quatre catégories, expliquées simplement",
  "a6.b15": "Meta classe chaque message envoyé dans une seule catégorie, qui détermine le tarif appliqué au pays du destinataire. Il n’y a ni négociation ni possibilité de « choisir » une catégorie moins chère : c’est le modèle soumis qui est classé.",
  "a6.b16": "<strong>Marketing</strong> — promotions et offres. La grille égyptienne d’octobre 2026 indique 0,0644 $ par message livré ; vérifiez le volume et les règles actuelles du compte.",
  "a6.b17": "<strong>Utilitaire</strong> — mises à jour admissibles concernant une transaction, comme une commande ou une expédition. La grille égyptienne indique 0,0036 $.",
  "a6.b18": "<strong>Authentification</strong> — mots de passe à usage unique et codes de connexion admissibles. La grille égyptienne indique 0,0036 $ ; un tarif international d’authentification peut s’appliquer dans les marchés admissibles. Vérifiez le tarif actuel du marché du destinataire.",
  "a6.b19": "<strong>Service</strong> — réponses du service client conformément aux règles actuelles de Meta. La grille prévoit 1 000 messages de service gratuits par mois et par numéro professionnel, puis 0,0036 $ en Égypte.",
  "a6.b20": "La grille actuelle de Meta définit les messages facturables et le mode de comptabilisation des livraisons. Consultez la dernière documentation et comparez le nombre de messages livrés à la facture du fournisseur, sans supposer que chaque message envoyé est facturé.",
  "a6.b21": "3. Trois calculs illustratifs",
  "a6.b22": "Ces exemples utilisent la grille égyptienne en vigueur depuis le 1er octobre 2026 et supposent que tous les messages mentionnés sont livrés et correctement classés. Ils excluent les frais du fournisseur, les taxes, les remises et les autres coûts de l’entreprise ; ce sont des calculs illustratifs, pas des factures client.",
  "a6.b23": "<b>Exemple 1 — messages de service.</b> Supposons qu’un numéro professionnel reçoive 12 000 réponses de service livrées en un mois. Après les 1 000 messages gratuits, 11 000 × 0,0036 $ = <strong>39,60 $</strong> de frais Meta. Les volumes réels et les autres frais peuvent varier.",
  "a6.b24": "<b>Exemple 2 — messages marketing.</b> Si 10 000 messages marketing destinés à des destinataires admissibles sont livrés à des numéros égyptiens, 10 000 × 0,0644 $ = <strong>644 $</strong> au tarif affiché par Meta. Il s’agit d’un calcul des frais Meta, pas de frais de plateforme ni d’une facture complète.",
  "a6.b25": "<b>Exemple 3 — relance de panier.</b> Si chacun de 800 paniers reçoit deux messages utilitaires livrés et que la catégorie et le contenu approuvés sont admissibles, 1 600 × 0,0036 $ = <strong>5,76 $</strong> de frais Meta. Avec une commande à 30 $ et une marge brute de 30 %, une récupération hypothétique de 4 % représente 288 $ de bénéfice brut avant les autres coûts — 50 fois cet exemple de frais de message, mais pas une estimation complète du retour sur investissement.",
  "a6.b26": "Ces exemples ne définissent ni une part de chiffre d’affaires ni une répartition de catégories typiques. Utilisez vos propres volumes de messages livrés, catégories approuvées, marges et factures fournisseur pour estimer vos coûts et résultats.",
  "a6.b27": "4. Autres règles de la grille et vérifications d’éligibilité",
  "a6.b28": "Les tarifs de Meta peuvent inclure des règles propres à certains marchés, des conditions d’éligibilité et des exceptions pour certains points d’entrée. La durée des fenêtres et les frais ont évolué, et la documentation des fournisseurs peut les présenter différemment. Avant d’intégrer une exception ou une fenêtre gratuite à votre budget, consultez la page tarifaire actuelle de Meta et les conditions propres au compte.",
  "a6.b29": "Si vous utilisez des publicités qui ouvrent WhatsApp, vérifiez quels messages sont admissibles à une éventuelle fenêtre sans frais, sa durée et l’inclusion ou non des modèles de suivi. Ne supposez pas que tous les messages de la conversation sont gratuits ; incluez les frais du fournisseur et le budget publicitaire dans votre estimation.",
  "a6.b30": "5. Comparer la facturation des fournisseurs",
  "a6.b31": "Les tarifs de Meta sont publics, mais une facture fournisseur peut utiliser une présentation et des modalités différentes. Par exemple, le guide ManyChat daté du 7 octobre 2026 indique 0,0740 $ par message marketing en Égypte ; la grille Meta en vigueur depuis le 1er octobre indique 0,0644 $. Cette différence ne suffit pas à en établir la cause ni à prouver une majoration précise. Demandez au fournisseur le tarif applicable, les frais inclus et un exemple de facture.",
  "a6.b32": "Questions à poser à tout fournisseur avant de connecter WhatsApp :",
  "a6.b33": "Quels tarifs de message et frais fournisseur s’appliquent à mon marché et à mon compte, et où sont-ils documentés ?",
  "a6.b34": "Les frais sont-ils par message, liés à l’utilisation ou forfaitaires par mois, et peuvent-ils varier selon le volume ?",
  "a6.b35": "Puis-je consulter le coût par message dans le tableau de bord avant l’envoi, ou uniquement sur la facture ?",
  "a6.b36": "Si je pars, est-ce que je conserve le numéro de téléphone et l’historique des modèles ?",
  "a6.b37": "6. Sept façons de réduire la facture",
  "a6.b38": "<strong>Laissez le client démarrer la conversation.</strong> Les messages entrants sont gratuits. Un parcours commentaire-vers-message privé ou clic-vers-chat fait porter le premier message du côté du client.",
  "a6.b39": "<strong>Réservez les 1 000 messages de service gratuits au support.</strong> Ne les dépensez pas en scripts de vente additionnelle : ce serait un coût marketing déguisé en assistance.",
  "a6.b40": "<strong>Segmentez selon la récence, pas selon la taille.</strong> Envoyer 10 000 messages aux personnes ayant acheté le mois dernier peut être préférable à 30 000 messages à toutes celles ayant un jour figuré dans la liste.",
  "a6.b41": "<strong>Envoyez les reçus comme messages utilitaires, pas marketing.</strong> « Votre commande a été expédiée » relève de l’utilitaire à 0,0036 $ ; un message « vous nous manquez ! » relève du marketing à 0,0644 $ et peut être signalé par les destinataires.",
  "a6.b42": "<strong>Utilisez les canaux déjà pris en charge par votre entreprise.</strong> L’e-mail ou un autre canal peut convenir à certaines mises à jour, mais vérifiez ses règles de consentement, de service et de tarification ; ne supposez pas qu’une intégration est active.",
  "a6.b43": "<strong>Surveillez la qualité et les livraisons.</strong> Suivez les alertes actuelles du compte Meta, examinez les réclamations et les résultats de livraison, puis mettez l’activité en pause ou ajustez-la si les règles l’exigent.",
  "a6.b44": "<strong>Demandez le rapprochement.</strong> La facturation Meta indique le nombre de messages livrés par catégorie. Comparez-le chaque mois au décompte de votre plateforme ; un écart signifie souvent que les modèles ont été classés différemment de ce que vous supposiez.",
  "a6.b45": "Chatora est actuellement un aperçu de produit sans tarif d’abonnement publié, sans canal WhatsApp connecté et sans estimation du coût des messages en direct. Il n’existe donc pas encore de tarif Chatora à comparer à ceux de Meta ou d’un autre fournisseur.",
  "a6.b46": "Questions fréquentes, en bref",
  "a6.b47": "L’API WhatsApp Business est-elle gratuite ?",
  "a6.b48": "La tarification Cloud API publiée par Meta est calculée par message pour les catégories et les marchés indiqués, mais les fournisseurs tiers peuvent facturer un abonnement ou des frais d’utilisation. Vérifiez la grille actuelle et les conditions du fournisseur pour votre compte.",
  "a6.b49": "Les réponses de service sont-elles redevenues payantes ?",
  "a6.b50": "Oui. Depuis le 1er octobre 2026, après avoir été gratuites depuis novembre 2024, chaque numéro professionnel bénéficie de 1 000 messages de service gratuits par mois ; les suivants sont facturés au tarif utilitaire du pays concerné.",
  "a6.b51": "Un BSP est-il obligatoire ?",
  "a6.b52": "Un fournisseur professionnel tiers n’est pas toujours nécessaire pour configurer Cloud API, mais l’inscription directe reste soumise aux exigences actuelles de Meta concernant les comptes, les autorisations et la technique. Consultez la documentation officielle et choisissez la voie adaptée à votre équipe.",
  "a6.b53": "Ces tarifs expirent-ils ?",
  "a6.b54": "Ils peuvent changer. Les chiffres ci-dessus ont été vérifiés sur la grille publiée par Meta le 28 octobre 2026 ; les tarifs et l’éligibilité peuvent évoluer. Consultez à nouveau la source officielle avant d’établir un budget.",
  "a6.b55": "Consultez la disponibilité actuelle",
  "a6.b56": "L’aperçu Chatora n’a ni canal WhatsApp connecté, ni tarif d’abonnement publié, ni estimation du coût des messages en direct. Pour établir un budget à jour, utilisez la grille officielle de Meta et les conditions de facturation de votre fournisseur.",
  "a6.cta": "Consulter la disponibilité de Chatora →",
  "a6.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs WhatsApp de Meta</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guide tarifaire WhatsApp de ManyChat</a>",
  "a6.b57": "Sources : documentation tarifaire WhatsApp Business Platform de Meta mise à jour le 30 septembre 2026, grille égyptienne de Meta en vigueur depuis le 1er octobre 2026 et guide tarifaire public WhatsApp de ManyChat consulté le 7 octobre 2026. Ces chiffres sont publiés par les fournisseurs, pas des factures de clients Chatora ; vérifiez les règles actuelles avant d’établir votre budget.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a6.h1": "WhatsApp-API-Preise in Ägypten (2026): Meta-Tarife und Kostenbeispiele",
  "a6.lede": "Meta berechnet WhatsApp-Nachrichten nach Kategorie und Empfängermarkt. Dieser Leitfaden nutzt Metas ägyptische Preisliste, gültig ab 1. Oktober 2026, für Beispielrechnungen einschließlich des monatlichen Freikontingents für Servicenachrichten. Es sind keine tatsächlichen Kundenrechnungen; Anbietergebühren, Steuern und Kontoeinstellungen können zusätzliche Kosten verursachen.",
  "a6.author": "Chatora-Rechercheteam",
  "a6.date": "Aktualisiert am 28. Oktober 2026 · 10 Min. Lesezeit",
  "a6.callout": "<b>Auszug aus Metas Preisliste:</b> Für Nachrichten an eine ägyptische Nummer (+20) nennt die USD-Preisliste vom Oktober 2026 <strong>0,0644 USD</strong> je Marketingnachricht und <strong>0,0036 USD</strong> je Utility-, Authentifizierungs- oder Servicenachricht. Außerdem sind 1.000 kostenlose Servicenachrichten pro Monat und Unternehmensnummer enthalten. Das sind Meta-Tarife, keine vollständige Anbieterrechnung.",
  "a6.b1": "Inhalt",
  "a6.b2": "<a href=\"#change\">Was sich am 1. Oktober 2026 geändert hat</a>",
  "a6.b3": "<a href=\"#categories\">Die vier Kategorien einfach erklärt</a>",
  "a6.b4": "<a href=\"#bills\">Drei Beispielrechnungen</a>",
  "a6.b5": "<a href=\"#tiers\">Weitere Preislistenregeln und Berechtigungsprüfungen</a>",
  "a6.b6": "<a href=\"#markups\">Anbieterabrechnungen vergleichen</a>",
  "a6.b7": "<a href=\"#cut\">Sieben Möglichkeiten, die Rechnung zu senken</a>",
  "a6.b8": "1. Was sich am 1. Oktober 2026 geändert hat",
  "a6.b9": "Wenn du einen WhatsApp-Preisartikel von vor Ende 2024 liest, beschreibt er ein nicht mehr gültiges Modell: eine Pauschale je 24-Stunden-„Konversation“. Meta hat es inzwischen zweimal ersetzt.",
  "a6.b10": "<strong>Juli 2025 — Abrechnung je Nachricht statt je Konversation.</strong> Jede zugestellte Vorlage wird einzeln berechnet. Eine Marketingvorlage und anschließend drei Updates am selben Tag ergeben nun vier Gebühren statt einer.",
  "a6.b11": "<strong>1. Oktober 2026 — Service-Antworten sind wieder kostenpflichtig.</strong> Antworten innerhalb des 24-stündigen Kundenservice-Fensters waren früher kostenlos und unbegrenzt. Jetzt erhält jede geschäftliche Telefonnummer <strong>1.000 kostenlose Servicenachrichten pro Monat</strong>; Nachricht 1.001 wird zum Utility-Tarif des Markts berechnet. Das Kontingent wird monatlich zurückgesetzt und nicht übertragen.",
  "a6.b12": "<strong>Vorlagenregeln und Kategorien prüfen.</strong> Gehe nicht davon aus, dass eine Vorlage kostenlos ist, nur weil das Kundenservice-Fenster offen ist; bestätige die genehmigte Kategorie und die aktuelle Behandlung in der Preisliste.",
  "a6.b13": "Für einen kleinen Shop sind sowohl Nachrichtenkategorie als auch Zustellvolumen wichtig. Ältere Leitfäden können frühere Regeln verwenden: Prüfe das Datum jeder Schätzung und vergleiche sie mit Metas aktueller Dokumentation.",
  "a6.b14": "2. Die vier Kategorien einfach erklärt",
  "a6.b15": "Meta ordnet jede gesendete Nachricht genau einer Kategorie zu; diese legt den Preis für das Land des Empfängers fest. Es gibt keine Verhandlung und keine Möglichkeit, eine günstigere Kategorie auszuwählen: Klassifiziert wird die eingereichte Vorlage.",
  "a6.b16": "<strong>Marketing</strong> — Werbeaktionen und Angebote. Die ägyptische Preisliste vom Oktober 2026 nennt 0,0644 USD je zugestellter Nachricht; prüfe das aktuelle Volumen und die Kontoregeln.",
  "a6.b17": "<strong>Utility</strong> — zulässige Updates zu einer Kundentransaktion, etwa Bestellung oder Versand. Die ägyptische Preisliste nennt 0,0036 USD.",
  "a6.b18": "<strong>Authentifizierung</strong> — zulässige Einmalpasswörter und Anmeldecodes. Die ägyptische Preisliste nennt 0,0036 USD; in berechtigten Märkten kann ein internationaler Authentifizierungstarif gelten. Prüfe den aktuellen Tarif des Empfängermarkts.",
  "a6.b19": "<strong>Service</strong> — Kundenservice-Antworten gemäß Metas aktuellen Regeln. Die Preisliste umfasst 1.000 kostenlose Servicenachrichten pro Monat und Unternehmensnummer, danach 0,0036 USD in Ägypten.",
  "a6.b20": "Metas aktuelle Preisliste legt fest, welche Nachrichten kostenpflichtig sind und wie Zustellungen gezählt werden. Prüfe die neueste Dokumentation und vergleiche zugestellte Nachrichten mit der Anbieterrechnung, statt anzunehmen, dass jede gesendete Nachricht berechnet wird.",
  "a6.b21": "3. Drei Beispielrechnungen",
  "a6.b22": "Diese Beispiele verwenden die ägyptische Preisliste, gültig ab 1. Oktober 2026, und setzen voraus, dass alle aufgeführten Nachrichten zugestellt und richtig klassifiziert werden. Anbietergebühren, Steuern, Rabatte und sonstige Geschäftskosten sind nicht enthalten; es sind Rechenbeispiele, keine Kundenrechnungen.",
  "a6.b23": "<b>Beispiel 1 — Servicenachrichten.</b> Angenommen, eine geschäftliche Telefonnummer erhält in einem Monat 12.000 zugestellte Service-Antworten. Nach den 1.000 kostenlosen Nachrichten werden 11.000 × 0,0036 USD = <strong>39,60 USD</strong> an Meta-Gebühren berechnet. Tatsächliche Mengen und andere Gebühren können abweichen.",
  "a6.b24": "<b>Beispiel 2 — Marketingnachrichten.</b> Werden 10.000 Marketingnachrichten an berechtigte Empfänger mit ägyptischen Nummern zugestellt, ergibt sich bei Metas Tarif 10.000 × 0,0644 USD = <strong>644 USD</strong>. Das ist eine Berechnung der Meta-Gebühren, keine Plattformgebühr und keine vollständige Rechnung.",
  "a6.b25": "<b>Beispiel 3 — Warenkorb-Nachfrage.</b> Wenn 800 Warenkörbe jeweils zwei zugestellte Utility-Nachrichten erhalten und Kategorie sowie genehmigter Inhalt zulässig sind, ergeben 1.600 × 0,0036 USD = <strong>5,76 USD</strong> an Meta-Gebühren. Bei einer Bestellung über 30 USD und 30 % Bruttomarge bedeutet eine hypothetische Rückgewinnung von 4 % einen Bruttogewinn von 288 USD vor sonstigen Kosten — das 50-Fache dieses Nachrichtenkostenbeispiels, aber keine vollständige ROI-Schätzung.",
  "a6.b26": "Diese Beispiele belegen weder einen typischen Umsatzanteil noch eine typische Kategorienverteilung. Nutze eigene Zahlen zu zugestellten Nachrichten, genehmigten Kategorien, Margen und Anbieterrechnungen, um Kosten und Ergebnisse für dein Unternehmen zu schätzen.",
  "a6.b27": "4. Weitere Preislistenregeln und Berechtigungsprüfungen",
  "a6.b28": "Metas Preise können marktspezifische Regeln, Berechtigungsbedingungen und Ausnahmen für bestimmte Einstiegspunkte enthalten. Zeitfenster und Gebühren haben sich geändert; Anbieterunterlagen können sie unterschiedlich beschreiben. Bevor du eine Ausnahme oder ein kostenloses Zeitfenster einplanst, prüfe Metas aktuelle Preisseite und die konkreten Kontobedingungen.",
  "a6.b29": "Wenn du Anzeigen verwendest, die WhatsApp öffnen, prüfe, welche Nachrichten für ein aktuelles kostenfreies Zeitfenster infrage kommen, wie lange es gilt und ob Folgevorlagen eingeschlossen sind. Gehe nicht davon aus, dass jede Nachricht der Unterhaltung kostenlos ist; berücksichtige Anbietergebühren und Werbeausgaben.",
  "a6.b30": "5. Anbieterabrechnungen vergleichen",
  "a6.b31": "Metas Tarife sind öffentlich, aber eine Anbieterrechnung kann andere Darstellungen und Abrechnungsbedingungen verwenden. So nennt der auf den 7. Oktober 2026 datierte ManyChat-Leitfaden 0,0740 USD je Marketingnachricht in Ägypten; Metas Preisliste, gültig ab 1. Oktober, nennt 0,0644 USD. Der Unterschied allein erklärt weder seine Ursache noch belegt er einen bestimmten Aufschlag. Frage den Anbieter nach dem gültigen Tarif, enthaltenen Gebühren und einer Beispielrechnung.",
  "a6.b32": "Fragen an jeden Anbieter vor dem Verbinden von WhatsApp:",
  "a6.b33": "Welche Nachrichtentarife und Anbietergebühren gelten für meinen Markt und mein Konto, und wo sind sie dokumentiert?",
  "a6.b34": "Werden Gebühren je Nachricht, nutzungsabhängig oder als monatliche Pauschale berechnet, und können sie je nach Volumen variieren?",
  "a6.b35": "Kann ich die Kosten je Nachricht im Dashboard vor dem Senden sehen oder erst auf der Rechnung?",
  "a6.b36": "Behalte ich Telefonnummer und Vorlagenverlauf, wenn ich den Anbieter verlasse?",
  "a6.b37": "6. Sieben Möglichkeiten, die Rechnung zu senken",
  "a6.b38": "<strong>Lass den Kunden den Chat beginnen.</strong> Eingehende Nachrichten sind kostenlos. Ein Kommentar-zu-DM- oder Click-to-Chat-Ablauf verlagert die erste Nachricht auf die Seite des Kunden.",
  "a6.b39": "<strong>Nutze die 1.000 kostenlosen Servicenachrichten für Support.</strong> Verschwende sie nicht für Upselling-Skripte — das wäre ein Marketingaufwand im Supportkostüm.",
  "a6.b40": "<strong>Segmentiere nach Aktualität, nicht nach Listengröße.</strong> 10.000 Nachrichten an Personen, die letzten Monat gekauft haben, können sinnvoller sein als 30.000 an alle, die jemals auf der Liste standen.",
  "a6.b41": "<strong>Versende Belege als Utility, nicht als Marketing.</strong> „Deine Bestellung wurde versendet“ gilt als Utility zu 0,0036 USD; eine „Wir vermissen dich!“-Nachricht als Marketing zu 0,0644 USD und kann von Empfängern gemeldet werden.",
  "a6.b42": "<strong>Nutze Kanäle, die dein Unternehmen bereits unterstützt.</strong> E-Mail oder ein anderer Kanal kann für manche Updates passen; prüfe jedoch dessen Einwilligungs-, Service- und Preisregeln und gehe nicht davon aus, dass eine Tool-Integration live ist.",
  "a6.b43": "<strong>Überwache Qualität und Zustellung.</strong> Beachte aktuelle Warnungen im Meta-Konto, prüfe Beschwerden und Zustellergebnisse und pausiere oder ändere Aktivitäten, wenn die Richtlinien es verlangen.",
  "a6.b44": "<strong>Fordere einen Abgleich an.</strong> Metas Abrechnung weist zugestellte Nachrichten je Kategorie aus. Vergleiche die Zahlen monatlich mit der Plattform; Abweichungen bedeuten oft, dass Vorlagen anders klassifiziert wurden als erwartet.",
  "a6.b45": "Chatora ist derzeit eine Produktvorschau ohne veröffentlichten Abonnementpreis, verbundenen WhatsApp-Kanal oder Live-Schätzung der Nachrichtenkosten. Es gibt noch keinen Chatora-Tarif, der mit Meta oder einem anderen Anbieter verglichen werden könnte.",
  "a6.b46": "Häufige Fragen, kurz beantwortet",
  "a6.b47": "Ist die WhatsApp Business API kostenlos?",
  "a6.b48": "Metas veröffentlichte Cloud-API-Preise werden für die aufgeführten Kategorien und Märkte je Nachricht berechnet; Drittanbieter können jedoch Abonnements oder Nutzungsgebühren erheben. Prüfe die aktuelle Preisliste und die Anbieterbedingungen für dein Konto.",
  "a6.b49": "Sind Service-Antworten nicht mehr kostenlos?",
  "a6.b50": "Ja. Seit dem 1. Oktober 2026, nachdem sie seit November 2024 kostenlos waren, erhält jede geschäftliche Telefonnummer 1.000 kostenlose Servicenachrichten pro Monat; weitere werden zum Utility-Tarif des jeweiligen Landes berechnet.",
  "a6.b51": "Ist ein BSP verpflichtend?",
  "a6.b52": "Für eine Cloud-API-Einrichtung ist nicht immer ein externer Business-Provider erforderlich. Eine direkte Einrichtung muss aber weiterhin Metas aktuelle Konto-, Berechtigungs- und technischen Anforderungen erfüllen. Prüfe die offizielle Dokumentation und wähle den passenden Umsetzungsweg für dein Team.",
  "a6.b53": "Verfallen diese Preise?",
  "a6.b54": "Sie können sich ändern. Die obigen Werte wurden mit Metas veröffentlichter Preisliste vom 28. Oktober 2026 abgeglichen; Tarife und Berechtigungen können sich ändern. Prüfe vor der Budgetplanung erneut die offizielle Quelle.",
  "a6.b55": "Aktuelle Verfügbarkeit prüfen",
  "a6.b56": "Chatoras Vorschau hat keinen verbundenen WhatsApp-Kanal, keinen veröffentlichten Abonnementpreis und keine Live-Schätzung der Nachrichtenkosten. Nutze für ein aktuelles Budget Metas offizielle Preisliste und die Abrechnungsbedingungen deines Anbieters.",
  "a6.cta": "Chatora-Verfügbarkeit prüfen →",
  "a6.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Meta-Preise für WhatsApp</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">ManyChat-Leitfaden zu WhatsApp-Preisen</a>",
  "a6.b57": "Quellen: Metas Dokumentation zur WhatsApp Business Platform, aktualisiert am 30. September 2026; Metas ägyptische Preisliste, gültig ab 1. Oktober 2026; und ManyChats öffentlicher WhatsApp-Preisleitfaden, geprüft am 7. Oktober 2026. Es sind veröffentlichte Anbieterwerte, keine Chatora-Kundenrechnungen; prüfe vor der Budgetplanung die aktuellen Regeln.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a6.h1": "Preços da API do WhatsApp no Egito (2026): tarifas da Meta e exemplos de custos",
  "a6.lede": "A Meta define o preço das mensagens do WhatsApp por categoria e mercado do destinatário. Este guia usa a tabela do Egito vigente desde 1º de outubro de 2026 para mostrar cálculos de exemplo, incluindo a franquia mensal de mensagens de serviço gratuitas. Não são faturas reais de clientes; cobranças do fornecedor, impostos e configurações da conta podem acrescentar custos.",
  "a6.author": "Equipe de pesquisa da Chatora",
  "a6.date": "Atualizado em 28 de outubro de 2026 · 10 min de leitura",
  "a6.callout": "<b>Retrato da tabela da Meta:</b> para mensagens entregues a um número egípcio (+20), a tabela em USD de outubro de 2026 lista <strong>US$ 0,0644</strong> por mensagem de marketing e <strong>US$ 0,0036</strong> por mensagem de utilidade, autenticação ou serviço. Também inclui 1.000 mensagens de serviço gratuitas por mês, por número comercial. São tarifas da Meta, não uma fatura completa do fornecedor.",
  "a6.b1": "Conteúdo",
  "a6.b2": "<a href=\"#change\">O que mudou em 1º de outubro de 2026</a>",
  "a6.b3": "<a href=\"#categories\">As quatro categorias explicadas de forma simples</a>",
  "a6.b4": "<a href=\"#bills\">Três cálculos ilustrativos</a>",
  "a6.b5": "<a href=\"#tiers\">Outras regras da tabela e verificações de elegibilidade</a>",
  "a6.b6": "<a href=\"#markups\">Como comparar a cobrança dos fornecedores</a>",
  "a6.b7": "<a href=\"#cut\">Sete maneiras de reduzir a fatura</a>",
  "a6.b8": "1. O que mudou em 1º de outubro de 2026",
  "a6.b9": "Se você ler um artigo sobre preços do WhatsApp escrito antes do fim de 2024, ele descreve um modelo que não existe mais: uma tarifa fixa por \"conversa\" de 24 horas. A Meta já o substituiu duas vezes.",
  "a6.b10": "<strong>Julho de 2025 — por mensagem, não por conversa.</strong> Cada modelo entregue é cobrado separadamente. Enviar um modelo de marketing e depois três atualizações no mesmo dia agora gera quatro cobranças, não uma.",
  "a6.b11": "<strong>1º de outubro de 2026 — respostas de serviço voltam a ser cobradas.</strong> Antes, as respostas enviadas durante a janela de atendimento de 24 horas eram gratuitas e ilimitadas. Agora cada número de telefone comercial recebe <strong>1.000 mensagens de serviço gratuitas por mês</strong>; a mensagem 1.001 é cobrada pela tarifa de utilidade do mercado. A franquia é renovada mensalmente e não acumula.",
  "a6.b12": "<strong>Confira as regras e categorias dos modelos.</strong> Não presuma que um modelo é gratuito porque a janela de atendimento ao cliente está aberta; confirme a categoria aprovada e o tratamento atual na tabela.",
  "a6.b13": "Para uma loja pequena, a categoria da mensagem e o volume entregue são importantes. Guias antigos podem usar regras anteriores: confira a data de qualquer estimativa e compare-a com a documentação atual da Meta.",
  "a6.b14": "2. As quatro categorias explicadas de forma simples",
  "a6.b15": "A Meta classifica cada mensagem enviada em exatamente uma categoria, que define o preço para o país do destinatário. Não há negociação nem como \"escolher\" uma categoria mais barata: a classificação depende do modelo enviado.",
  "a6.b16": "<strong>Marketing</strong> — promoções e ofertas. A tabela do Egito de outubro de 2026 lista US$ 0,0644 por mensagem entregue; confira o volume e as regras atuais da conta.",
  "a6.b17": "<strong>Utilidade</strong> — atualizações qualificadas sobre uma transação do cliente, como pedido ou envio. A tabela do Egito lista US$ 0,0036.",
  "a6.b18": "<strong>Autenticação</strong> — senhas de uso único e códigos de login qualificados. A tabela do Egito lista US$ 0,0036; uma tarifa internacional de autenticação pode se aplicar em mercados elegíveis. Confira a tarifa atual do mercado do destinatário.",
  "a6.b19": "<strong>Serviço</strong> — respostas de atendimento ao cliente conforme as regras atuais da Meta. A tabela inclui 1.000 mensagens de serviço gratuitas por mês, por número comercial; depois, a tarifa no Egito é de US$ 0,0036.",
  "a6.b20": "A tabela atual da Meta define quais mensagens são cobradas e como a entrega é contabilizada. Consulte a documentação mais recente e compare as mensagens entregues com a fatura do fornecedor, em vez de presumir que toda mensagem enviada será cobrada.",
  "a6.b21": "3. Três cálculos ilustrativos",
  "a6.b22": "Estes exemplos usam a tabela do Egito vigente desde 1º de outubro de 2026 e pressupõem que todas as mensagens listadas foram entregues e classificadas corretamente. Não incluem taxas do fornecedor, impostos, descontos nem outros custos comerciais; são exemplos de cálculo, não faturas de clientes.",
  "a6.b23": "<b>Exemplo 1 — mensagens de serviço.</b> Suponha que um número comercial receba 12.000 respostas de serviço entregues em um mês. Após as 1.000 mensagens gratuitas, 11.000 × US$ 0,0036 = <strong>US$ 39,60</strong> em tarifas da Meta. Volumes reais e outras cobranças podem variar.",
  "a6.b24": "<b>Exemplo 2 — mensagens de marketing.</b> Se 10.000 mensagens de marketing forem entregues a destinatários elegíveis com números egípcios, 10.000 × US$ 0,0644 = <strong>US$ 644</strong> pela tarifa listada da Meta. É um cálculo de tarifas da Meta, não uma cobrança da plataforma nem uma fatura completa.",
  "a6.b25": "<b>Exemplo 3 — acompanhamento de carrinho.</b> Se cada um de 800 carrinhos receber duas mensagens de utilidade entregues e a categoria e o conteúdo aprovados forem elegíveis, 1.600 × US$ 0,0036 = <strong>US$ 5,76</strong> em tarifas da Meta. Com um pedido de US$ 30 e margem bruta de 30%, uma recuperação hipotética de 4% representa US$ 288 de lucro bruto antes de outros custos — 50 vezes este exemplo de tarifa de mensagens, mas não uma estimativa completa de ROI.",
  "a6.b26": "Esses exemplos não estabelecem uma participação típica de receita nem uma combinação típica de categorias. Use seus próprios números de mensagens entregues, categorias aprovadas, margem e fatura do fornecedor para estimar custos e resultados da sua empresa.",
  "a6.b27": "4. Outras regras da tabela e verificações de elegibilidade",
  "a6.b28": "Os preços da Meta podem incluir regras específicas por mercado, condições de elegibilidade e exceções para determinados pontos de entrada. A duração das janelas e as tarifas mudaram, e a documentação dos fornecedores pode descrevê-las de outra forma. Antes de incluir uma exceção ou janela gratuita no orçamento, confira a página atual de preços da Meta e as condições específicas da conta.",
  "a6.b29": "Se você usar anúncios que abrem o WhatsApp, confirme quais mensagens se qualificam para uma janela atual sem cobrança, por quanto tempo e se modelos de acompanhamento estão incluídos. Não presuma que todas as mensagens da conversa são gratuitas; inclua na estimativa as cobranças do fornecedor e o gasto com anúncios.",
  "a6.b30": "5. Como comparar a cobrança dos fornecedores",
  "a6.b31": "As tarifas da Meta são públicas, mas a fatura do fornecedor pode usar outra apresentação e outras condições de cobrança. Por exemplo, o guia do ManyChat de 7 de outubro de 2026 lista US$ 0,0740 por mensagem de marketing no Egito; a tabela da Meta vigente desde 1º de outubro lista US$ 0,0644. A diferença, por si só, não explica a causa nem comprova uma margem específica. Peça ao fornecedor a tarifa aplicável, as taxas incluídas e uma fatura de exemplo.",
  "a6.b32": "Perguntas para fazer a qualquer fornecedor antes de conectar o WhatsApp:",
  "a6.b33": "Quais tarifas de mensagens e cobranças do fornecedor se aplicam ao meu mercado e à minha conta, e onde estão documentadas?",
  "a6.b34": "As cobranças são por mensagem, baseadas no uso ou uma mensalidade fixa? Podem variar conforme o volume?",
  "a6.b35": "Posso ver o custo por mensagem no painel antes do envio ou somente na fatura?",
  "a6.b36": "Se eu sair, mantenho o número de telefone e o histórico de modelos?",
  "a6.b37": "6. Sete maneiras de reduzir a fatura",
  "a6.b38": "<strong>Deixe o cliente iniciar a conversa.</strong> Mensagens recebidas são gratuitas. Um fluxo de comentário para DM ou de clique para conversar coloca a primeira mensagem do lado do cliente.",
  "a6.b39": "<strong>Reserve as 1.000 mensagens de serviço gratuitas para atendimento.</strong> Não as desperdice em scripts de venda adicional — isso é custo de marketing disfarçado de suporte.",
  "a6.b40": "<strong>Segmente pela recência, não pelo tamanho.</strong> Enviar 10.000 mensagens a quem comprou no mês passado pode ser melhor do que mandar 30.000 para todos que já estiveram na lista.",
  "a6.b41": "<strong>Envie recibos como utilidade, não marketing.</strong> \"Seu pedido foi enviado\" é utilidade a US$ 0,0036; uma mensagem \"estamos com saudade!\" é marketing a US$ 0,0644 e pode ser denunciada pelos destinatários.",
  "a6.b42": "<strong>Use os canais que sua empresa já atende.</strong> E-mail ou outro canal pode servir para algumas atualizações, mas confira as regras de consentimento, serviço e preço; não presuma que a integração de uma ferramenta está ativa.",
  "a6.b43": "<strong>Monitore a qualidade e as entregas.</strong> Acompanhe os alertas atuais da conta da Meta, confira reclamações e resultados de entrega e pause ou ajuste a atividade quando as políticas exigirem.",
  "a6.b44": "<strong>Peça a conciliação.</strong> A cobrança da Meta mostra o número de mensagens entregues por categoria. Compare mensalmente com a contagem da plataforma; divergências costumam indicar que os modelos foram classificados de forma diferente da esperada.",
  "a6.b45": "A Chatora é atualmente uma prévia do produto sem preço de assinatura publicado, canal do WhatsApp conectado ou estimativa de custo de mensagens ao vivo. Ainda não há uma tarifa da Chatora para comparar com a Meta ou outro fornecedor.",
  "a6.b46": "Perguntas frequentes, em resumo",
  "a6.b47": "A API do WhatsApp Business é gratuita?",
  "a6.b48": "A tarifa publicada da Cloud API da Meta é por mensagem para as categorias e mercados listados, mas fornecedores terceirizados podem cobrar assinatura ou tarifas de uso. Confira a tabela vigente e as condições do fornecedor para sua conta.",
  "a6.b49": "As respostas de serviço deixaram de ser gratuitas?",
  "a6.b50": "Sim. Desde 1º de outubro de 2026, após serem gratuitas desde novembro de 2024, cada número comercial recebe 1.000 mensagens de serviço gratuitas por mês; as demais são cobradas pela tarifa de utilidade do país.",
  "a6.b51": "É obrigatório contratar um BSP?",
  "a6.b52": "Nem sempre é necessário um provedor comercial terceirizado para configurar a Cloud API, mas a integração direta ainda envolve os requisitos atuais de conta, permissões e tecnologia da Meta. Consulte a documentação oficial e escolha o caminho adequado à sua equipe.",
  "a6.b53": "Esses valores vencem?",
  "a6.b54": "Eles podem mudar. Os valores acima foram conferidos na tabela publicada pela Meta em 28 de outubro de 2026; tarifas e elegibilidade podem mudar, então consulte a fonte oficial novamente antes de fazer o orçamento.",
  "a6.b55": "Consulte a disponibilidade atual",
  "a6.b56": "A prévia da Chatora não tem canal do WhatsApp conectado, preço de assinatura publicado nem estimativa ao vivo do custo das mensagens. Para um orçamento atual, use a tabela oficial da Meta e as condições de cobrança do seu fornecedor.",
  "a6.cta": "Consultar disponibilidade da Chatora →",
  "a6.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do WhatsApp da Meta</a> · <a href=\"https://help.manychat.com/hc/en-us/articles/14281380243740-WhatsApp-pricing-guide\" rel=\"noopener noreferrer\" target=\"_blank\">Guia de preços do WhatsApp do ManyChat</a>",
  "a6.b57": "Fontes: documentação de preços da WhatsApp Business Platform da Meta, atualizada em 30 de setembro de 2026; tabela da Meta para o Egito vigente desde 1º de outubro de 2026; e guia público de preços do WhatsApp do ManyChat, consultado em 7 de outubro de 2026. São valores publicados por fornecedores, não faturas de clientes da Chatora; confira as regras atuais antes de fazer o orçamento.",
});


/* Article a7 translations: WhatsApp abandoned-cart messages. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a7.h1": "Mensajes de WhatsApp para carritos abandonados: ejemplos, escenarios de tarifas y comprobaciones de políticas",
  "a7.lede": "No existe una tasa de recuperación ni una secuencia de mensajes universal que garantice beneficios. Esta guía presenta textos ilustrativos, explica cómo afectan las categorías de mensajes de Meta a las tarifas y qué debes comprobar sobre consentimiento y tiempos. La vista previa de Chatora no tiene una conexión activa con WhatsApp.",
  "a7.author": "Equipo de investigación de Chatora",
  "a7.date": "Actualizado el 28 de octubre de 2026 · 8 min de lectura",
  "a7.callout": "<b>Primero las tarifas, no el ROI:</b> con las tarifas de Meta para Egipto de octubre de 2026, tres mensajes entregados costarían <strong>0,1932 USD</strong> si todos se clasifican como Marketing o <strong>0,0108 USD</strong> si cada uno cumple legítimamente los requisitos de Utility. La categoría aprobada por Meta depende del contenido y las reglas, no del precio que prefiera quien envía. Estas cifras excluyen las tarifas del proveedor, los impuestos, los descuentos y los costes operativos; no determinan un umbral de rentabilidad.",
  "a7.b1": "Contenido",
  "a7.b2": "<a href=\"#why\">Por qué se abandonan los carritos y qué puedes corregir</a>",
  "a7.b3": "<a href=\"#sequence\">Los tres mensajes, con ejemplos de texto</a>",
  "a7.b4": "<a href=\"#timing\">Momento, consentimiento y frecuencia</a>",
  "a7.b5": "<a href=\"#cost\">Escenarios de tarifas de Meta y supuestos</a>",
  "a7.b6": "<a href=\"#never\">Cinco motivos para que bloqueen tus mensajes</a>",
  "a7.b7": "1. Por qué se abandonan los carritos y qué puedes corregir",
  "a7.b8": "Los mensajes de recuperación solo ayudan con un tipo de abandono. Antes de redactar nada, decide cuál de estos casos intentas abordar:",
  "a7.b9": "<strong>Distracción.</strong> Es posible que el comprador pensara volver después de una interrupción; un recordatorio puede ayudar, pero no garantiza la recuperación.",
  "a7.b10": "<strong>Precio o coste de entrega.</strong> El envío o el pago contra entrega pueden influir en la decisión. Un descuento reduce el margen; prueba cualquier oferta frente a un mensaje sin descuento.",
  "a7.b11": "<strong>Confianza.</strong> La falta de opiniones, condiciones de devolución o datos de la empresa puede generar dudas. Un mensaje de seguimiento no sustituye la información clara en la página del producto.",
  "a7.b12": "<strong>Preguntas sobre la entrega.</strong> Es posible que los clientes necesiten información precisa sobre zonas y plazos de entrega o aduanas; responde solo con datos que puedas verificar.",
  "a7.b13": "Si puedes preguntar a los clientes por qué dejaron el pago, recopila sus comentarios con el consentimiento adecuado y compáralos con los datos de tus propios pedidos. No sustituyas las pruebas de tu tienda por una referencia genérica.",
  "a7.b14": "2. Los tres mensajes, con ejemplos de texto",
  "a7.b15": "Los tres mensajes siguientes son textos ilustrativos, no plantillas aprobadas ni una secuencia probada. Un recordatorio de carrito abandonado puede clasificarse como Marketing; no supongas que cumple los requisitos de Utility. Confirma el consentimiento, la aprobación de la plantilla y la categoría de Meta aplicable antes de enviarlo.",
  "a7.b16": "<b>Mensaje de ejemplo 1 · momento que se debe probar, si está permitido.</b> «أهلًا {first_name} 👋 سلة {{product}} لسه محفوظة عندك — تحب أكمّل الأوردر معاك؟ لو محتاج تغيّر المقاس أو العنوان، قولّي.» El texto es ilustrativo; verifica el consentimiento, la categoría del mensaje y los requisitos de la plantilla.",
  "a7.b17": "<b>Mensaje de ejemplo 2 · actualización logística opcional.</b> Responde a una pregunta real con información verificada sobre plazos de entrega, disponibilidad del pago contra entrega o condiciones de devolución. Envíala solo si lo permiten el consentimiento y las reglas vigentes del canal.",
  "a7.b18": "<b>Mensaje de ejemplo 3 · nota final opcional.</b> Usa una fecha de vencimiento o una afirmación sobre existencias solo cuando sea cierta y verificable. Cualquier incentivo debe ajustarse a tu margen y a las reglas de marketing aplicables.",
  "a7.b19": "Antes de enviar, confirma el consentimiento, la plantilla y categoría aprobadas y el tratamiento de las tarifas en la tarifa vigente de Meta. Evita la urgencia exagerada y supervisa las entregas, las bajas y los comentarios de los clientes.",
  "a7.b20": "3. Momento, consentimiento y frecuencia",
  "a7.b21": "No existe un retraso ideal universal. Prueba el momento solo con clientes que hayan dado el consentimiento requerido, respeta las ventanas de mensajería de la plataforma y compara entregas, respuestas, bajas y pedidos atribuibles en tu propia cuenta.",
  "a7.b22": "Evita enviar recordatorios superpuestos para un mismo pedido; detén o actualiza una secuencia anterior cuando cambie el estado del carrito o del pedido.",
  "a7.b23": "Establece un límite de frecuencia prudente según el consentimiento del cliente, la legislación local y las reglas vigentes de la plataforma; una secuencia de tres mensajes es solo un ejemplo, no un requisito de Meta.",
  "a7.b24": "Si el cliente responde o finaliza el pago, pausa los recordatorios automáticos y deriva las preguntas a una persona cuando sea necesario.",
  "a7.b25": "Ten en cuenta la hora local y las preferencias del destinatario. Supervisa las bajas, quejas y alertas de la cuenta; ninguna hora garantiza una respuesta concreta.",
  "a7.b26": "4. Escenarios de tarifas de Meta y supuestos",
  "a7.b27": "Con las tarifas de Egipto vigentes desde el 1 de octubre de 2026, tres mensajes entregados cuestan <strong>0,1932 USD</strong> por carrito si los tres se clasifican como Marketing (0,0644 USD cada uno), o <strong>0,0108 USD</strong> si todos cumplen legítimamente los requisitos de Utility (0,0036 USD cada uno). La categoría aprobada depende del contenido y de las reglas de Meta. Estos importes excluyen las tarifas del proveedor, impuestos, descuentos, mano de obra, devoluciones y el coste de las existencias sin vender.",
  "a7.b28": "Para estimar la rentabilidad, usa tus propios pedidos recuperados atribuibles y el margen de contribución, y después resta todos los costes pertinentes. Cuando sea posible, compara periodos coherentes o un grupo de control; aquí no se afirma una tasa general de recuperación ni un resultado de beneficios.",
  "a7.b29": "5. Cinco problemas que debes evitar",
  "a7.b30": "Ofrecer un descuento sin comprobar el margen de contribución, la elegibilidad y si un recordatorio sin descuento también podría ayudar al cliente.",
  "a7.b31": "Ignorar una baja o una solicitud para dejar de recibir mensajes. Mantén registros de supresión y sigue las reglas vigentes del canal.",
  "a7.b32": "Etiquetar contenido promocional como Utility para buscar una tarifa menor. La categoría aprobada por Meta y su política vigente determinan el tratamiento aplicable.",
  "a7.b33": "Enviar un recordatorio de carrito a un público amplio sin comprobar el consentimiento, la pertinencia y la elegibilidad actual de cada destinatario.",
  "a7.b34": "Dejar una pregunta del cliente sin resolver. Ofrece una vía adecuada para recibir asistencia humana y pausa los recordatorios automáticos cuando corresponda.",
  "a7.b35": "Chatora no tiene una conexión activa con WhatsApp o Instagram, un activador de carrito, aprobación de plantillas ni un flujo de envío. La secuencia de esta página es texto ilustrativo; no se puede publicar ni enviar desde la vista previa actual.",
  "a7.b36": "Preguntas frecuentes, en breve",
  "a7.b37": "¿Cuántos mensajes debe incluir un flujo para carritos abandonados?",
  "a7.b38": "No existe una cantidad ideal universal. Empieza con la secuencia más breve que atienda la necesidad del cliente y después prueba tiempos y frecuencia dentro de las reglas de consentimiento y de la plataforma, vigilando las bajas y quejas.",
  "a7.b39": "¿Un flujo de carrito necesita un descuento?",
  "a7.b40": "No siempre. Un descuento puede reducir el margen; compáralo con un recordatorio informativo y mide los pedidos atribuibles y el margen de contribución antes de decidir.",
  "a7.b41": "¿Un mensaje de carrito abandonado es Marketing o Utility?",
  "a7.b42": "No automáticamente. La categoría aprobada por Meta depende del contenido del mensaje y de las reglas vigentes. Un recordatorio promocional de carrito puede ser Marketing; no lo etiquetes como Utility solo porque haya un carrito.",
  "a7.b43": "Consulta la disponibilidad actual de Chatora",
  "a7.b44": "Chatora es una vista previa del producto sin canal de WhatsApp conectado, activador de carrito en directo ni plan de suscripción gratuito o de pago. La galería pública de plantillas contiene borradores iniciales editables, no automatización de mensajería activa.",
  "a7.cta": "Consultar disponibilidad →",
  "a7.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de WhatsApp de Meta</a>",
  "a7.b45": "Fuente: tarifa de WhatsApp de Meta vigente desde el 1 de octubre de 2026. Los textos y cálculos de costes son ilustrativos; no se utilizan datos de recuperación de clientes de Chatora ni referencias de rendimiento.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a7.h1": "Messages WhatsApp de relance de panier : exemples, scénarios tarifaires et règles à vérifier",
  "a7.lede": "Il n’existe aucun taux de récupération ni aucune séquence de messages universels garantissant un bénéfice. Ce guide présente des exemples de textes, explique l’effet des catégories de messages Meta sur les frais et indique les points à vérifier concernant le consentement et le moment d’envoi. L’aperçu Chatora n’a pas de connexion WhatsApp en direct.",
  "a7.author": "Équipe de recherche de Chatora",
  "a7.date": "Mis à jour le 28 octobre 2026 · 8 min de lecture",
  "a7.callout": "<b>Les frais d’abord, pas le ROI :</b> aux tarifs Meta d’octobre 2026 en Égypte, trois messages livrés coûteraient <strong>0,1932 $</strong> s’ils étaient tous classés Marketing, ou <strong>0,0108 $</strong> s’ils remplissaient tous légitimement les critères Utilitaire. La catégorie approuvée par Meta dépend du contenu et des règles, pas du tarif préféré par l’expéditeur. Ces chiffres excluent les frais fournisseur, les taxes, les remises et les coûts d’exploitation ; ils ne définissent pas un seuil de rentabilité.",
  "a7.b1": "Sommaire",
  "a7.b2": "<a href=\"#why\">Pourquoi les paniers sont abandonnés et ce que vous pouvez corriger</a>",
  "a7.b3": "<a href=\"#sequence\">Trois messages avec exemples de texte</a>",
  "a7.b4": "<a href=\"#timing\">Moment, consentement et fréquence</a>",
  "a7.b5": "<a href=\"#cost\">Scénarios de frais Meta et hypothèses</a>",
  "a7.b6": "<a href=\"#never\">Cinq motifs de blocage à éviter</a>",
  "a7.b7": "1. Pourquoi les paniers sont abandonnés — et ce que vous pouvez corriger",
  "a7.b8": "Les messages de relance ne fonctionnent que sur un type d’abandon. Avant de rédiger quoi que ce soit, déterminez lequel vous cherchez réellement à traiter :",
  "a7.b9": "<strong>Distraction.</strong> Un acheteur peut vouloir revenir après avoir été interrompu ; un rappel peut aider, mais ne garantit pas la récupération.",
  "a7.b10": "<strong>Prix ou frais de livraison.</strong> Les frais d’expédition ou de paiement à la livraison peuvent peser dans la décision. Une remise réduit la marge ; testez toute offre face à un rappel sans remise.",
  "a7.b11": "<strong>Confiance.</strong> L’absence d’avis, de conditions de retour ou d’informations sur l’entreprise peut susciter des doutes. Un message de suivi ne remplace pas des informations claires sur la page produit.",
  "a7.b12": "<strong>Questions de livraison.</strong> Les clients peuvent avoir besoin d’informations exactes sur les zones et délais de livraison ou les formalités douanières ; ne répondez qu’avec des détails vérifiables.",
  "a7.b13": "Si vous pouvez demander aux clients pourquoi ils ont quitté le paiement, recueillez leurs commentaires avec le consentement approprié et comparez-les à vos propres données de commande. Ne remplacez pas les données de votre boutique par un indicateur générique.",
  "a7.b14": "2. Trois messages avec exemples de texte",
  "a7.b15": "Les trois messages ci-dessous sont des exemples de rédaction, pas des modèles approuvés ni une séquence éprouvée. Un rappel de panier abandonné peut être classé Marketing ; ne supposez pas qu’il est admissible comme Utilitaire. Vérifiez le consentement, l’approbation du modèle et la catégorie Meta applicable avant l’envoi.",
  "a7.b16": "<b>Exemple de message 1 · délai à tester, si autorisé.</b> «أهلًا {first_name} 👋 سلة {{product}} لسه محفوظة عندك — تحب أكمّل الأوردر معاك؟ لو محتاج تغيّر المقاس أو العنوان، قولّي.» Texte d’exemple uniquement ; vérifiez le consentement, la catégorie du message et les exigences relatives au modèle.",
  "a7.b17": "<b>Exemple de message 2 · mise à jour logistique facultative.</b> Répondez à une vraie question avec des informations vérifiées sur les délais de livraison, le paiement à la livraison ou les conditions de retour. N’envoyez ce message que si le consentement et les règles actuelles du canal l’autorisent.",
  "a7.b18": "<b>Exemple de message 3 · note finale facultative.</b> N’indiquez une échéance ou un niveau de stock que si l’information est vraie et vérifiable. Toute incitation doit respecter votre marge et les règles marketing applicables.",
  "a7.b19": "Avant l’envoi, confirmez le consentement, le modèle et la catégorie approuvés ainsi que le traitement tarifaire dans la grille actuelle de Meta. Évitez les urgences exagérées et surveillez les livraisons, les désabonnements et les retours des clients.",
  "a7.b20": "3. Moment, consentement et fréquence",
  "a7.b21": "Il n’existe pas de délai idéal universel. Testez le moment d’envoi uniquement auprès de clients ayant donné le consentement requis, respectez les fenêtres de messagerie de la plateforme et comparez livraisons, réponses, désabonnements et commandes attribuables dans votre compte.",
  "a7.b22": "Évitez les rappels qui se chevauchent pour une même commande ; arrêtez ou mettez à jour une séquence précédente lorsque l’état du panier ou de la commande change.",
  "a7.b23": "Fixez une limite de fréquence prudente selon le consentement du client, la loi locale et les règles actuelles de la plateforme ; une séquence de trois messages est un exemple, pas une exigence de Meta.",
  "a7.b24": "Si le client répond ou finalise sa commande, mettez les rappels automatiques en pause et transférez les questions à une personne si nécessaire.",
  "a7.b25": "Tenez compte de l’heure locale et des préférences du destinataire. Surveillez les désabonnements, les réclamations et les alertes du compte ; aucune heure ne garantit une réponse particulière.",
  "a7.b26": "4. Scénarios de frais Meta et hypothèses",
  "a7.b27": "Aux tarifs égyptiens en vigueur depuis le 1er octobre 2026, trois messages livrés coûtent <strong>0,1932 $</strong> par panier s’ils sont tous classés Marketing (0,0644 $ chacun), ou <strong>0,0108 $</strong> s’ils remplissent légitimement les critères Utilitaire (0,0036 $ chacun). La catégorie approuvée dépend du contenu et des règles de Meta. Ces montants excluent les frais fournisseur, les taxes, les remises, la main-d’œuvre, les retours et le coût des stocks invendus.",
  "a7.b28": "Pour estimer la rentabilité, utilisez vos propres commandes récupérées attribuables et votre marge contributive, puis déduisez tous les coûts pertinents. Comparez une période cohérente ou un groupe témoin lorsque c’est possible ; aucun taux général de récupération ni résultat de bénéfice n’est avancé ici.",
  "a7.b29": "5. Cinq problèmes à éviter",
  "a7.b30": "Proposer une remise sans vérifier la marge contributive, l’éligibilité et si un rappel sans remise serait aussi utile au client.",
  "a7.b31": "Ignorer un désabonnement ou une demande d’arrêt. Tenez à jour les listes de suppression et respectez les règles actuelles du canal.",
  "a7.b32": "Classer un texte promotionnel comme Utilitaire pour obtenir un tarif plus bas. Le traitement applicable dépend de la catégorie approuvée par Meta et de ses règles actuelles.",
  "a7.b33": "Envoyer un rappel de panier à une large audience sans vérifier le consentement, la pertinence et l’éligibilité actuelle de chaque destinataire.",
  "a7.b34": "Laisser une question du client sans réponse. Proposez un accès adapté à une assistance humaine et mettez les rappels automatiques en pause si nécessaire.",
  "a7.b35": "Chatora n’a ni connexion WhatsApp ou Instagram en direct, ni déclencheur de panier, ni approbation de modèle, ni flux d’envoi. La séquence de cette page est un exemple de texte ; elle ne peut pas être publiée ni envoyée depuis l’aperçu actuel.",
  "a7.b36": "Questions fréquentes, en bref",
  "a7.b37": "Combien de messages faut-il dans un parcours de relance de panier ?",
  "a7.b38": "Il n’existe pas de nombre idéal universel. Commencez par la séquence la plus courte qui réponde au besoin du client, puis testez le moment et la fréquence dans le respect du consentement et des règles de la plateforme, en surveillant désabonnements et réclamations.",
  "a7.b39": "Une relance de panier nécessite-t-elle une remise ?",
  "a7.b40": "Pas toujours. Une remise peut réduire la marge ; comparez-la à un rappel informatif et mesurez les commandes attribuables ainsi que la marge contributive avant de décider.",
  "a7.b41": "Un message de panier abandonné est-il Marketing ou Utilitaire ?",
  "a7.b42": "Pas automatiquement. La catégorie approuvée par Meta dépend du contenu du message et des règles actuelles. Un rappel promotionnel de panier peut relever de Marketing ; ne le classez pas Utilitaire au seul motif qu’un panier existe.",
  "a7.b43": "Consultez la disponibilité actuelle de Chatora",
  "a7.b44": "Chatora est un aperçu de produit sans canal WhatsApp connecté, déclencheur de panier en direct ni offre d’abonnement gratuite ou payante. La galerie publique contient des brouillons de départ modifiables, pas une automatisation de messagerie en direct.",
  "a7.cta": "Consulter la disponibilité →",
  "a7.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs WhatsApp de Meta</a>",
  "a7.b45": "Source : grille tarifaire WhatsApp de Meta en vigueur depuis le 1er octobre 2026. Les textes et calculs de coûts sont illustratifs ; aucune donnée de récupération de clients Chatora ni aucun indicateur de performance n’est utilisé.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a7.h1": "WhatsApp-Nachrichten bei abgebrochenen Warenkörben: Beispiele, Gebühren und Richtlinien",
  "a7.lede": "Es gibt keine allgemeingültige Warenkorb-Wiedergewinnungsrate oder Nachrichtenfolge, die Gewinn garantiert. Dieser Leitfaden zeigt beispielhafte Texte, erklärt den Einfluss von Metas Nachrichtenkategorien auf Gebühren und nennt Prüfungen zu Einwilligung und Zeitpunkt. Chatoras Vorschau hat keine Live-WhatsApp-Verbindung.",
  "a7.author": "Chatora-Rechercheteam",
  "a7.date": "Aktualisiert am 28. Oktober 2026 · 8 Min. Lesezeit",
  "a7.callout": "<b>Erst die Gebühren, nicht der ROI:</b> Nach Metas ägyptischen Tarifen vom Oktober 2026 würden drei zugestellte Nachrichten <strong>0,1932 USD</strong> kosten, wenn alle als Marketing klassifiziert werden, oder <strong>0,0108 USD</strong>, wenn jede Nachricht berechtigt als Utility gilt. Metas genehmigte Kategorie hängt von Inhalt und Regeln ab, nicht vom bevorzugten Preis des Absenders. Diese Werte enthalten weder Anbietergebühren, Steuern, Rabatte noch Betriebskosten und belegen keine Gewinnschwelle.",
  "a7.b1": "Inhalt",
  "a7.b2": "<a href=\"#why\">Warum Warenkörbe abgebrochen werden und was du ändern kannst</a>",
  "a7.b3": "<a href=\"#sequence\">Drei Nachrichten mit Textbeispielen</a>",
  "a7.b4": "<a href=\"#timing\">Zeitpunkt, Einwilligung und Häufigkeit</a>",
  "a7.b5": "<a href=\"#cost\">Meta-Gebührenszenarien und Annahmen</a>",
  "a7.b6": "<a href=\"#never\">Fünf Gründe für eine Sperre</a>",
  "a7.b7": "1. Warum Warenkörbe abgebrochen werden — und was du ändern kannst",
  "a7.b8": "Rückgewinnungsnachrichten helfen nur bei einer Art von Abbruch. Überlege vor dem Schreiben, welchen dieser Fälle du tatsächlich angehst:",
  "a7.b9": "<strong>Ablenkung.</strong> Ein Käufer möchte möglicherweise nach einer Unterbrechung zurückkehren; eine Erinnerung kann helfen, garantiert aber keine Rückgewinnung.",
  "a7.b10": "<strong>Preis oder Lieferkosten.</strong> Versand- oder Nachnahmegebühren können die Entscheidung beeinflussen. Ein Rabatt senkt die Marge; teste Angebote gegen eine Erinnerung ohne Rabatt.",
  "a7.b11": "<strong>Vertrauen.</strong> Fehlende Bewertungen, Rückgabebedingungen oder Unternehmensangaben können Zweifel auslösen. Eine Folgenachricht ersetzt keine klaren Informationen auf der Produktseite.",
  "a7.b12": "<strong>Fragen zur Lieferung.</strong> Kunden benötigen vielleicht korrekte Informationen zu Liefergebieten, Zeitplänen oder Zoll; antworte nur mit Angaben, die du überprüfen kannst.",
  "a7.b13": "Wenn du Kunden nach dem Grund für den abgebrochenen Checkout fragen kannst, sammle das Feedback mit geeigneter Einwilligung und vergleiche es mit deinen eigenen Bestelldaten. Ersetze die Daten deines Shops nicht durch einen allgemeinen Richtwert.",
  "a7.b14": "2. Drei Nachrichten mit Textbeispielen",
  "a7.b15": "Die folgenden drei Nachrichten sind illustrative Texte, keine genehmigten Vorlagen oder bewährte Sequenz. Eine Erinnerung an einen abgebrochenen Warenkorb kann als Marketing eingestuft werden; gehe nicht davon aus, dass sie als Utility gilt. Prüfe vor dem Versand Einwilligung, Vorlagengenehmigung und die geltende Meta-Kategorie.",
  "a7.b16": "<b>Beispielnachricht 1 · Zeitpunkt testen, sofern zulässig.</b> „أهلًا {first_name} 👋 سلة {{product}} لسه محفوظة عندك — تحب أكمّل الأوردر معاك؟ لو محتاج تغيّر المقاس أو العنوان، قولّي.“ Nur ein Textbeispiel; prüfe Einwilligung, Nachrichtenkategorie und Vorlagenanforderungen.",
  "a7.b17": "<b>Beispielnachricht 2 · optionale Logistik-Info.</b> Beantworte eine echte Frage mit überprüften Angaben zu Lieferzeiten, Nachnahme oder Rückgabebedingungen. Sende sie nur, wenn Einwilligung und aktuelle Kanalregeln es erlauben.",
  "a7.b18": "<b>Beispielnachricht 3 · optionale Abschlussnotiz.</b> Nenne eine Frist oder einen Lagerbestand nur, wenn die Angabe wahr und überprüfbar ist. Ein Anreiz muss zu deiner Marge und den geltenden Marketingregeln passen.",
  "a7.b19": "Prüfe vor dem Versand Einwilligung, genehmigte Vorlage und Kategorie sowie die Gebührenbehandlung in Metas aktueller Preisliste. Vermeide übertriebene Dringlichkeit und beobachte Zustellungen, Abmeldungen und Kundenfeedback.",
  "a7.b20": "3. Zeitpunkt, Einwilligung und Häufigkeit",
  "a7.b21": "Einen allgemeingültig besten Zeitabstand gibt es nicht. Teste den Zeitpunkt nur bei Kunden mit erforderlicher Einwilligung, beachte die Messaging-Zeitfenster der Plattform und vergleiche Zustellungen, Antworten, Abmeldungen und zugeordnete Bestellungen im eigenen Konto.",
  "a7.b22": "Vermeide überlappende Erinnerungen für dieselbe Bestellung; stoppe oder aktualisiere eine frühere Sequenz, wenn sich Warenkorb- oder Bestellstatus ändert.",
  "a7.b23": "Lege anhand von Kundeneinwilligung, lokalem Recht und aktuellen Plattformregeln eine vorsichtige Frequenzgrenze fest; eine Sequenz mit drei Nachrichten ist ein Beispiel, keine Meta-Vorgabe.",
  "a7.b24": "Wenn ein Kunde antwortet oder den Checkout abschließt, pausiere automatische Erinnerungen und leite Fragen bei Bedarf an eine Person weiter.",
  "a7.b25": "Berücksichtige die Ortszeit und Präferenzen des Empfängers. Beobachte Abmeldungen, Beschwerden und Kontowarnungen; keine Uhrzeit garantiert eine bestimmte Antwort.",
  "a7.b26": "4. Meta-Gebührenszenarien und Annahmen",
  "a7.b27": "Bei den ägyptischen Tarifen, gültig ab 1. Oktober 2026, kosten drei zugestellte Nachrichten <strong>0,1932 USD</strong> je Warenkorb, wenn alle als Marketing klassifiziert werden (je 0,0644 USD), oder <strong>0,0108 USD</strong>, wenn alle berechtigt als Utility gelten (je 0,0036 USD). Die genehmigte Kategorie hängt von Inhalt und Metas Regeln ab. Diese Beträge enthalten keine Anbietergebühren, Steuern, Rabatte, Arbeitszeit, Rücksendungen oder Kosten unverkaufter Ware.",
  "a7.b28": "Schätze die Rentabilität anhand eigener zurechenbarer zurückgewonnener Bestellungen und deiner Deckungsbeitragsmarge und ziehe alle relevanten Kosten ab. Vergleiche möglichst einen einheitlichen Zeitraum oder eine Kontrollgruppe; hier wird keine allgemeine Rückgewinnungsquote oder Gewinnwirkung behauptet.",
  "a7.b29": "5. Fünf Probleme, die du vermeiden solltest",
  "a7.b30": "Einen Rabatt anbieten, ohne Deckungsbeitrag, Berechtigung und den möglichen Nutzen einer Erinnerung ohne Rabatt zu prüfen.",
  "a7.b31": "Eine Abmeldung oder Bitte um Stopp ignorieren. Führe Sperrlisten und halte die aktuellen Kanalregeln ein.",
  "a7.b32": "Werbetexte als Utility kennzeichnen, um einen günstigeren Tarif zu erhalten. Metas genehmigte Kategorie und aktuelle Richtlinien bestimmen die Abrechnung.",
  "a7.b33": "Eine Warenkorberinnerung an ein breites Publikum senden, ohne Einwilligung, Relevanz und aktuelle Messaging-Berechtigung jedes Empfängers zu prüfen.",
  "a7.b34": "Eine Kundenfrage ungelöst lassen. Biete einen passenden Weg zu menschlicher Hilfe an und pausiere bei Bedarf automatische Erinnerungen.",
  "a7.b35": "Chatora hat weder eine Live-Verbindung zu WhatsApp oder Instagram noch Warenkorb-Trigger, Vorlagengenehmigung oder Versandablauf. Die Sequenz auf dieser Seite ist ein Textbeispiel; sie kann in der aktuellen Vorschau nicht veröffentlicht oder versendet werden.",
  "a7.b36": "Häufige Fragen, kurz beantwortet",
  "a7.b37": "Wie viele Nachrichten sollte ein Ablauf für abgebrochene Warenkörbe enthalten?",
  "a7.b38": "Eine allgemeingültige ideale Zahl gibt es nicht. Beginne mit der kürzesten Sequenz, die den Kundenbedarf erfüllt, und teste dann Zeitpunkt und Häufigkeit im Rahmen der Einwilligung und Plattformregeln; beobachte Abmeldungen und Beschwerden.",
  "a7.b39": "Braucht ein Warenkorb-Ablauf einen Rabatt?",
  "a7.b40": "Nicht immer. Ein Rabatt kann die Marge senken; vergleiche ihn mit einer informativen Erinnerung und miss zurechenbare Bestellungen sowie Deckungsbeitrag, bevor du entscheidest.",
  "a7.b41": "Ist eine Warenkorberinnerung Marketing oder Utility?",
  "a7.b42": "Nicht automatisch. Metas genehmigte Kategorie hängt vom Nachrichteninhalt und den aktuellen Regeln ab. Eine werbliche Warenkorberinnerung kann Marketing sein; kennzeichne sie nicht allein deshalb als Utility, weil ein Warenkorb vorhanden ist.",
  "a7.b43": "Chatoras aktuelle Verfügbarkeit prüfen",
  "a7.b44": "Chatora ist eine Produktvorschau ohne verbundenen WhatsApp-Kanal, Live-Warenkorb-Trigger oder kostenlosen beziehungsweise kostenpflichtigen Tarif. Die öffentliche Vorlagengalerie enthält bearbeitbare Startentwürfe, keine Live-Messaging-Automatisierung.",
  "a7.cta": "Verfügbarkeit prüfen →",
  "a7.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Meta-Preise für WhatsApp</a>",
  "a7.b45": "Quelle: Metas WhatsApp-Preisliste, gültig ab 1. Oktober 2026. Texte und Kostenrechnungen sind illustrativ; Chatora-Kundendaten zur Warenkorbrückgewinnung oder Leistungsbenchmarks werden nicht verwendet.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a7.h1": "Mensagens de WhatsApp para carrinhos abandonados: exemplos, cenários de tarifas e regras",
  "a7.lede": "Não existe uma taxa universal de recuperação de carrinhos nem uma sequência de mensagens que garanta lucro. Este guia apresenta textos ilustrativos, explica como as categorias de mensagens da Meta afetam as tarifas e o que verificar sobre consentimento e horário. A prévia da Chatora não tem conexão ativa com o WhatsApp.",
  "a7.author": "Equipe de pesquisa da Chatora",
  "a7.date": "Atualizado em 28 de outubro de 2026 · 8 min de leitura",
  "a7.callout": "<b>Tarifas primeiro, não ROI:</b> pelas tarifas da Meta no Egito em outubro de 2026, três mensagens entregues custariam <strong>US$ 0,1932</strong> se todas fossem classificadas como Marketing, ou <strong>US$ 0,0108</strong> se cada uma se qualificasse legitimamente como Utilidade. A categoria aprovada pela Meta depende do conteúdo e das regras, não do preço preferido por quem envia. Esses valores excluem tarifas do fornecedor, impostos, descontos e custos operacionais; não definem um ponto de equilíbrio.",
  "a7.b1": "Conteúdo",
  "a7.b2": "<a href=\"#why\">Por que os carrinhos são abandonados e o que você pode corrigir</a>",
  "a7.b3": "<a href=\"#sequence\">As três mensagens, com exemplos de texto</a>",
  "a7.b4": "<a href=\"#timing\">Horário, consentimento e frequência</a>",
  "a7.b5": "<a href=\"#cost\">Cenários de tarifas da Meta e premissas</a>",
  "a7.b6": "<a href=\"#never\">Cinco motivos que podem levar ao bloqueio</a>",
  "a7.b7": "1. Por que os carrinhos são abandonados — e o que você pode corrigir",
  "a7.b8": "Mensagens de recuperação só ajudam em um tipo de abandono. Antes de escrever qualquer coisa, decida qual destes casos você está tentando resolver:",
  "a7.b9": "<strong>Distração.</strong> A pessoa pode pretender voltar depois de ser interrompida; um lembrete pode ajudar, mas não garante a recuperação.",
  "a7.b10": "<strong>Preço ou custo de entrega.</strong> Frete ou taxas de pagamento na entrega podem influenciar a decisão. Um desconto reduz a margem; teste qualquer oferta contra uma mensagem sem desconto.",
  "a7.b11": "<strong>Confiança.</strong> A falta de avaliações, condições de devolução ou dados da empresa pode gerar dúvidas. Uma mensagem de acompanhamento não substitui informações claras na página do produto.",
  "a7.b12": "<strong>Dúvidas sobre a entrega.</strong> Clientes podem precisar de informações corretas sobre áreas e prazos de entrega ou alfândega; responda somente com dados que você possa verificar.",
  "a7.b13": "Se puder perguntar aos clientes por que saíram do checkout, colete o feedback com o consentimento adequado e compare-o com seus próprios dados de pedidos. Não substitua as evidências da sua loja por uma referência genérica.",
  "a7.b14": "2. As três mensagens, com exemplos de texto",
  "a7.b15": "As três mensagens abaixo são textos ilustrativos, não modelos aprovados nem uma sequência comprovada. Um lembrete de carrinho abandonado pode ser classificado como Marketing; não presuma que se qualifica como Utilidade. Confirme consentimento, aprovação do modelo e a categoria aplicável da Meta antes do envio.",
  "a7.b16": "<b>Mensagem de exemplo 1 · horário a testar, se permitido.</b> “أهلًا {first_name} 👋 سلة {{product}} لسه محفوظة عندك — تحب أكمّل الأوردر معاك؟ لو محتاج تغيّر المقاس أو العنوان، قولّي.” Texto apenas ilustrativo; confirme consentimento, categoria da mensagem e exigências do modelo.",
  "a7.b17": "<b>Mensagem de exemplo 2 · atualização logística opcional.</b> Responda a uma pergunta real com informações verificadas sobre prazo de entrega, disponibilidade de pagamento na entrega ou condições de devolução. Envie somente se o consentimento e as regras atuais do canal permitirem.",
  "a7.b18": "<b>Mensagem de exemplo 3 · nota final opcional.</b> Use um prazo ou informação de estoque apenas quando for verdadeiro e verificável. Qualquer incentivo deve respeitar sua margem e as regras de marketing aplicáveis.",
  "a7.b19": "Antes do envio, confirme o consentimento, o modelo e a categoria aprovados e o tratamento das tarifas na tabela atual da Meta. Evite urgência exagerada e monitore entregas, descadastros e feedback dos clientes.",
  "a7.b20": "3. Horário, consentimento e frequência",
  "a7.b21": "Não existe um intervalo ideal universal. Teste horários somente com clientes que deram o consentimento necessário, respeite as janelas de mensagens da plataforma e compare entregas, respostas, descadastros e pedidos atribuíveis na sua própria conta.",
  "a7.b22": "Evite lembretes sobrepostos para o mesmo pedido; interrompa ou atualize uma sequência anterior quando o status do carrinho ou do pedido mudar.",
  "a7.b23": "Defina um limite de frequência conservador com base no consentimento do cliente, na legislação local e nas regras atuais da plataforma; uma sequência de três mensagens é um exemplo, não uma exigência da Meta.",
  "a7.b24": "Se o cliente responder ou concluir o checkout, pause os lembretes automáticos e encaminhe dúvidas para uma pessoa quando necessário.",
  "a7.b25": "Considere o horário local e as preferências do destinatário. Monitore descadastros, reclamações e alertas da conta; nenhum horário garante determinada resposta.",
  "a7.b26": "4. Cenários de tarifas da Meta e premissas",
  "a7.b27": "Pelas tarifas do Egito vigentes desde 1º de outubro de 2026, três mensagens entregues custam <strong>US$ 0,1932</strong> por carrinho se as três forem classificadas como Marketing (US$ 0,0644 cada), ou <strong>US$ 0,0108</strong> se todas se qualificarem legitimamente como Utilidade (US$ 0,0036 cada). A categoria aprovada depende do conteúdo e das regras da Meta. Esses valores excluem tarifas do fornecedor, impostos, descontos, mão de obra, devoluções e o custo de estoque não vendido.",
  "a7.b28": "Para estimar a lucratividade, use seus próprios pedidos recuperados atribuíveis e a margem de contribuição e subtraia todos os custos relevantes. Quando possível, compare um período consistente ou um grupo de controle; este guia não afirma uma taxa geral de recuperação nem um resultado de lucro.",
  "a7.b29": "5. Cinco problemas a evitar",
  "a7.b30": "Oferecer desconto sem verificar margem de contribuição, elegibilidade e se um lembrete sem desconto também atenderia o cliente.",
  "a7.b31": "Ignorar um descadastro ou pedido para parar. Mantenha registros de supressão e siga as regras atuais do canal.",
  "a7.b32": "Classificar conteúdo promocional como Utilidade para tentar obter uma tarifa menor. A categoria aprovada pela Meta e a política atual determinam o tratamento aplicável.",
  "a7.b33": "Enviar um lembrete de carrinho para um público amplo sem verificar consentimento, relevância e elegibilidade atual de cada destinatário.",
  "a7.b34": "Deixar uma dúvida do cliente sem resposta. Ofereça um caminho adequado para atendimento humano e pause os lembretes automáticos quando necessário.",
  "a7.b35": "A Chatora não tem conexão ativa com WhatsApp ou Instagram, gatilho de carrinho, aprovação de modelos nem fluxo de envio. A sequência desta página é um exemplo de texto; não pode ser publicada nem enviada pela prévia atual.",
  "a7.b36": "Perguntas frequentes, em resumo",
  "a7.b37": "Quantas mensagens um fluxo de carrinho abandonado deve ter?",
  "a7.b38": "Não existe uma quantidade ideal universal. Comece com a menor sequência que atenda à necessidade do cliente e depois teste horário e frequência dentro das regras de consentimento e da plataforma, monitorando descadastros e reclamações.",
  "a7.b39": "Um fluxo de carrinho precisa de desconto?",
  "a7.b40": "Nem sempre. Um desconto pode reduzir a margem; compare-o com um lembrete informativo e meça pedidos atribuíveis e margem de contribuição antes de decidir.",
  "a7.b41": "Uma mensagem de carrinho abandonado é Marketing ou Utilidade?",
  "a7.b42": "Não automaticamente. A categoria aprovada pela Meta depende do conteúdo da mensagem e das regras atuais. Um lembrete promocional de carrinho pode ser Marketing; não o classifique como Utilidade só porque existe um carrinho.",
  "a7.b43": "Consulte a disponibilidade atual da Chatora",
  "a7.b44": "A Chatora é uma prévia do produto sem canal do WhatsApp conectado, gatilho de carrinho ao vivo ou plano de assinatura gratuito ou pago. A galeria pública de modelos contém rascunhos iniciais editáveis, não automação de mensagens ativa.",
  "a7.cta": "Consultar disponibilidade →",
  "a7.sources": "<a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do WhatsApp da Meta</a>",
  "a7.b45": "Fonte: tabela de tarifas do WhatsApp da Meta vigente desde 1º de outubro de 2026. Os textos e cálculos de custo são ilustrativos; não são usados dados de recuperação de clientes da Chatora nem referências de desempenho.",
});


/* Article a8 translations: ManyChat vs. Chatfuel. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a8.h1": "ManyChat vs. Chatfuel en 2026: precios de los planes, facturación de cartera y qué comprobar",
  "a8.lede": "ManyChat usa planes por niveles de contactos; Chatfuel combina una suscripción con créditos mensuales y consumo de saldo. Esta comparación fechada separa las cifras públicas de las tarifas por mensajes y del uso, que dependen de cada cuenta. Chatora se incluye únicamente para indicar el estado de su vista previa, no como competidor con un precio activo.",
  "a8.author": "Equipo de investigación de Chatora",
  "a8.date": "Actualizado el 28 de octubre de 2026 · 9 min de lectura",
  "a8.callout": "<b>Respuesta breve:</b> los precios de suscripción por sí solos no permiten obtener un total fiable con todos los cargos. ManyChat publica niveles por número de contactos; Chatfuel publica precios de suscripción y créditos, mientras que el consumo de saldo y las tarifas de WhatsApp dependen del uso real. Chatora no tiene precios publicados ni canales activos, por lo que no hay un total comparable de Chatora.",
  "a8.b1": "Contenido",
  "a8.b2": "<a href=\"#models\">Tres modelos de facturación publicados</a>",
  "a8.b3": "<a href=\"#worked\">Un ejemplo fechado, sin inventar totales</a>",
  "a8.b4": "<a href=\"#wins\">Para qué podría convenir cada plataforma</a>",
  "a8.b5": "<a href=\"#switch\">Preguntas antes de cambiar</a>",
  "a8.b6": "<a href=\"#verdict\">Conclusiones según el caso de uso</a>",
  "a8.b7": "1. Tres modelos de facturación publicados",
  "a8.b8": "Las páginas de planes muestran unidades de facturación distintas; eso no demuestra que las herramientas incluyan las mismas funciones ni generen la misma factura final:",
  "a8.b9": "<strong>ManyChat — niveles por contactos.</strong> Su página en USD, consultada el 28 de octubre, indica Free con 25 contactos, Essential con 250, Pro con 2.500, Business con 7.500 y Advanced con 25.000. Los equivalentes mensuales con facturación anual son 14 $, 29 $, 69 $ y 139 $ para los planes de pago.",
  "a8.b10": "<strong>Chatfuel — suscripción, créditos y consumo de saldo.</strong> Business figura a 20 $ mes a mes o a un equivalente de 18 $ al mes con facturación anual, e incluye 20 $ en créditos mensuales. Agency S figura a 100 $ al mes o a un equivalente de 90 $ al mes con facturación anual, e incluye 100 $ en créditos y tres empresas cliente. Comprueba cómo se aplica el saldo a tu uso.",
  "a8.b11": "<strong>Chatora — vista previa del producto.</strong> No hay un precio de suscripción publicado, un canal de mensajería conectado ni respuestas de IA en directo. Hoy no se le puede asignar un plan o coste por mensaje comparable.",
  "a8.b12": "Para estimar el coste mensual total, separa la suscripción, los créditos de uso, los mensajes de WhatsApp entregados, los impuestos y las posibles tarifas específicas del proveedor. No des por hecho que una tarifa se repercute al coste ni que se aplica un recargo sin consultar las condiciones de facturación vigentes del proveedor.",
  "a8.b13": "2. Un ejemplo fechado, sin inventar totales",
  "a8.b14": "Supongamos que una tienda egipcia tiene 5.000 contactos y prevé enviar 2.000 mensajes de marketing por WhatsApp a números egipcios. Las instantáneas públicas de los planes ayudan a identificar las franquicias de suscripción; la tarifa actual en USD de Meta ofrece una referencia separada para los mensajes. La factura del proveedor puede diferir, por lo que las cifras siguientes no representan un total mensual con todos los cargos.",
  "a8.tl1": "Concepto",
  "a8.tl2": "Cifra publicada",
  "a8.tl3": "Qué indica —y qué no—",
  "a8.t1": "Plan de ManyChat para 5.000 contactos",
  "a8.t1a": "Business: 69 $/mes equivalente con facturación anual; 7.500 contactos",
  "a8.t1b": "Instantánea de la suscripción; comprueba el precio regional, las funciones y los impuestos",
  "a8.t2": "Chatfuel Business",
  "a8.t2a": "20 $ al mes o 18 $/mes equivalente con facturación anual; 20 $ en créditos mensuales",
  "a8.t2b": "Las deducciones de la cartera y el consumo total requieren detalles de facturación de la cuenta",
  "a8.t3": "Tarifa de Meta para 2.000 mensajes de marketing entregados en Egipto",
  "a8.t3a": "128,80 $ según la tarifa de lista de Meta de 0,0644 $ USD",
  "a8.t3b": "Solo cálculo según la tarifa de lista de Meta; excluye plataforma, proveedor, impuestos y otras tarifas",
  "a8.t4": "Cifra de la guía de WhatsApp de ManyChat",
  "a8.t4a": "0,0740 $ por mensaje de marketing a Egipto en su guía del 7 de octubre",
  "a8.t4b": "Cifra publicada por ManyChat; no equivale a la tarifa de Meta",
  "a8.t5": "Coste total de Chatora",
  "a8.t5a": "No publicado",
  "a8.t5b": "No hay precio de suscripción ni integración de mensajería en directo que comparar",
  "a8.foot": "Páginas de los proveedores consultadas el 28 de octubre de 2026; la tarifa de lista de Meta en USD entra en vigor el 1 de octubre de 2026. Los equivalentes mensuales indicados usan facturación anual cuando se señala. Los precios regionales, impuestos, condiciones de saldo y uso pueden variar; esta tabla no estima un total mensual final.",
  "a8.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentación de facturación de Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifa de Meta</a>",
  "a8.b15": "La tarifa de Meta indica para Egipto 0,0644 $ por mensaje de marketing y 0,0036 $ para mensajes de utilidad, autenticación y servicio. La guía de ManyChat publica una cifra de marketing distinta para Egipto. Pregunta a cada proveedor qué tarifa y cargos se aplican a tu cuenta y compara la factura con la tarifa publicada por Meta; la diferencia por sí sola no explica su causa.",
  "a8.b16": "3. Para qué podría convenir cada plataforma",
  "a8.b17": "Una comparación útil reconoce las fortalezas y limitaciones propias de cada producto:",
  "a8.b18": "<strong>ManyChat — ecosistema consolidado.</strong> Cuenta con un creador maduro, recursos comunitarios y un programa público de partners. Comprueba si sus funciones actuales de canales, IA y soporte encajan con tu plan.",
  "a8.b19": "<strong>Chatfuel — opciones de saldo y agencia.</strong> Sus páginas públicas indican disponibilidad de proveedores de WhatsApp, contactos ilimitados en la documentación de ayuda y una opción Agency S. Conviene revisar el saldo y el consumo real.",
  "a8.b20": "<strong>Chatora — vista previa del producto.</strong> Ofrece textos de interfaz en árabe e inglés, borradores iniciales editables y herramientas CSV. No es una alternativa de mensajería en directo y no tiene un precio de suscripción publicado.",
  "a8.b21": "4. Preguntas antes de cambiar",
  "a8.b22": "<strong>¿Qué datos puedes exportar?</strong> Guarda los registros de contactos, las definiciones de flujos y las plantillas de mensajes antes de cambiar de proveedor; comprueba las herramientas de exportación de cada plataforma.",
  "a8.b23": "<strong>¿Qué permisos de canal se necesitan?</strong> Comprueba el acceso oficial a la API, la titularidad de la cuenta y los requisitos de aprobación antes de conectar una cuenta de producción.",
  "a8.b24": "<strong>¿Qué funciones ganará o perderá tu equipo?</strong> Compara las bibliotecas de plantillas, los flujos de agencia, las integraciones, el soporte lingüístico y los compromisos de asistencia.",
  "a8.b25": "<strong>¿Cuál es el precio real por mensaje?</strong> Pregunta por la tarifa aplicable a la categoría y al mercado y solicita una factura de ejemplo; la tarifa de Meta y el desglose de facturación del proveedor pueden diferir.",
  "a8.b26": "5. Conclusiones según el caso de uso",
  "a8.b27": "<strong>Necesitas mensajería social activa ahora:</strong> evalúa proveedores con canales oficialmente compatibles y disponibles en este momento, y confirma los límites del plan.",
  "a8.b28": "<strong>Necesitas almacenar muchos contactos o un modelo de saldo:</strong> compara el plan publicado de Chatfuel, los créditos y el consumo de tu cuenta con la combinación de mensajes prevista.",
  "a8.b29": "<strong>Necesitas un ecosistema de plantillas consolidado:</strong> ManyChat podría convenirte; comprueba la oferta local y el nivel de funciones actuales.",
  "a8.b30": "<strong>Estás considerando Chatora:</strong> la vista previa actual no es un software de mensajería para producción. Consulta la página de disponibilidad; no se publica un precio ni una comparación de ahorro.",
  "a8.b31": "Antes de comprar, anota el número de contactos, la lista de canales, las categorías de mensajes previstas, el uso de IA y el país de facturación. Pide a cada proveedor las condiciones por escrito y compara el mismo periodo y conjunto de funciones.",
  "a8.b32": "Preguntas frecuentes, en breve",
  "a8.b33": "¿Chatfuel es más barato que ManyChat?",
  "a8.b34": "Los precios públicos de suscripción difieren, pero el total depende de los límites de contactos, el acceso a funciones, los créditos mensuales, las deducciones de saldo, los cargos por mensajes de Meta, los impuestos y el periodo de facturación. Comparar solo la suscripción no da una respuesta con todos los costes.",
  "a8.b35": "¿Puedo comparar el precio de Chatora con el de ellos?",
  "a8.b36": "No. Chatora no tiene un precio de suscripción publicado ni un canal de mensajería en directo, así que no hay un plan equivalente ni un total por uso que comparar.",
  "a8.b37": "¿Los contactos se transfieren automáticamente si cambio de proveedor?",
  "a8.b38": "No lo des por hecho. Exporta y guarda los registros disponibles de tu proveedor actual y comprueba la titularidad y las reglas de transferencia del canal antes de desconectarlo.",
  "a8.b39": "¿Dónde puedo consultar la disponibilidad actual de Chatora?",
  "a8.b40": "La página de precios indica qué está habilitado y qué no en la vista previa actual. No publica un plan de pago ni promete mensajería por canales en directo.",
  "a8.b41": "Consulta las condiciones publicadas, no un total supuesto",
  "a8.b42": "Revisa los precios y reglas de uso actuales de cada proveedor. La página de Chatora muestra el estado de la vista previa; todavía no puede calcular una comparación con todos los cargos.",
  "a8.b43": "Consultar la disponibilidad de Chatora →",
  "a8.b44": "Fuentes: páginas de precios y facturación de ManyChat y Chatfuel consultadas el 28 de octubre de 2026; tarifa de lista de WhatsApp de Meta en USD vigente desde el 1 de octubre de 2026. Los precios, las condiciones de saldo y la facturación regional pueden cambiar. Chatora no está afiliada a ManyChat ni a Chatfuel.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a8.h1": "ManyChat ou Chatfuel en 2026 : prix des forfaits, facturation par portefeuille et points à vérifier",
  "a8.lede": "ManyChat propose des forfaits par paliers de contacts ; Chatfuel combine un abonnement, des crédits mensuels et une consommation sur portefeuille. Cette comparaison datée distingue ces chiffres publics des frais de messages et de l’usage, qui dépendent de chaque compte. Chatora est mentionné uniquement pour préciser l’état de son aperçu produit, pas comme concurrent avec un tarif actif.",
  "a8.author": "Équipe de recherche de Chatora",
  "a8.date": "Mis à jour le 28 octobre 2026 · 9 min de lecture",
  "a8.callout": "<b>En bref :</b> les seuls prix d’abonnement ne permettent pas d’établir un total fiable tout compris. ManyChat publie des paliers selon le nombre de contacts ; Chatfuel publie des prix d’abonnement et des crédits, tandis que la consommation du portefeuille et les frais WhatsApp dépendent de l’usage réel. Chatora n’a pas de prix publié ni de canaux en direct : aucun total Chatora comparable n’est donc disponible.",
  "a8.b1": "Sommaire",
  "a8.b2": "<a href=\"#models\">Trois modèles de facturation publiés</a>",
  "a8.b3": "<a href=\"#worked\">Un exemple daté, sans total inventé</a>",
  "a8.b4": "<a href=\"#wins\">À quels usages chaque plateforme peut convenir</a>",
  "a8.b5": "<a href=\"#switch\">Questions à se poser avant de changer</a>",
  "a8.b6": "<a href=\"#verdict\">Conclusion selon le cas d’usage</a>",
  "a8.b7": "1. Trois modèles de facturation publiés",
  "a8.b8": "Les pages des forfaits affichent des unités de facturation différentes ; cela ne prouve pas que les outils incluent les mêmes fonctionnalités ni aboutissent à la même facture finale :",
  "a8.b9": "<strong>ManyChat — paliers de contacts.</strong> Sa page en USD, consultée le 28 octobre, indique Free à 25 contacts, Essential à 250, Pro à 2 500, Business à 7 500 et Advanced à 25 000. Les équivalents mensuels avec facturation annuelle sont de 14 $, 29 $, 69 $ et 139 $ pour les offres payantes.",
  "a8.b10": "<strong>Chatfuel — abonnement, crédits et consommation sur portefeuille.</strong> Business est affiché à 20 $ au mois ou à l’équivalent de 18 $/mois avec facturation annuelle, avec 20 $ de crédits mensuels. Agency S est affiché à 100 $ au mois ou à l’équivalent de 90 $/mois avec facturation annuelle, avec 100 $ de crédits et trois entreprises clientes. Vérifiez comment le solde du portefeuille s’applique à votre usage.",
  "a8.b11": "<strong>Chatora — aperçu produit.</strong> Aucun prix d’abonnement n’est publié ; aucun canal de messagerie n’est connecté et aucune réponse IA n’est active. Il est donc impossible de lui attribuer aujourd’hui un forfait ou un coût par message comparable.",
  "a8.b12": "Pour estimer un coût mensuel tout compris, distinguez l’abonnement, les crédits d’utilisation, les messages WhatsApp livrés, les taxes et les éventuels frais propres au fournisseur. Ne supposez pas qu’un frais est refacturé à l’identique ou qu’une majoration s’applique sans consulter les conditions de facturation actuelles du fournisseur.",
  "a8.b13": "2. Un exemple daté, sans total inventé",
  "a8.b14": "Supposons qu’une boutique égyptienne ait 5 000 contacts et prévoie d’envoyer 2 000 messages marketing WhatsApp à des numéros égyptiens. Les aperçus publics des forfaits permettent de repérer les seuils d’abonnement ; la grille tarifaire USD actuelle de Meta fournit une base distincte pour les frais de messages. La facture du fournisseur peut différer : les chiffres ci-dessous ne constituent donc pas un total mensuel tout compris.",
  "a8.tl1": "Élément",
  "a8.tl2": "Chiffre publié",
  "a8.tl3": "Ce que cela indique — et n’indique pas",
  "a8.t1": "Forfait ManyChat pour 5 000 contacts",
  "a8.t1a": "Business : équivalent à 69 $/mois avec facturation annuelle ; 7 500 contacts",
  "a8.t1b": "Aperçu de l’abonnement ; vérifiez le prix régional, les fonctionnalités et les taxes",
  "a8.t2": "Chatfuel Business",
  "a8.t2a": "20 $ au mois ou équivalent à 18 $/mois avec facturation annuelle ; 20 $ de crédits mensuels",
  "a8.t2b": "Les déductions du portefeuille et la consommation totale nécessitent les détails de facturation du compte",
  "a8.t3": "Frais Meta pour 2 000 messages marketing livrés en Égypte",
  "a8.t3a": "128,80 $ selon le tarif catalogue Meta de 0,0644 $ USD",
  "a8.t3b": "Calcul au seul tarif catalogue Meta ; hors frais de plateforme, de fournisseur, taxes et autres frais",
  "a8.t4": "Chiffre du guide WhatsApp de ManyChat",
  "a8.t4a": "0,0740 $ par message marketing vers l’Égypte dans son guide du 7 octobre",
  "a8.t4b": "Chiffre publié par ManyChat ; il n’est pas interchangeable avec le tarif Meta",
  "a8.t5": "Total Chatora",
  "a8.t5a": "Non publié",
  "a8.t5b": "Aucun prix d’abonnement ni aucune intégration de messagerie en direct à comparer",
  "a8.foot": "Pages des fournisseurs consultées le 28 octobre 2026 ; le tarif catalogue USD de Meta entre en vigueur le 1er octobre 2026. Les équivalents mensuels indiqués correspondent à une facturation annuelle lorsqu’elle est précisée. Les prix régionaux, les taxes, les modalités du portefeuille et l’usage peuvent varier ; ce tableau n’estime pas le total mensuel final.",
  "a8.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentation de facturation Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Grille tarifaire Meta</a>",
  "a8.b15": "La grille de Meta indique pour l’Égypte 0,0644 $ par message marketing et 0,0036 $ pour les messages Utilitaire, Authentification et Service. Le guide de ManyChat indique un autre tarif marketing pour l’Égypte. Demandez à chaque fournisseur quels tarifs et frais s’appliquent à votre compte et comparez la facture à la grille publiée par Meta ; l’écart seul n’en établit pas la cause.",
  "a8.b16": "3. À quels usages chaque plateforme peut convenir",
  "a8.b17": "Une comparaison utile présente les points forts et les limites propres à chaque produit :",
  "a8.b18": "<strong>ManyChat — écosystème établi.</strong> Il dispose d’un outil de création mature, de ressources communautaires et d’un programme partenaire public. Vérifiez si les fonctionnalités actuelles de canaux, d’IA et d’assistance correspondent à votre forfait.",
  "a8.b19": "<strong>Chatfuel — portefeuille et options agence.</strong> Ses pages publiques indiquent le statut des fournisseurs WhatsApp, un nombre illimité de contacts dans sa documentation d’aide et une option Agency S. Le portefeuille et l’usage réel restent à examiner.",
  "a8.b20": "<strong>Chatora — aperçu produit.</strong> Il propose une interface en arabe et en anglais, des brouillons de départ modifiables et des outils CSV. Ce n’est pas une solution de messagerie en direct et aucun prix d’abonnement n’est publié.",
  "a8.b21": "4. Questions à se poser avant de changer",
  "a8.b22": "<strong>Quelles données pouvez-vous exporter ?</strong> Enregistrez les fiches de contacts, les définitions de parcours et les modèles de messages avant de changer de fournisseur ; vérifiez les outils d’export de chaque plateforme.",
  "a8.b23": "<strong>Quelles autorisations de canal sont requises ?</strong> Vérifiez l’accès officiel à l’API, la propriété du compte et les exigences d’approbation avant de connecter un compte de production.",
  "a8.b24": "<strong>Quelles fonctionnalités votre équipe perdra-t-elle ou gagnera-t-elle ?</strong> Comparez les bibliothèques de modèles, les processus agence, les intégrations, la prise en charge des langues et les engagements d’assistance.",
  "a8.b25": "<strong>Quel est le véritable prix par message ?</strong> Demandez le tarif applicable à la catégorie et au marché ainsi qu’un exemple de facture ; la grille de Meta et le détail de facturation du fournisseur peuvent différer.",
  "a8.b26": "5. Conclusion selon le cas d’usage",
  "a8.b27": "<strong>Vous avez besoin de messagerie sociale en direct dès maintenant :</strong> évaluez les fournisseurs disposant actuellement de canaux officiellement pris en charge et confirmez les limites du forfait.",
  "a8.b28": "<strong>Vous avez besoin d’un grand répertoire de contacts ou d’un modèle par portefeuille :</strong> comparez le forfait publié de Chatfuel, ses crédits et l’usage au niveau du compte à la répartition de messages prévue.",
  "a8.b29": "<strong>Vous recherchez un écosystème de modèles mature :</strong> ManyChat peut convenir ; vérifiez l’offre locale actuelle et le niveau de fonctionnalités.",
  "a8.b30": "<strong>Vous envisagez Chatora :</strong> l’aperçu actuel n’est pas un logiciel de messagerie destiné à la production. Consultez la page de disponibilité ; aucun prix ni aucune comparaison d’économies ne sont publiés.",
  "a8.b31": "Avant d’acheter, notez le nombre de contacts, les canaux, les catégories de messages prévues, l’usage de l’IA et le pays de facturation. Demandez à chaque fournisseur ses conditions écrites et comparez la même période et le même ensemble de fonctionnalités.",
  "a8.b32": "Questions fréquentes, en bref",
  "a8.b33": "Chatfuel est-il moins cher que ManyChat ?",
  "a8.b34": "Les prix d’abonnement publics diffèrent, mais le total dépend des limites de contacts, de l’accès aux fonctionnalités, des crédits mensuels, des déductions du portefeuille, des frais de messages Meta, des taxes et de la période de facturation. Une comparaison des seuls abonnements ne donne pas le coût tout compris.",
  "a8.b35": "Puis-je comparer le prix de Chatora au leur ?",
  "a8.b36": "Non. Chatora n’a ni prix d’abonnement publié ni canal de messagerie en direct ; il n’existe donc ni forfait équivalent ni total d’utilisation à comparer.",
  "a8.b37": "Les contacts sont-ils transférés automatiquement lorsque je change ?",
  "a8.b38": "Ne le présumez pas. Exportez et sauvegardez les données disponibles auprès de votre fournisseur actuel, puis vérifiez les règles de propriété et de transfert du canal avant de le déconnecter.",
  "a8.b39": "Où consulter la disponibilité actuelle de Chatora ?",
  "a8.b40": "La page des tarifs précise ce qui est activé ou non dans l’aperçu actuel. Elle ne publie pas d’offre payante et ne promet pas de messagerie sur des canaux en direct.",
  "a8.b41": "Consultez les conditions publiées, pas un total supposé",
  "a8.b42": "Vérifiez les prix et règles d’usage actuels de chaque fournisseur. La page Chatora décrit l’état de l’aperçu ; elle ne peut pas encore calculer une comparaison tout compris.",
  "a8.b43": "Consulter la disponibilité de Chatora →",
  "a8.b44": "Sources : pages de tarifs et de facturation de ManyChat et Chatfuel consultées le 28 octobre 2026 ; grille tarifaire USD WhatsApp de Meta en vigueur depuis le 1er octobre 2026. Les prix, modalités du portefeuille et tarifs régionaux peuvent évoluer. Chatora n’est affilié ni à ManyChat ni à Chatfuel.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a8.h1": "ManyChat vs. Chatfuel 2026: Tarifpläne, Wallet-Abrechnung und was du prüfen solltest",
  "a8.lede": "ManyChat nutzt Kontaktstufen für seine Tarife; Chatfuel kombiniert ein Abonnement mit monatlichen Guthaben und Wallet-Verbrauch. Dieser datierte Vergleich trennt die veröffentlichten Zahlen von Nachrichtenentgelten und Nutzung, die vom jeweiligen Konto abhängen. Chatora wird nur mit dem Status seiner Produktvorschau aufgeführt, nicht als aktiv bepreister Wettbewerber.",
  "a8.author": "Chatora-Rechercheteam",
  "a8.date": "Aktualisiert am 28. Oktober 2026 · 9 Min. Lesezeit",
  "a8.callout": "<b>Kurz gesagt:</b> Aus den Abonnementpreisen allein ergibt sich keine verlässliche Gesamtsumme. ManyChat veröffentlicht Kontaktstufen; Chatfuel veröffentlicht Abonnementpreise und Guthaben, während Wallet-Verbrauch und WhatsApp-Gebühren von der tatsächlichen Nutzung abhängen. Chatora hat weder veröffentlichte Preise noch Live-Kanäle; daher gibt es keine vergleichbare Chatora-Gesamtsumme.",
  "a8.b1": "Inhalt",
  "a8.b2": "<a href=\"#models\">Drei veröffentlichte Abrechnungsmodelle</a>",
  "a8.b3": "<a href=\"#worked\">Ein datiertes Beispiel ohne erfundene Gesamtsummen</a>",
  "a8.b4": "<a href=\"#wins\">Wofür die einzelnen Plattformen geeignet sein könnten</a>",
  "a8.b5": "<a href=\"#switch\">Fragen vor einem Wechsel</a>",
  "a8.b6": "<a href=\"#verdict\">Fazit nach Anwendungsfall</a>",
  "a8.b7": "1. Drei veröffentlichte Abrechnungsmodelle",
  "a8.b8": "Die Tarifseiten zeigen unterschiedliche Abrechnungseinheiten; daraus folgt nicht, dass die Tools dieselben Funktionen enthalten oder dieselbe Endabrechnung ergeben:",
  "a8.b9": "<strong>ManyChat — Kontaktstufen.</strong> Die USD-Seite, geprüft am 28. Oktober, nennt Free mit 25 Kontakten, Essential mit 250, Pro mit 2.500, Business mit 7.500 und Advanced mit 25.000. Die monatlichen Äquivalente bei jährlicher Abrechnung betragen für die kostenpflichtigen Tarife 14 $, 29 $, 69 $ und 139 $.",
  "a8.b10": "<strong>Chatfuel — Abonnement plus Guthaben und Wallet-Verbrauch.</strong> Business wird mit 20 $ bei monatlicher Zahlung oder umgerechnet 18 $/Monat bei jährlicher Abrechnung aufgeführt und enthält 20 $ monatliches Guthaben. Agency S wird mit 100 $ monatlich oder umgerechnet 90 $/Monat bei jährlicher Abrechnung aufgeführt und enthält 100 $ Guthaben sowie drei Kundenunternehmen. Prüfe, wie das Wallet für deine Nutzung belastet wird.",
  "a8.b11": "<strong>Chatora — Produktvorschau.</strong> Es gibt keinen veröffentlichten Abonnementpreis, keinen verbundenen Messaging-Kanal und keine Live-KI-Antwort. Daher lässt sich Chatora heute weder ein vergleichbarer Tarif noch ein Nachrichtenpreis zuordnen.",
  "a8.b12": "Für eine monatliche Gesamtkostenschätzung solltest du Abonnement, Nutzungsguthaben, zugestellte WhatsApp-Nachrichten, Steuern und mögliche anbieterspezifische Gebühren getrennt betrachten. Nimm weder eine Weitergabe zum Selbstkostenpreis noch einen Aufschlag an, ohne die aktuellen Abrechnungsbedingungen des Anbieters zu prüfen.",
  "a8.b13": "2. Ein datiertes Beispiel ohne erfundene Gesamtsummen",
  "a8.b14": "Angenommen, ein ägyptischer Shop hat 5.000 Kontakte und plant 2.000 WhatsApp-Marketingnachrichten an ägyptische Nummern. Die veröffentlichten Tarifübersichten zeigen die enthaltenen Kontaktmengen; Metas aktuelle USD-Preisliste bietet eine separate Grundlage für Nachrichtenentgelte. Die Anbieterrechnung kann abweichen, daher sind die folgenden Zahlen keine monatliche Gesamtsumme.",
  "a8.tl1": "Position",
  "a8.tl2": "Veröffentlichte Angabe",
  "a8.tl3": "Was sie aussagt — und was nicht",
  "a8.t1": "ManyChat-Tarif für 5.000 Kontakte",
  "a8.t1a": "Business: umgerechnet 69 $/Monat bei jährlicher Abrechnung; 7.500 Kontakte",
  "a8.t1b": "Abonnement-Snapshot; prüfe regionale Preise, Funktionen und Steuern",
  "a8.t2": "Chatfuel Business",
  "a8.t2a": "20 $ monatlich oder umgerechnet 18 $/Monat bei jährlicher Abrechnung; 20 $ monatliches Guthaben",
  "a8.t2b": "Wallet-Abzüge und Gesamtnutzung erfordern kontospezifische Abrechnungsdetails",
  "a8.t3": "Meta-Gebühr für 2.000 zugestellte Marketingnachrichten nach Ägypten",
  "a8.t3a": "128,80 $ nach Metas Listenpreis von 0,0644 USD",
  "a8.t3b": "Nur eine Berechnung zum Meta-Listenpreis; ohne Plattform-, Anbieter-, Steuer- und sonstige Gebühren",
  "a8.t4": "Angabe aus ManyChats WhatsApp-Leitfaden",
  "a8.t4a": "0,0740 $ je Marketingnachricht nach Ägypten im Leitfaden vom 7. Oktober",
  "a8.t4b": "Von ManyChat veröffentlichte Angabe; nicht mit Metas Preisliste gleichzusetzen",
  "a8.t5": "Chatora-Gesamtsumme",
  "a8.t5a": "Nicht veröffentlicht",
  "a8.t5b": "Kein Abonnementpreis und keine Live-Messaging-Integration zum Vergleichen",
  "a8.foot": "Anbieterseiten geprüft am 28. Oktober 2026; Metas USD-Listenpreisliste gilt ab 1. Oktober 2026. Die genannten monatlichen Äquivalente beruhen, sofern angegeben, auf jährlicher Abrechnung. Regionale Preise, Steuern, Wallet-Bedingungen und Nutzung können variieren; diese Tabelle schätzt keine endgültige Monatsgesamtsumme.",
  "a8.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">ManyChat-Preise</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Chatfuel-Preise</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Chatfuel-Abrechnungsdokumentation</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Meta-Preisliste</a>",
  "a8.b15": "Metas Preisliste nennt für Ägypten 0,0644 $ je Marketingnachricht und 0,0036 $ für Utility-, Authentifizierungs- und Servicenachrichten. ManyChats Leitfaden nennt für Marketing in Ägypten einen anderen Wert. Frage jeden Anbieter, welche Tarife und Gebühren für dein Konto gelten, und vergleiche die Rechnung mit Metas veröffentlichter Preisliste; allein die Differenz erklärt nicht ihre Ursache.",
  "a8.b16": "3. Wofür die einzelnen Plattformen geeignet sein könnten",
  "a8.b17": "Ein sinnvoller Vergleich berücksichtigt die jeweiligen Stärken und Grenzen der Produkte:",
  "a8.b18": "<strong>ManyChat — etabliertes Ökosystem.</strong> Es bietet einen ausgereiften Builder, Community-Ressourcen und ein öffentliches Partnerprogramm. Prüfe, ob die aktuellen Kanal-, KI- und Supportfunktionen zu deinem Tarif passen.",
  "a8.b19": "<strong>Chatfuel — Wallet- und Agenturoptionen.</strong> Die öffentlichen Seiten nennen den WhatsApp-Anbieterstatus, unbegrenzte Kontakte in den Hilfedokumenten und die Option Agency S. Wallet-Abrechnung und tatsächliche Nutzung solltest du prüfen.",
  "a8.b20": "<strong>Chatora — Produktvorschau.</strong> Sie bietet arabische und englische UI-Texte, bearbeitbare Startentwürfe und CSV-Tools. Chatora ist keine Live-Messaging-Alternative und hat keinen veröffentlichten Abonnementpreis.",
  "a8.b21": "4. Fragen vor einem Wechsel",
  "a8.b22": "<strong>Welche Daten kannst du exportieren?</strong> Sichere Kontaktlisten, Flow-Definitionen und Nachrichtenvorlagen, bevor du den Anbieter wechselst; prüfe die Exportfunktionen jeder Plattform.",
  "a8.b23": "<strong>Welche Kanalberechtigungen sind erforderlich?</strong> Prüfe den offiziellen API-Zugang, die Kontoinhaberschaft und Genehmigungsvoraussetzungen, bevor du ein Produktionskonto verbindest.",
  "a8.b24": "<strong>Welche Funktionen verliert oder gewinnt dein Team?</strong> Vergleiche Vorlagenbibliotheken, Agentur-Workflows, Integrationen, Sprachunterstützung und Supportzusagen.",
  "a8.b25": "<strong>Wie hoch ist der tatsächliche Nachrichtenpreis?</strong> Frage nach dem geltenden Marktpreis für die jeweilige Kategorie und einer Musterrechnung; Metas Preisliste und die Abrechnungsanzeige des Anbieters können voneinander abweichen.",
  "a8.b26": "5. Fazit nach Anwendungsfall",
  "a8.b27": "<strong>Du brauchst jetzt Live-Messaging über soziale Kanäle:</strong> Prüfe Anbieter mit aktuell verfügbaren, offiziell unterstützten Kanälen und bestätige die Tarifgrenzen.",
  "a8.b28": "<strong>Du brauchst einen großen Kontaktbestand oder ein Wallet-Modell:</strong> Vergleiche Chatfuels veröffentlichten Tarif, Guthaben und kontospezifische Nutzung mit deinem erwarteten Nachrichtenmix.",
  "a8.b29": "<strong>Du brauchst ein ausgereiftes Vorlagen-Ökosystem:</strong> ManyChat könnte passen; prüfe das aktuelle lokale Angebot und den Funktionsumfang des Tarifs.",
  "a8.b30": "<strong>Du ziehst Chatora in Betracht:</strong> Die aktuelle Vorschau ist keine Messaging-Software für den Produktivbetrieb. Prüfe die Verfügbarkeitsseite; ein Preis oder Sparvergleich wird nicht veröffentlicht.",
  "a8.b31": "Notiere vor dem Kauf die Kontaktzahl, Kanäle, erwarteten Nachrichtenkategorien, KI-Nutzung und das Abrechnungsland. Bitte jeden Anbieter um schriftliche Bedingungen und vergleiche denselben Zeitraum und Funktionsumfang.",
  "a8.b32": "Häufige Fragen, kurz beantwortet",
  "a8.b33": "Ist Chatfuel günstiger als ManyChat?",
  "a8.b34": "Die veröffentlichten Abonnementpreise unterscheiden sich, doch die Gesamtkosten hängen von Kontaktgrenzen, Funktionszugang, monatlichem Guthaben, Wallet-Abzügen, Meta-Nachrichtenentgelten, Steuern und Abrechnungszeitraum ab. Ein Vergleich nur der Abonnements ist keine Gesamtkostenantwort.",
  "a8.b35": "Kann ich Chatoras Preis mit deren Preisen vergleichen?",
  "a8.b36": "Nein. Chatora hat weder einen veröffentlichten Abonnementpreis noch einen Live-Messaging-Kanal; daher gibt es keinen gleichwertigen Tarif und keine vergleichbare nutzungsabhängige Gesamtsumme.",
  "a8.b37": "Werden Kontakte beim Wechsel automatisch übertragen?",
  "a8.b38": "Gehe nicht davon aus. Exportiere und sichere verfügbare Daten deines aktuellen Anbieters und prüfe Eigentums- und Übertragungsregeln des Kanals, bevor du die Verbindung trennst.",
  "a8.b39": "Wo finde ich Chatoras aktuelle Verfügbarkeit?",
  "a8.b40": "Die Preisseite nennt, was in der aktuellen Vorschau aktiviert ist und was nicht. Sie veröffentlicht weder einen kostenpflichtigen Tarif noch ein Versprechen für Live-Kanalnachrichten.",
  "a8.b41": "Prüfe veröffentlichte Bedingungen, keine angenommene Gesamtsumme",
  "a8.b42": "Prüfe die aktuellen Preise und Nutzungsregeln jedes Anbieters. Chatoras Seite zeigt den Status der Vorschau; einen vollständigen Kostenvergleich kann sie noch nicht berechnen.",
  "a8.b43": "Chatoras Verfügbarkeit prüfen →",
  "a8.b44": "Quellen: ManyChat- und Chatfuel-Preis- und Abrechnungsseiten, geprüft am 28. Oktober 2026; Metas USD-WhatsApp-Preisliste, gültig ab 1. Oktober 2026. Preise, Wallet-Bedingungen und regionale Abrechnung können sich ändern. Chatora ist nicht mit ManyChat oder Chatfuel verbunden.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a8.h1": "ManyChat vs. Chatfuel em 2026: preços dos planos, cobrança por carteira e o que verificar",
  "a8.lede": "O ManyChat usa níveis de plano por quantidade de contatos; o Chatfuel combina assinatura com créditos mensais e consumo da carteira. Esta comparação datada separa os valores públicos das tarifas por mensagem e do uso, que dependem de cada conta. A Chatora aparece apenas para indicar o estado da prévia do produto, não como concorrente com preço ativo.",
  "a8.author": "Equipe de pesquisa da Chatora",
  "a8.date": "Atualizado em 28 de outubro de 2026 · 9 min de leitura",
  "a8.callout": "<b>Resposta curta:</b> os preços de assinatura, por si só, não fornecem um total confiável com todos os custos. O ManyChat publica faixas por contatos; o Chatfuel publica preços de assinatura e créditos, enquanto o consumo da carteira e as tarifas do WhatsApp dependem do uso real. A Chatora não tem preços publicados nem canais ativos, portanto não há um total comparável da Chatora.",
  "a8.b1": "Conteúdo",
  "a8.b2": "<a href=\"#models\">Três modelos de cobrança publicados</a>",
  "a8.b3": "<a href=\"#worked\">Um exemplo datado, sem inventar totais</a>",
  "a8.b4": "<a href=\"#wins\">Para quais casos cada plataforma pode servir</a>",
  "a8.b5": "<a href=\"#switch\">Perguntas antes de mudar</a>",
  "a8.b6": "<a href=\"#verdict\">Conclusão por caso de uso</a>",
  "a8.b7": "1. Três modelos de cobrança publicados",
  "a8.b8": "As páginas dos planos mostram unidades de cobrança diferentes; isso não prova que as ferramentas incluam os mesmos recursos nem resultem na mesma fatura final:",
  "a8.b9": "<strong>ManyChat — faixas por contatos.</strong> A página em USD, consultada em 28 de outubro, lista Free com 25 contatos, Essential com 250, Pro com 2.500, Business com 7.500 e Advanced com 25.000. Os equivalentes mensais com cobrança anual são US$ 14, US$ 29, US$ 69 e US$ 139 nos planos pagos.",
  "a8.b10": "<strong>Chatfuel — assinatura, créditos e consumo da carteira.</strong> O Business aparece por US$ 20 no pagamento mensal ou equivalente a US$ 18/mês na cobrança anual, com US$ 20 em créditos mensais. O Agency S aparece por US$ 100 mensais ou equivalente a US$ 90/mês na cobrança anual, com US$ 100 em créditos e três empresas clientes. Verifique como o saldo da carteira é aplicado ao seu uso.",
  "a8.b11": "<strong>Chatora — prévia do produto.</strong> Não há preço de assinatura publicado, canal de mensagens conectado nem resposta de IA ao vivo. Hoje não é possível atribuir à Chatora um plano ou custo por mensagem comparável.",
  "a8.b12": "Para estimar o custo mensal total, separe a assinatura, os créditos de uso, as mensagens do WhatsApp entregues, os impostos e eventuais tarifas específicas do provedor. Não presuma repasse pelo custo nem acréscimo sem consultar os termos de cobrança atuais do provedor.",
  "a8.b13": "2. Um exemplo datado, sem inventar totais",
  "a8.b14": "Suponha que uma loja egípcia tenha 5.000 contatos e planeje enviar 2.000 mensagens de marketing pelo WhatsApp para números do Egito. As referências públicas dos planos ajudam a identificar as franquias da assinatura; a tabela atual da Meta em USD fornece uma base separada para as tarifas das mensagens. A cobrança do provedor pode ser diferente, portanto os valores abaixo não representam um total mensal com todos os custos.",
  "a8.tl1": "Item",
  "a8.tl2": "Valor publicado",
  "a8.tl3": "O que informa — e o que não informa",
  "a8.t1": "Plano do ManyChat para 5.000 contatos",
  "a8.t1a": "Business: equivalente a US$ 69/mês na cobrança anual; 7.500 contatos",
  "a8.t1b": "Referência da assinatura; verifique preço regional, recursos e impostos",
  "a8.t2": "Chatfuel Business",
  "a8.t2a": "US$ 20 mensal ou equivalente a US$ 18/mês na cobrança anual; US$ 20 em créditos mensais",
  "a8.t2b": "Os débitos da carteira e o uso total exigem detalhes de cobrança da conta",
  "a8.t3": "Tarifa da Meta para 2.000 mensagens de marketing entregues no Egito",
  "a8.t3a": "US$ 128,80 pela tarifa de lista da Meta de US$ 0,0644",
  "a8.t3b": "Somente o cálculo pela tarifa de lista da Meta; exclui plataforma, provedor, impostos e outras tarifas",
  "a8.t4": "Valor do guia de WhatsApp do ManyChat",
  "a8.t4a": "US$ 0,0740 por mensagem de marketing para o Egito no guia de 7 de outubro",
  "a8.t4b": "Valor publicado pelo ManyChat; não é intercambiável com a tarifa da Meta",
  "a8.t5": "Total da Chatora",
  "a8.t5a": "Não publicado",
  "a8.t5b": "Sem preço de assinatura ou integração de mensagens ao vivo para comparar",
  "a8.foot": "Páginas dos provedores consultadas em 28 de outubro de 2026; a tarifa de lista da Meta em USD entra em vigor em 1º de outubro de 2026. Os equivalentes mensais indicados usam cobrança anual quando especificado. Preços regionais, impostos, termos da carteira e uso podem variar; esta tabela não estima o total mensal final.",
  "a8.sources": "<a href=\"https://manychat.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do ManyChat</a> · <a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentação de cobrança do Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tabela de tarifas da Meta</a>",
  "a8.b15": "A tabela da Meta lista para o Egito US$ 0,0644 por mensagem de marketing e US$ 0,0036 para mensagens de utilidade, autenticação e serviço. O guia do ManyChat apresenta outro valor de marketing para o Egito. Pergunte a cada provedor quais tarifas e cobranças se aplicam à sua conta e compare a fatura com a tabela publicada pela Meta; a diferença, por si só, não explica a causa.",
  "a8.b16": "3. Para quais casos cada plataforma pode servir",
  "a8.b17": "Uma comparação útil considera os pontos fortes e as limitações de cada produto:",
  "a8.b18": "<strong>ManyChat — ecossistema consolidado.</strong> Oferece um construtor maduro, recursos da comunidade e um programa público de parceiros. Verifique se os recursos atuais de canais, IA e suporte atendem ao seu plano.",
  "a8.b19": "<strong>Chatfuel — opções de carteira e agência.</strong> As páginas públicas listam o status de provedores de WhatsApp, contatos ilimitados na documentação de ajuda e uma opção Agency S. É preciso analisar a carteira e o uso real.",
  "a8.b20": "<strong>Chatora — prévia do produto.</strong> Oferece textos de interface em árabe e inglês, rascunhos iniciais editáveis e ferramentas CSV. Não é uma alternativa de mensagens ao vivo e não tem preço de assinatura publicado.",
  "a8.b21": "4. Perguntas antes de mudar",
  "a8.b22": "<strong>Quais dados podem ser exportados?</strong> Salve os registros de contatos, as definições dos fluxos e os modelos de mensagem antes de trocar de provedor; verifique as ferramentas de exportação de cada plataforma.",
  "a8.b23": "<strong>Quais permissões de canal são necessárias?</strong> Verifique o acesso oficial à API, a titularidade da conta e os requisitos de aprovação antes de conectar uma conta de produção.",
  "a8.b24": "<strong>Quais recursos sua equipe vai perder ou ganhar?</strong> Compare bibliotecas de modelos, fluxos de agência, integrações, suporte a idiomas e compromissos de atendimento.",
  "a8.b25": "<strong>Qual é o preço real por mensagem?</strong> Peça a tarifa aplicável à categoria e ao mercado, além de uma fatura de exemplo; a tabela da Meta e a cobrança apresentada pelo provedor podem ser diferentes.",
  "a8.b26": "5. Conclusão por caso de uso",
  "a8.b27": "<strong>Precisa de mensagens sociais ao vivo agora:</strong> avalie provedores com canais oficialmente compatíveis e disponíveis atualmente e confirme os limites do plano.",
  "a8.b28": "<strong>Precisa de uma grande base de contatos ou modelo de carteira:</strong> compare o plano publicado do Chatfuel, os créditos e o uso no nível da conta com a combinação de mensagens esperada.",
  "a8.b29": "<strong>Precisa de um ecossistema maduro de modelos:</strong> o ManyChat pode servir; verifique a oferta local atual e o nível de recursos.",
  "a8.b30": "<strong>Está considerando a Chatora:</strong> a prévia atual não é um software de mensagens para produção. Consulte a página de disponibilidade; não há preço publicado nem comparação de economia.",
  "a8.b31": "Antes de comprar, registre a quantidade de contatos, os canais, as categorias de mensagens esperadas, o uso de IA e o país de cobrança. Peça os termos por escrito a cada provedor e compare o mesmo período e conjunto de recursos.",
  "a8.b32": "Perguntas frequentes, em resumo",
  "a8.b33": "O Chatfuel é mais barato que o ManyChat?",
  "a8.b34": "Os preços públicos de assinatura são diferentes, mas o total depende dos limites de contatos, acesso a recursos, créditos mensais, débitos da carteira, tarifas de mensagens da Meta, impostos e período de cobrança. Comparar somente as assinaturas não fornece o custo total.",
  "a8.b35": "Posso comparar o preço da Chatora com os deles?",
  "a8.b36": "Não. A Chatora não tem preço de assinatura publicado nem canal de mensagens ao vivo, portanto não há plano equivalente ou total de uso para comparar.",
  "a8.b37": "Os contatos são transferidos automaticamente quando eu mudo?",
  "a8.b38": "Não presuma que sim. Exporte e faça backup dos registros disponíveis no provedor atual e verifique as regras de titularidade e transferência do canal antes de desconectá-lo.",
  "a8.b39": "Onde posso consultar a disponibilidade atual da Chatora?",
  "a8.b40": "A página de preços informa o que está e não está habilitado na prévia atual. Ela não publica um plano pago nem promete mensagens em canais ao vivo.",
  "a8.b41": "Consulte os termos publicados, não um total presumido",
  "a8.b42": "Confira os preços e as regras de uso atuais de cada provedor. A página da Chatora mostra o estado da prévia; ainda não é possível calcular uma comparação com todos os custos.",
  "a8.b43": "Consultar disponibilidade da Chatora →",
  "a8.b44": "Fontes: páginas de preços e cobrança do ManyChat e do Chatfuel consultadas em 28 de outubro de 2026; tabela de tarifas do WhatsApp da Meta em USD vigente desde 1º de outubro de 2026. Preços, termos da carteira e cobrança regional podem mudar. A Chatora não é afiliada ao ManyChat nem ao Chatfuel.",
});


/* Article a9 translations: Chatfuel pricing. */
Object.assign(window.CHATORA_I18N_PAGES.es, {
  "a9.h1": "Precios de Chatfuel explicados (2026): planes, saldo de cartera y tarifas de WhatsApp",
  "a9.lede": "Chatfuel publica precios de suscripción y créditos mensuales, mientras que los cargos por IA y WhatsApp pueden depender del uso. Esta instantánea fechada separa las cifras públicas de los planes de los costes que dependen del saldo y la factura de tu cuenta. No se presupone ningún recargo porcentual no documentado ni un precio por respuesta.",
  "a9.author": "Equipo de investigación de Chatora",
  "a9.date": "Actualizado el 28 de octubre de 2026 · 8 min de lectura",
  "a9.callout": "<b>Instantánea:</b> la página de precios de Chatfuel indica Business a 20 $/mes o un equivalente de 18 $/mes con facturación anual, con 20 $ en créditos mensuales. Agency S figura a 100 $/mes o un equivalente de 90 $/mes con facturación anual, con 100 $ en créditos mensuales y tres empresas cliente. El uso del saldo y las tarifas de mensajes de Meta dependen del uso real; las páginas publicadas no respaldan una factura total universal ni una afirmación general de un recargo del 10%.",
  "a9.b1": "Contenido",
  "a9.b2": "<a href=\"#plan\">Precios de los planes publicados</a>",
  "a9.b3": "<a href=\"#wallet\">Qué cubre el saldo de la cartera</a>",
  "a9.b4": "<a href=\"#estimate\">Qué se necesita para calcular el coste total</a>",
  "a9.b5": "<a href=\"#fit\">Para qué podría convenir Chatfuel</a>",
  "a9.b6": "<a href=\"#faq\">Qué comprobar antes de contratar</a>",
  "a9.b7": "1. Precios de los planes publicados",
  "a9.b8": "El 28 de octubre de 2026, la página pública de precios de Chatfuel indicaba Business a 20 $ mes a mes o a un equivalente de 18 $ al mes con facturación anual (216 $ facturados al año). La página incluye 20 $ en créditos mensuales. Agency S figura a 100 $ mes a mes o a un equivalente de 90 $ al mes con facturación anual (1.080 $ facturados al año), con 100 $ en créditos mensuales y tres empresas cliente. Confirma las condiciones regionales y el tratamiento exacto de los créditos en las páginas de pago y facturación del proveedor.",
  "a9.b9": "La página de precios ofrece una prueba gratuita de siete días; no indica un plan gratuito permanente. La página pública de planes describe los créditos incluidos como créditos de IA, mientras que la documentación de facturación de Chatfuel también describe el uso del saldo para costes de IA y WhatsApp. Comprueba las condiciones actuales de la cuenta y los cargos que prevés utilizar.",
  "a9.b10": "2. Qué cubre el saldo de la cartera",
  "a9.b11": "La documentación de facturación actual de Chatfuel indica que el saldo puede cubrir respuestas de IA y cargos de mensajes de WhatsApp facturados por Meta. El crédito mensual es una aportación al presupuesto, no una promesa de uso ilimitado. El gasto real depende del número y la categoría de los mensajes entregados, el uso de IA, cualquier franquicia gratuita aplicable y la configuración de facturación de la cuenta.",
  "a9.tl1": "Concepto publicado",
  "a9.tl2": "Información pública",
  "a9.tl3": "Qué verificar",
  "a9.t1": "Suscripción Business",
  "a9.t1a": "20 $ al mes; equivalente a 18 $/mes con facturación anual (216 $/año)",
  "a9.t1b": "La facturación anual se paga por adelantado; confirma el precio regional y los impuestos",
  "a9.t2": "Crédito mensual de Business",
  "a9.t2a": "20 $ en créditos mensuales",
  "a9.t2b": "Consulta la página de facturación para conocer los cargos de cartera admitidos y las condiciones de renovación",
  "a9.t3": "Agency S",
  "a9.t3a": "100 $ al mes; equivalente a 90 $/mes con facturación anual (1.080 $/año)",
  "a9.t3b": "La página de precios indica 100 $ en créditos mensuales y tres empresas cliente",
  "a9.t4": "Mensajes de WhatsApp",
  "a9.t4a": "Las tarifas de Meta varían según la categoría y el mercado del destinatario",
  "a9.t4b": "Pregunta cómo factura el proveedor a tu cuenta; no deduzcas un recargo a partir de la tarifa de otro proveedor",
  "a9.t5": "Coste mensual total",
  "a9.t5a": "No se determina solo con la suscripción",
  "a9.t5b": "Usa los términos reales del saldo, el volumen de mensajes, el plan y la factura",
  "a9.foot": "Páginas públicas consultadas el 28 de octubre de 2026. La página de precios y la documentación de facturación pueden describir de manera distinta los créditos y los cargos del saldo; confirma con Chatfuel las condiciones aplicables. A continuación se enlaza la tarifa de Meta para Egipto. Aquí no se presupone ningún recargo de Chatfuel ni un coste por respuesta de IA.",
  "a9.sources": "<a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentación de facturación de Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Precios de WhatsApp de Meta</a>",
  "a9.b13": "3. Qué se necesita para calcular el coste total",
  "a9.b14": "Para elaborar una estimación mensual útil, recopila los envíos de WhatsApp previstos por categoría de mensaje y país del destinatario, tu uso de IA, el crédito mensual incluido en el plan, cualquier ajuste de recarga automática y los impuestos aplicables. La tarifa de Meta cobra por categoría de mensaje entregado y mercado, e incluye una franquicia mensual gratuita para mensajes de servicio; las condiciones de facturación del proveedor pueden añadirse o mostrarse de otra forma. Compara las facturas, no solo los titulares de los planes.",
  "a9.b15": "No conviertas una respuesta de IA de ejemplo en un precio universal por respuesta. El uso de tokens y la configuración del modelo pueden variar, y los cargos del saldo dependen de las reglas de facturación vigentes de Chatfuel. Si el panel del proveedor ofrece una estimación de uso, valídala con tu factura real antes de ampliar el uso.",
  "a9.b16": "4. Para qué podría convenir Chatfuel",
  "a9.b17": "Un precio inicial de suscripción bajo es solo un factor. Las páginas públicas actuales pueden hacer que valga la pena evaluar Chatfuel si sus canales, modelo de contactos, cartera o herramientas de agencia encajan con tu flujo de trabajo.",
  "a9.b18": "<strong>Grandes bases de contactos.</strong> La documentación de ayuda de Chatfuel indica contactos ilimitados en sus planes; comprueba las condiciones actuales del plan y la economía del uso de mensajes para tu propia audiencia.",
  "a9.b19": "<strong>Equipos que comparan herramientas para agencias.</strong> La página de precios indica que Agency S incluye tres empresas cliente y un panel de agencia. Compara el límite exacto de clientes y los créditos incluidos con la cantidad de marcas que gestionas.",
  "a9.b20": "<strong>Equipos que supervisan el uso.</strong> La cartera permite ver el consumo, pero también significa que el uso de IA y mensajería puede cambiar el total. Revisa los ajustes de recarga y las alertas antes de activar automatizaciones.",
  "a9.b21": "5. Qué comprobar antes de contratar",
  "a9.b22": "<strong>¿Se acumulan los créditos mensuales?</strong> Consulta las condiciones de facturación actuales y la configuración de la cuenta; no des por hecho que los saldos no utilizados se transfieren.",
  "a9.b23": "<strong>¿Qué ocurre al llegar al umbral del saldo?</strong> Confirma si la recarga automática está activada, cómo se inicia y cómo pausarla.",
  "a9.b24": "<strong>¿Cómo se facturan los mensajes de WhatsApp?</strong> Solicita la tarifa aplicable por categoría y mercado y una factura de ejemplo; la tarifa pública de Meta puede diferir del desglose del proveedor.",
  "a9.b25": "<strong>¿La prueba es un plan gratuito permanente?</strong> No: la página de precios indica una prueba de siete días, no un nivel de suscripción gratuita permanente.",
  "a9.b26": "Compara la disponibilidad actual antes de cambiar",
  "a9.b27": "La vista previa actual de Chatora no tiene un precio de suscripción publicado ni canales de mensajería activos. Todavía no es válida una comparación de costes totales; consulta las condiciones públicas fechadas de cada proveedor y tu propio uso.",
  "a9.b28": "Consultar la disponibilidad de Chatora →",
  "a9.b29": "Preguntas frecuentes, en breve",
  "a9.b30": "¿Chatfuel tiene un plan gratuito permanente?",
  "a9.b31": "La página de precios consultada el 28 de octubre de 2026 indica una prueba gratuita de siete días y planes de pago; no muestra un plan gratuito permanente. Los detalles de la prueba pueden cambiar, así que confirma la oferta actual directamente.",
  "a9.b32": "¿Puedo calcular el coste de una respuesta de IA?",
  "a9.b33": "No a partir de una tarifa fija única por respuesta. El uso depende del modelo y del consumo real, y los cargos se determinan según las condiciones actuales del saldo del proveedor. Usa tus propios datos de facturación para estimar el coste.",
  "a9.b34": "¿Chatfuel es más barato que ManyChat?",
  "a9.b35": "Los precios de suscripción y los límites incluidos son distintos, por lo que el precio inicial más bajo no es una comparación de costes totales. Para tu caso de uso, suma la franquicia de contactos o conversaciones, los canales necesarios, los créditos, los cargos por mensajes, los impuestos y el ciclo de facturación.",
  "a9.b36": "¿Puedo trasladar un bot de Chatfuel a Chatora?",
  "a9.b37": "La vista previa de Chatora no cuenta con una herramienta de migración ni un servicio de migración probados. Conserva tus exportaciones originales y confirma que cualquier importador futuro esté implementado y probado antes de planificar un cambio.",
  "a9.r1": "Chatora vs. Chatfuel: comparación fechada y disponibilidad actual",
  "a9.r2": "ManyChat vs. Chatfuel: precios de los planes y modelos de facturación",
  "a9.b38": "Fuentes: página de precios y documentación de facturación de Chatfuel consultadas el 28 de octubre de 2026, y página de precios de WhatsApp Business Platform de Meta, actualizada el 30 de septiembre de 2026. Los precios de lista y las condiciones de facturación pueden cambiar; verifica los detalles actuales antes de comprar. Chatora no está afiliada a Chatfuel.",
});

Object.assign(window.CHATORA_I18N_PAGES.fr, {
  "a9.h1": "Tarifs de Chatfuel expliqués (2026) : forfaits, portefeuille et frais WhatsApp",
  "a9.lede": "Chatfuel publie des prix d’abonnement et des crédits mensuels, tandis que les frais d’IA et de WhatsApp peuvent dépendre de l’utilisation. Cet instantané daté distingue les tarifs publics des coûts liés au portefeuille et à la facture de votre compte. Aucun pourcentage de majoration non documenté ni prix par réponse n’est supposé.",
  "a9.author": "Équipe de recherche de Chatora",
  "a9.date": "Mis à jour le 28 octobre 2026 · 8 min de lecture",
  "a9.callout": "<b>Instantané :</b> la page tarifaire de Chatfuel affiche Business à 20 $/mois ou à l’équivalent de 18 $/mois avec facturation annuelle, avec 20 $ de crédits mensuels. Agency S est affiché à 100 $/mois ou à l’équivalent de 90 $/mois avec facturation annuelle, avec 100 $ de crédits mensuels et trois entreprises clientes. L’utilisation du portefeuille et les frais de messages Meta dépendent de l’usage réel ; les pages publiées ne justifient ni une facture totale universelle ni l’affirmation générale d’une majoration de 10 %.",
  "a9.b1": "Sommaire",
  "a9.b2": "<a href=\"#plan\">Prix des forfaits publiés</a>",
  "a9.b3": "<a href=\"#wallet\">Ce que couvre le portefeuille</a>",
  "a9.b4": "<a href=\"#estimate\">Éléments nécessaires à une estimation tout compris</a>",
  "a9.b5": "<a href=\"#fit\">Dans quels cas Chatfuel peut convenir</a>",
  "a9.b6": "<a href=\"#faq\">Questions à vérifier avant l’achat</a>",
  "a9.b7": "1. Prix des forfaits publiés",
  "a9.b8": "Au 28 octobre 2026, la page tarifaire publique de Chatfuel affichait Business à 20 $ au mois ou à l’équivalent de 18 $/mois avec facturation annuelle (216 $ facturés par an). La page indique 20 $ de crédits mensuels. Agency S est affiché à 100 $ au mois ou à l’équivalent de 90 $/mois avec facturation annuelle (1 080 $ facturés par an), avec 100 $ de crédits mensuels et trois entreprises clientes. Vérifiez les conditions régionales et le traitement exact des crédits dans les pages de paiement et de facturation du fournisseur.",
  "a9.b9": "La page tarifaire propose un essai gratuit de sept jours ; elle ne mentionne pas de forfait gratuit permanent. La page publique des forfaits décrit les crédits inclus comme des crédits IA, tandis que la documentation de facturation de Chatfuel décrit aussi l’utilisation du portefeuille pour les coûts de l’IA et de WhatsApp. Vérifiez les conditions actuelles applicables au compte et aux frais que vous prévoyez.",
  "a9.b10": "2. Ce que couvre le portefeuille",
  "a9.b11": "La documentation de facturation actuelle de Chatfuel indique que l’utilisation du portefeuille peut inclure les réponses IA et les frais de messages WhatsApp facturés par Meta. Le crédit mensuel contribue au budget ; il ne promet pas un usage illimité. Les dépenses réelles dépendent du nombre et de la catégorie des messages livrés, de l’usage de l’IA, de toute franchise gratuite applicable et des paramètres de facturation du compte.",
  "a9.tl1": "Élément publié",
  "a9.tl2": "Indication publique",
  "a9.tl3": "Points à vérifier",
  "a9.t1": "Abonnement Business",
  "a9.t1a": "20 $ au mois ; équivalent à 18 $/mois avec facturation annuelle (216 $/an)",
  "a9.t1b": "La facturation annuelle est payée d’avance ; vérifiez le prix régional et les taxes",
  "a9.t2": "Crédit mensuel Business",
  "a9.t2a": "20 $ de crédits mensuels",
  "a9.t2b": "Consultez la page de facturation pour connaître les frais de portefeuille admissibles et les modalités de renouvellement",
  "a9.t3": "Agency S",
  "a9.t3a": "100 $ au mois ; équivalent à 90 $/mois avec facturation annuelle (1 080 $/an)",
  "a9.t3b": "La page tarifaire indique 100 $ de crédits mensuels et trois entreprises clientes",
  "a9.t4": "Messages WhatsApp",
  "a9.t4a": "Les frais Meta varient selon la catégorie et le marché du destinataire",
  "a9.t4b": "Demandez comment le fournisseur facture votre compte ; ne déduisez pas une majoration du tarif d’un autre fournisseur",
  "a9.t5": "Total mensuel tout compris",
  "a9.t5a": "Ne peut pas être déterminé par le seul abonnement",
  "a9.t5b": "Tenez compte du portefeuille réel, du volume de messages, du forfait et des conditions de facturation",
  "a9.foot": "Pages publiques consultées le 28 octobre 2026. La page tarifaire et la documentation de facturation peuvent décrire différemment les crédits et les frais de portefeuille ; confirmez les conditions applicables auprès de Chatfuel. La grille tarifaire Meta pour l’Égypte est liée ci-dessous. Aucune majoration Chatfuel ni aucun coût par réponse IA n’est supposé ici.",
  "a9.sources": "<a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentation de facturation Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Tarifs WhatsApp de Meta</a>",
  "a9.b13": "3. Éléments nécessaires à une estimation tout compris",
  "a9.b14": "Pour établir une estimation mensuelle pertinente, recueillez le nombre prévu de messages WhatsApp livrés par catégorie et par pays du destinataire, votre usage de l’IA, le crédit mensuel inclus dans le forfait, les paramètres éventuels de recharge automatique et les taxes applicables. La grille de Meta facture chaque message livré selon sa catégorie et son marché, avec une franchise mensuelle gratuite pour les messages de service ; les conditions de facturation du fournisseur peuvent s’y ajouter ou être présentées différemment. Comparez les factures, pas seulement les intitulés des forfaits.",
  "a9.b15": "Ne transformez pas un exemple de réponse IA en prix universel par réponse. L’utilisation de jetons et les paramètres du modèle peuvent varier, et les déductions du portefeuille dépendent des règles de facturation actuelles de Chatfuel. Si le tableau de bord du fournisseur propose une estimation d’usage, vérifiez-la à l’aide de votre facture réelle avant de passer à l’échelle supérieure.",
  "a9.b16": "4. Dans quels cas Chatfuel peut convenir",
  "a9.b17": "Un prix d’abonnement d’appel bas n’est qu’un facteur parmi d’autres. Les pages publiques actuelles peuvent justifier d’évaluer Chatfuel si les canaux, le modèle de contacts, le portefeuille ou les outils agence proposés correspondent à votre flux de travail.",
  "a9.b18": "<strong>Grandes bases de contacts.</strong> La documentation d’aide de Chatfuel indique des contacts illimités dans ses forfaits ; vérifiez les conditions actuelles et l’économie de l’usage des messages pour votre audience.",
  "a9.b19": "<strong>Équipes comparant des outils agence.</strong> La page tarifaire indique qu’Agency S comprend trois entreprises clientes et un tableau de bord agence. Comparez la limite exacte de clients et le crédit inclus au nombre de marques que vous gérez.",
  "a9.b20": "<strong>Équipes qui surveillent l’utilisation.</strong> Le portefeuille rend la consommation visible, mais signifie aussi que l’usage de l’IA et de la messagerie peut modifier le total. Vérifiez les paramètres de recharge et les alertes avant d’activer l’automatisation.",
  "a9.b21": "5. Questions à vérifier avant l’achat",
  "a9.b22": "<strong>Les crédits mensuels sont-ils reportés ?</strong> Vérifiez les conditions de facturation et les paramètres du compte actuels, plutôt que de supposer que les soldes inutilisés sont reportés.",
  "a9.b23": "<strong>Que se passe-t-il lorsque le portefeuille atteint son seuil ?</strong> Vérifiez si la recharge automatique est activée, comment elle se déclenche et comment la suspendre.",
  "a9.b24": "<strong>Comment les frais des messages WhatsApp sont-ils facturés ?</strong> Demandez le tarif applicable par catégorie et par marché ainsi qu’un exemple de facture ; la grille publique de Meta peut différer du détail de facturation du fournisseur.",
  "a9.b25": "<strong>L’essai est-il un forfait gratuit permanent ?</strong> Non : la page tarifaire indique un essai de sept jours, pas un niveau d’abonnement gratuit permanent.",
  "a9.b26": "Vérifiez la disponibilité actuelle avant de changer",
  "a9.b27": "L’aperçu actuel de Chatora n’a ni prix d’abonnement publié ni canaux de messagerie en direct. Aucune comparaison de coût total valide n’est possible pour l’instant ; consultez les conditions publiques datées de chaque fournisseur et votre propre usage.",
  "a9.b28": "Consulter la disponibilité de Chatora →",
  "a9.b29": "Questions fréquentes, en bref",
  "a9.b30": "Chatfuel propose-t-il un forfait gratuit permanent ?",
  "a9.b31": "La page tarifaire consultée le 28 octobre 2026 indique un essai gratuit de sept jours et des forfaits payants ; elle ne mentionne pas de forfait gratuit permanent. Les détails de l’essai peuvent changer : vérifiez directement l’offre actuelle.",
  "a9.b32": "Puis-je calculer le coût d’une réponse IA ?",
  "a9.b33": "Pas à partir d’un tarif fixe unique par réponse. L’utilisation dépend du modèle et de la consommation réelle, et les déductions suivent les conditions actuelles du portefeuille du fournisseur. Utilisez vos propres données de facturation pour établir une estimation.",
  "a9.b34": "Chatfuel est-il moins cher que ManyChat ?",
  "a9.b35": "Les prix d’abonnement publiés et les limites incluses diffèrent ; le tarif d’appel le plus bas ne permet donc pas une comparaison tout compris. Pour votre usage, ajoutez le quota de contacts ou de conversations, les canaux nécessaires, les crédits, les frais de messages, les taxes et la périodicité de facturation.",
  "a9.b36": "Puis-je transférer un bot Chatfuel vers Chatora ?",
  "a9.b37": "L’aperçu Chatora ne dispose d’aucun outil ni service de migration testé. Conservez vos exports d’origine et vérifiez que tout futur outil d’import est effectivement implémenté et testé avant de prévoir un changement.",
  "a9.r1": "Chatora et Chatfuel : comparaison datée et disponibilité actuelle",
  "a9.r2": "ManyChat ou Chatfuel : prix des forfaits et modèles de facturation",
  "a9.b38": "Sources : page tarifaire et documentation de facturation Chatfuel consultées le 28 octobre 2026, et page des tarifs WhatsApp Business Platform de Meta mise à jour le 30 septembre 2026. Les prix catalogue et conditions de facturation peuvent changer ; vérifiez les informations actuelles avant tout achat. Chatora n’est pas affilié à Chatfuel.",
});

Object.assign(window.CHATORA_I18N_PAGES.de, {
  "a9.h1": "Chatfuel-Preise erklärt (2026): Tarife, Wallet und WhatsApp-Gebühren",
  "a9.lede": "Chatfuel veröffentlicht Abonnementpreise und monatliches Guthaben; KI- und WhatsApp-Kosten können von der Nutzung abhängen. Diese datierte Übersicht trennt die veröffentlichten Tarifangaben von Kosten, die sich nach Wallet und Rechnung deines Kontos richten. Es wird weder ein undokumentierter prozentualer Aufschlag noch ein Preis je Antwort unterstellt.",
  "a9.author": "Chatora-Rechercheteam",
  "a9.date": "Aktualisiert am 28. Oktober 2026 · 8 Min. Lesezeit",
  "a9.callout": "<b>Momentaufnahme:</b> Chatfuels Preisseite nennt Business für 20 $/Monat oder umgerechnet 18 $/Monat bei jährlicher Abrechnung, mit 20 $ monatlichem Guthaben. Agency S wird mit 100 $/Monat oder umgerechnet 90 $/Monat bei jährlicher Abrechnung aufgeführt, mit 100 $ monatlichem Guthaben und drei Kundenunternehmen. Wallet-Nutzung und Meta-Nachrichtenentgelte hängen vom tatsächlichen Verbrauch ab; die veröffentlichten Seiten belegen weder eine allgemeingültige Gesamtrechnung noch die pauschale Behauptung eines Aufschlags von 10 %.",
  "a9.b1": "Inhalt",
  "a9.b2": "<a href=\"#plan\">Veröffentlichte Tarifpreise</a>",
  "a9.b3": "<a href=\"#wallet\">Was das Wallet abdeckt</a>",
  "a9.b4": "<a href=\"#estimate\">Was eine Gesamtkostenschätzung erfordert</a>",
  "a9.b5": "<a href=\"#fit\">Wofür Chatfuel geeignet sein könnte</a>",
  "a9.b6": "<a href=\"#faq\">Was du vor dem Kauf prüfen solltest</a>",
  "a9.b7": "1. Veröffentlichte Tarifpreise",
  "a9.b8": "Am 28. Oktober 2026 nannte Chatfuels öffentliche Preisseite Business für 20 $ bei monatlicher Zahlung oder umgerechnet 18 $ pro Monat bei jährlicher Abrechnung (216 $ jährlich im Voraus). Die Seite weist 20 $ monatliches Guthaben aus. Agency S wird mit 100 $ bei monatlicher Zahlung oder umgerechnet 90 $ pro Monat bei jährlicher Abrechnung (1.080 $ jährlich im Voraus) aufgeführt, mit 100 $ monatlichem Guthaben und drei Kundenunternehmen. Regionale Bedingungen und die genaue Anrechnung des Guthabens solltest du auf den Checkout- und Abrechnungsseiten des Anbieters prüfen.",
  "a9.b9": "Die Preisseite bietet eine siebentägige kostenlose Testphase; einen dauerhaft kostenlosen Tarif führt sie nicht auf. Auf der öffentlichen Tarifseite werden die enthaltenen Guthaben als KI-Guthaben beschrieben, während Chatfuels Abrechnungsdokumentation Wallet-Nutzung auch für KI- und WhatsApp-Kosten nennt. Prüfe die aktuellen Bedingungen für dein Konto und die geplanten Gebühren.",
  "a9.b10": "2. Was das Wallet abdeckt",
  "a9.b11": "Chatfuels aktuelle Abrechnungsdokumentation besagt, dass Wallet-Nutzung KI-Antworten und von Meta berechnete WhatsApp-Nachrichtenentgelte umfassen kann. Das monatliche Guthaben ist ein Budgetbeitrag, keine Zusage unbegrenzter Nutzung. Die tatsächlichen Ausgaben hängen von Anzahl und Kategorie zugestellter Nachrichten, KI-Nutzung, geltenden Gratisvolumen und den Abrechnungseinstellungen des Kontos ab.",
  "a9.tl1": "Veröffentlichte Position",
  "a9.tl2": "Öffentliche Angabe",
  "a9.tl3": "Was zu prüfen ist",
  "a9.t1": "Business-Abonnement",
  "a9.t1a": "20 $ monatlich; umgerechnet 18 $/Monat bei jährlicher Abrechnung (216 $/Jahr)",
  "a9.t1b": "Jahresabrechnung wird im Voraus bezahlt; prüfe regionale Preise und Steuern",
  "a9.t2": "Monatliches Business-Guthaben",
  "a9.t2a": "20 $ monatliches Guthaben",
  "a9.t2b": "Prüfe auf der Abrechnungsseite zulässige Wallet-Gebühren und Verlängerungsbedingungen",
  "a9.t3": "Agency S",
  "a9.t3a": "100 $ monatlich; umgerechnet 90 $/Monat bei jährlicher Abrechnung (1.080 $/Jahr)",
  "a9.t3b": "Die Preisseite nennt 100 $ monatliches Guthaben und drei Kundenunternehmen",
  "a9.t4": "WhatsApp-Nachrichten",
  "a9.t4a": "Meta-Gebühren variieren nach Kategorie und Markt des Empfängers",
  "a9.t4b": "Frage, wie der Anbieter deinem Konto Gebühren berechnet; leite keinen Aufschlag aus dem Tarif eines anderen Anbieters ab",
  "a9.t5": "Monatliche Gesamtkosten",
  "a9.t5a": "Nicht allein durch das Abonnement bestimmt",
  "a9.t5b": "Berücksichtige tatsächliches Wallet, Nachrichtenvolumen, Tarif und Rechnungsbedingungen",
  "a9.foot": "Öffentliche Seiten geprüft am 28. Oktober 2026. Preisseite und Abrechnungsdokumentation können Guthaben und Wallet-Gebühren unterschiedlich beschreiben; bestätige die geltenden Bedingungen bei Chatfuel. Metas Preisliste für Ägypten ist unten verlinkt. Hier wird weder ein Chatfuel-Aufschlag noch ein Preis je KI-Antwort unterstellt.",
  "a9.sources": "<a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Chatfuel-Preise</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Chatfuel-Abrechnungsdokumentation</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Meta-Preise für WhatsApp</a>",
  "a9.b13": "3. Was eine Gesamtkostenschätzung erfordert",
  "a9.b14": "Für eine aussagekräftige monatliche Schätzung benötigst du die erwarteten WhatsApp-Zustellungen nach Nachrichtenkategorie und Empfängerland, deine KI-Nutzung, das im Tarif enthaltene Monatsguthaben, mögliche automatische Aufladeeinstellungen und geltende Steuern. Metas Preisliste berechnet Gebühren je zugestellter Nachricht nach Kategorie und Markt und enthält ein monatliches Gratisvolumen für Servicenachrichten; Anbieterbedingungen können zusätzliche oder anders ausgewiesene Kosten vorsehen. Vergleiche Rechnungen, nicht nur Tarifüberschriften.",
  "a9.b15": "Leite aus einer einzelnen beispielhaften KI-Antwort keinen allgemeinen Preis pro Antwort ab. Tokenverbrauch und Modelleinstellungen können variieren; Wallet-Abzüge richten sich nach Chatfuels aktuellen Abrechnungsregeln. Wenn das Dashboard des Anbieters eine Nutzungsschätzung bietet, überprüfe sie vor einer Ausweitung anhand deiner tatsächlichen Rechnung.",
  "a9.b16": "4. Wofür Chatfuel geeignet sein könnte",
  "a9.b17": "Ein niedriger beworbener Abonnementpreis ist nur ein Faktor. Die aktuellen öffentlichen Seiten können Chatfuel prüfenswert machen, wenn die aufgeführten Kanäle, das Kontaktmodell, das Wallet oder Agenturtools zu deinem Arbeitsablauf passen.",
  "a9.b18": "<strong>Große Kontaktbestände.</strong> Chatfuels Hilfedokumentation nennt unbegrenzte Kontakte in den Tarifen; prüfe die aktuellen Tarifbedingungen und die Wirtschaftlichkeit der Nachrichtennutzung für deine Zielgruppe.",
  "a9.b19": "<strong>Teams, die Agenturtools vergleichen.</strong> Die Preisseite nennt bei Agency S drei Kundenunternehmen und ein Agentur-Dashboard. Vergleiche das genaue Kundenlimit und Guthaben mit der Zahl der von dir betreuten Marken.",
  "a9.b20": "<strong>Teams, die den Verbrauch überwachen.</strong> Ein Wallet macht den Verbrauch sichtbar, bedeutet aber auch, dass KI- und Messaging-Nutzung die Gesamtkosten verändern können. Prüfe Aufladeeinstellungen und Warnungen, bevor du Automatisierungen aktivierst.",
  "a9.b21": "5. Was du vor dem Kauf prüfen solltest",
  "a9.b22": "<strong>Verfallen monatliche Guthaben oder werden sie übertragen?</strong> Prüfe die aktuellen Abrechnungsbedingungen und Kontoeinstellungen, statt eine Übertragung ungenutzter Beträge anzunehmen.",
  "a9.b23": "<strong>Was passiert beim Wallet-Schwellenwert?</strong> Kläre, ob automatische Aufladung aktiviert ist, wodurch sie ausgelöst wird und wie du sie pausieren kannst.",
  "a9.b24": "<strong>Wie werden WhatsApp-Nachrichtenentgelte berechnet?</strong> Frage nach dem geltenden Tarif je Kategorie und Markt sowie einer Musterrechnung; Metas öffentliche Preisliste kann von der Abrechnungsanzeige des Anbieters abweichen.",
  "a9.b25": "<strong>Ist die Testphase ein dauerhaft kostenloser Tarif?</strong> Nein — die Preisseite nennt eine siebentägige Testphase, keinen dauerhaft kostenlosen Tarif.",
  "a9.b26": "Prüfe die aktuelle Verfügbarkeit vor dem Wechsel",
  "a9.b27": "Chatoras aktuelle Vorschau hat weder einen veröffentlichten Abonnementpreis noch Live-Messaging-Kanäle. Ein valider Gesamtkostenvergleich ist noch nicht möglich; prüfe die datierten öffentlichen Bedingungen jedes Anbieters und deine eigene Nutzung.",
  "a9.b28": "Chatoras Verfügbarkeit prüfen →",
  "a9.b29": "Häufige Fragen, kurz beantwortet",
  "a9.b30": "Hat Chatfuel einen dauerhaft kostenlosen Tarif?",
  "a9.b31": "Die am 28. Oktober 2026 geprüfte Preisseite nennt eine siebentägige kostenlose Testphase und kostenpflichtige Tarife, aber keinen dauerhaft kostenlosen Tarif. Testbedingungen können sich ändern; prüfe das aktuelle Angebot direkt beim Anbieter.",
  "a9.b32": "Kann ich die Kosten einer KI-Antwort berechnen?",
  "a9.b33": "Nicht anhand eines einzigen festen Preises je Antwort. Der Verbrauch hängt vom Modell und der tatsächlichen Nutzung ab; die aktuellen Wallet-Bedingungen des Anbieters bestimmen die Abzüge. Verwende deine eigenen Abrechnungsdaten für eine Schätzung.",
  "a9.b34": "Ist Chatfuel günstiger als ManyChat?",
  "a9.b35": "Die veröffentlichten Abonnementpreise und enthaltenen Limits unterscheiden sich; der niedrigste Einstiegspreis ist daher kein Gesamtkostenvergleich. Berücksichtige für deinen Anwendungsfall Kontakt- oder Gesprächslimits, benötigte Kanäle, Guthaben, Nachrichtenentgelte, Steuern und Abrechnungszyklus.",
  "a9.b36": "Kann ich einen Chatfuel-Bot zu Chatora übertragen?",
  "a9.b37": "Chatoras Vorschau hat kein getestetes Migrationstool und keinen getesteten Migrationsservice. Bewahre deine ursprünglichen Exporte auf und prüfe, ob ein künftiger Importer implementiert und getestet wurde, bevor du einen Wechsel planst.",
  "a9.r1": "Chatora vs. Chatfuel: datierter Vergleich und aktuelle Verfügbarkeit",
  "a9.r2": "ManyChat vs. Chatfuel: Tarifpreise und Abrechnungsmodelle",
  "a9.b38": "Quellen: Chatfuels Preisseite und Abrechnungsdokumentation, geprüft am 28. Oktober 2026, sowie Metas WhatsApp-Business-Platform-Preisseite, aktualisiert am 30. September 2026. Listenpreise und Abrechnungsbedingungen können sich ändern; prüfe die aktuellen Angaben vor dem Kauf. Chatora ist nicht mit Chatfuel verbunden.",
});

Object.assign(window.CHATORA_I18N_PAGES.pt, {
  "a9.h1": "Preços do Chatfuel explicados (2026): planos, carteira e tarifas do WhatsApp",
  "a9.lede": "O Chatfuel publica preços de assinatura e créditos mensais, enquanto as cobranças por IA e WhatsApp podem depender do uso. Esta visão datada separa os valores públicos dos planos dos custos que dependem da carteira e da fatura da sua conta. Não se presume percentual de acréscimo sem documentação nem preço por resposta.",
  "a9.author": "Equipe de pesquisa da Chatora",
  "a9.date": "Atualizado em 28 de outubro de 2026 · 8 min de leitura",
  "a9.callout": "<b>Retrato do momento:</b> a página de preços do Chatfuel lista o Business por US$ 20/mês ou equivalente a US$ 18/mês na cobrança anual, com US$ 20 em créditos mensais. O Agency S aparece por US$ 100/mês ou equivalente a US$ 90/mês na cobrança anual, com US$ 100 em créditos mensais e três empresas clientes. O uso da carteira e as tarifas de mensagens da Meta dependem do uso real; as páginas publicadas não sustentam uma fatura total universal nem uma alegação geral de acréscimo de 10%.",
  "a9.b1": "Conteúdo",
  "a9.b2": "<a href=\"#plan\">Preços dos planos publicados</a>",
  "a9.b3": "<a href=\"#wallet\">O que a carteira cobre</a>",
  "a9.b4": "<a href=\"#estimate\">O que é necessário para uma estimativa completa</a>",
  "a9.b5": "<a href=\"#fit\">Em quais casos o Chatfuel pode servir</a>",
  "a9.b6": "<a href=\"#faq\">O que verificar antes de contratar</a>",
  "a9.b7": "1. Preços dos planos publicados",
  "a9.b8": "Em 28 de outubro de 2026, a página pública de preços do Chatfuel listava o Business por US$ 20 no pagamento mensal ou equivalente a US$ 18 por mês na cobrança anual (US$ 216 cobrados por ano). A página lista US$ 20 em créditos mensais. O Agency S aparece por US$ 100 no pagamento mensal ou equivalente a US$ 90 por mês na cobrança anual (US$ 1.080 cobrados por ano), com US$ 100 em créditos mensais e três empresas clientes. Confirme os termos regionais e o tratamento exato dos créditos nas páginas de checkout e cobrança do provedor.",
  "a9.b9": "A página de preços oferece um teste grátis de sete dias; não lista um plano gratuito permanente. A página pública dos planos descreve os créditos incluídos como créditos de IA, enquanto a documentação de cobrança do Chatfuel também descreve o uso da carteira para custos de IA e WhatsApp. Confira os termos atuais aplicáveis à conta e às cobranças que espera utilizar.",
  "a9.b10": "2. O que a carteira cobre",
  "a9.b11": "A documentação atual de cobrança do Chatfuel informa que o uso da carteira pode incluir respostas de IA e tarifas de mensagens do WhatsApp cobradas pela Meta. O crédito mensal é uma contribuição para o orçamento, não uma promessa de uso ilimitado. O gasto real depende da quantidade e da categoria das mensagens entregues, do uso de IA, de eventuais franquias gratuitas e das configurações de cobrança da conta.",
  "a9.tl1": "Item publicado",
  "a9.tl2": "Informação pública",
  "a9.tl3": "O que verificar",
  "a9.t1": "Assinatura Business",
  "a9.t1a": "US$ 20 mensal; equivalente a US$ 18/mês na cobrança anual (US$ 216/ano)",
  "a9.t1b": "A cobrança anual é paga antecipadamente; confirme preço regional e impostos",
  "a9.t2": "Crédito mensal do Business",
  "a9.t2a": "US$ 20 em créditos mensais",
  "a9.t2b": "Consulte a página de cobrança para ver cobranças elegíveis da carteira e termos de renovação",
  "a9.t3": "Agency S",
  "a9.t3a": "US$ 100 mensal; equivalente a US$ 90/mês na cobrança anual (US$ 1.080/ano)",
  "a9.t3b": "A página de preços lista US$ 100 em créditos mensais e três empresas clientes",
  "a9.t4": "Mensagens do WhatsApp",
  "a9.t4a": "As tarifas da Meta variam conforme a categoria e o mercado do destinatário",
  "a9.t4b": "Pergunte como o provedor cobra da sua conta; não deduza um acréscimo com base na tarifa de outro provedor",
  "a9.t5": "Total mensal completo",
  "a9.t5a": "Não é determinado apenas pela assinatura",
  "a9.t5b": "Considere a carteira real, o volume de mensagens, o plano e os termos da fatura",
  "a9.foot": "Páginas públicas consultadas em 28 de outubro de 2026. A página de preços e a documentação de cobrança podem descrever créditos e cobranças da carteira de maneiras diferentes; confirme com o Chatfuel os termos aplicáveis. A tabela de tarifas da Meta para o Egito está vinculada abaixo. Não se presume aqui acréscimo do Chatfuel nem custo por resposta de IA.",
  "a9.sources": "<a href=\"https://chatfuel.com/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do Chatfuel</a> · <a href=\"https://chatfuel.com/docs/billing/chatfuel-plans-and-pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Documentação de cobrança do Chatfuel</a> · <a href=\"https://developers.facebook.com/documentation/business-messaging/whatsapp/pricing\" rel=\"noopener noreferrer\" target=\"_blank\">Preços do WhatsApp da Meta</a>",
  "a9.b13": "3. O que é necessário para uma estimativa completa",
  "a9.b14": "Para uma estimativa mensal útil, reúna o volume esperado de mensagens do WhatsApp entregues por categoria e país do destinatário, o uso de IA, o crédito mensal incluído no plano, eventuais configurações de recarga automática e os impostos aplicáveis. A tabela da Meta cobra por mensagem entregue, de acordo com categoria e mercado, e oferece uma franquia mensal gratuita para mensagens de serviço; os termos de cobrança do provedor podem ser adicionais ou apresentados de outra forma. Compare as faturas, não apenas os títulos dos planos.",
  "a9.b15": "Não transforme uma resposta de IA de exemplo em um preço universal por resposta. O uso de tokens e as configurações do modelo podem variar, e os débitos da carteira dependem das regras atuais de cobrança do Chatfuel. Se o painel do provedor oferecer uma estimativa de uso, valide-a com sua fatura real antes de ampliar a operação.",
  "a9.b16": "4. Em quais casos o Chatfuel pode servir",
  "a9.b17": "Um preço inicial baixo da assinatura é apenas um dos fatores. As páginas públicas atuais podem tornar o Chatfuel digno de avaliação se os canais listados, o modelo de contatos, a carteira ou as ferramentas de agência combinarem com seu fluxo de trabalho.",
  "a9.b18": "<strong>Grandes bases de contatos.</strong> A documentação de ajuda do Chatfuel lista contatos ilimitados nos planos; verifique os termos atuais e a economia do uso de mensagens para seu público.",
  "a9.b19": "<strong>Equipes comparando ferramentas para agências.</strong> A página de preços lista o Agency S com três empresas clientes e um painel de agência. Compare o limite exato de clientes e a franquia de créditos com a quantidade de marcas que você gerencia.",
  "a9.b20": "<strong>Equipes que monitoram o uso.</strong> A carteira deixa o consumo visível, mas também significa que o uso de IA e mensagens pode alterar o total. Revise as configurações de recarga e os alertas antes de habilitar automações.",
  "a9.b21": "5. O que verificar antes de contratar",
  "a9.b22": "<strong>Os créditos mensais acumulam?</strong> Consulte os termos atuais de cobrança e as configurações da conta em vez de presumir que saldos não utilizados serão transferidos.",
  "a9.b23": "<strong>O que acontece ao atingir o limite da carteira?</strong> Confirme se a recarga automática está ativada, como ela é acionada e como pausá-la.",
  "a9.b24": "<strong>Como são cobradas as tarifas de mensagens do WhatsApp?</strong> Peça a tarifa aplicável por categoria e mercado e uma fatura de exemplo; a tabela pública da Meta pode diferir da cobrança exibida pelo provedor.",
  "a9.b25": "<strong>O teste grátis é um plano gratuito permanente?</strong> Não — a página de preços lista um teste de sete dias, não um nível de assinatura gratuita permanente.",
  "a9.b26": "Compare a disponibilidade atual antes de mudar",
  "a9.b27": "A prévia atual da Chatora não tem preço de assinatura publicado nem canais de mensagens ao vivo. Ainda não há uma comparação válida do custo total; consulte os termos públicos datados de cada provedor e seu próprio uso.",
  "a9.b28": "Consultar disponibilidade da Chatora →",
  "a9.b29": "Perguntas frequentes, em resumo",
  "a9.b30": "O Chatfuel tem um plano gratuito permanente?",
  "a9.b31": "A página de preços consultada em 28 de outubro de 2026 lista um teste grátis de sete dias e planos pagos; não lista um plano gratuito permanente. Os detalhes do teste podem mudar, portanto confira a oferta atual diretamente.",
  "a9.b32": "Posso calcular o custo de uma resposta de IA?",
  "a9.b33": "Não com base em um único valor fixo por resposta. O uso depende do modelo e do consumo real, e os termos atuais da carteira do provedor determinam os débitos. Use seus próprios dados de cobrança para estimar.",
  "a9.b34": "O Chatfuel é mais barato que o ManyChat?",
  "a9.b35": "Os preços de assinatura e os limites incluídos são diferentes; portanto, o menor preço inicial não representa uma comparação completa. Para seu caso de uso, some a franquia de contatos ou conversas, os canais necessários, os créditos, as tarifas de mensagens, os impostos e o ciclo de cobrança.",
  "a9.b36": "Posso transferir um bot do Chatfuel para a Chatora?",
  "a9.b37": "A prévia da Chatora não tem ferramenta nem serviço de migração testados. Guarde suas exportações originais e confirme que qualquer importador futuro foi implementado e testado antes de planejar a mudança.",
  "a9.r1": "Chatora vs. Chatfuel: comparação datada e disponibilidade atual",
  "a9.r2": "ManyChat vs. Chatfuel: preços dos planos e modelos de cobrança",
  "a9.b38": "Fontes: página de preços e documentação de cobrança do Chatfuel consultadas em 28 de outubro de 2026, e página de preços do WhatsApp Business Platform da Meta atualizada em 30 de setembro de 2026. Preços de lista e termos de cobrança podem mudar; confirme os detalhes atuais antes de comprar. A Chatora não é afiliada ao Chatfuel.",
});

